// Own profile (view first; Edit opens the form) or, with ?id=, another member's profile with Block / Report.
import React, { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Platform, Pressable, Text, View } from 'react-native';
import { router, Stack, useLocalSearchParams, useSegments } from 'expo-router';
import * as ImagePicker from 'expo-image-picker';
import { Avatar, Button, EmptyState, Field, FieldGrid, HighlightPanel, ListRow, ListView, Page, SectionCard, StatusPill, styles } from '../components/ui';
import { BiometricSetting } from '../components/biometric-setting';
import { ReportDialog } from '../components/Prompt';
import { MeetupBadge, MeetupConnect, MeetupProConnect } from '../components/MeetupLink';
import { listGroups } from '../lib/groups';
import { meetupGroupsForPro, type MeetupProGroup } from '../lib/meetup-url';
import { colors, fonts, fs } from '../lib/theme';
import { confirmUsername, blockUser, ensureMyProfile, getProfile, isBanned, listBlocked, openDm, setBan, report, unblockUser, updateProfile, uploadAvatar } from '../lib/api';
import { useSession } from '../lib/session';
import { usePresence } from '../lib/presence';
import { supabase } from '../lib/supabase';
import { setDemo } from '../lib/demo';
import { fullName, handle, normalizeUsername, primaryName, validateUsername } from '../lib/names';
import type { Profile } from '../lib/types';

function UsernamePrompt({ handleText, onKeep }: { handleText: string; onKeep: () => void }) {
  return (
    <View style={{ backgroundColor: colors.goldSoft, borderRadius: 6, padding: 12, marginBottom: 14, gap: 6 }}>
      <Text style={[styles.body, { fontFamily: fonts.sansMedium }]}>Pick a username</Text>
      <Text style={[styles.muted, { fontSize: fs(13) }]}>We gave you {handleText} for now. Choose your own below, or keep it.</Text>
      <Text onPress={onKeep} accessibilityRole="button" style={[styles.link, { fontSize: fs(13) }]}>Keep {handleText}</Text>
    </View>
  );
}

function ProfileFacts({ rows }: { rows: [string, string][] }) {
  return (
    <View style={{ gap: 14 }}>
      {rows.map(([label, value]) => (
        <View key={label} style={{ borderBottomWidth: 1, borderBottomColor: colors.line, paddingBottom: 8 }}>
          <Text style={styles.fieldLabel}>{label}</Text>
          <Text style={styles.fieldValue}>{value}</Text>
        </View>
      ))}
    </View>
  );
}

export default function ProfileScreen() {
  const params = useLocalSearchParams<{ id?: string; meetup?: string; meetup_pro?: string; reason?: string }>();
  const { userId, isModerator, demo } = useSession();
  const { online } = usePresence();
  // This screen is also the Profile tab. A stack title replaces the tab label and truncates it, so the tab sets none.
  const inTab = useSegments()[0] === '(tabs)';
  const targetId = params.id ?? userId;
  const isMe = targetId === userId;
  const [p, setP] = useState<Profile | null>(null);
  const [name, setName] = useState(''); const [username, setUsername] = useState(''); const [bio, setBio] = useState('');
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false); const [msg, setMsg] = useState<string | null>(null);
  const editingRef = useRef(false);
  editingRef.current = editing;
  const shownId = useRef<string | null>(null);
  shownId.current = p?.id ?? null;
  const [isBlocked, setIsBlocked] = useState(false); const [banned, setBanned] = useState(false); const [reporting, setReporting] = useState(false);
  const [messaging, setMessaging] = useState(false);
  const [phase, setPhase] = useState<'loading' | 'ready' | 'error'>('loading');
  const [loadError, setLoadError] = useState<string | null>(null);

  const [reload, setReload] = useState(0);
  const [proGroups, setProGroups] = useState<MeetupProGroup[]>([]);
  const proNote = typeof params.meetup_pro === 'string' ? params.meetup_pro : null;
  const meetupNote = params.meetup === 'linked'
    ? (proNote ? `Meetup Pro connected for ${proNote}.` : 'Meetup connected.')
    : params.meetup === 'error' ? (params.reason === 'already_linked' ? 'That Meetup account is linked to another member.' : 'Meetup connection didn’t complete.') : null;
  useEffect(() => {
    if (!isMe || demo || !userId) { setProGroups([]); return; }
    let live = true;
    listGroups(isModerator)
      .then((rows) => { if (live) setProGroups(meetupGroupsForPro(rows, userId, isModerator)); })
      .catch(() => { if (live) setProGroups([]); });
    return () => { live = false; };
  }, [isMe, demo, userId, isModerator, reload]);
  useEffect(() => {
    if (!targetId) { if (!userId) router.replace('/sign-in'); return; }
    let live = true;
    const switching = shownId.current !== targetId;
    if (switching) {
      setPhase('loading');
      setLoadError(null);
      setEditing(false);
      setMsg(null);
    }
    (async () => {
      try {
        let x = await getProfile(targetId, true);
        // Signup should insert a row. If it didn't, create it now so the tab isn't blank.
        if (!x && isMe && userId && !demo) {
          await ensureMyProfile();
          x = await getProfile(targetId, true);
        }
        if (!live) return;
        if (!x) {
          setP(null);
          setPhase('error');
          setLoadError(isMe ? 'Your profile isn’t available yet.' : 'This member has no profile.');
          return;
        }
        setP(x);
        if (switching || !editingRef.current) {
          setName(x.display_name ?? '');
          setUsername(x.username ?? '');
          setBio(x.bio ?? '');
        }
        setPhase('ready');
      } catch (e: any) {
        if (!live) return;
        if (!switching && shownId.current === targetId) {
          setMsg(e?.message || 'Couldn’t refresh this profile.');
          setPhase('ready');
          return;
        }
        setP(null);
        setPhase('error');
        setLoadError(e?.message || 'Couldn’t load this profile.');
      }
    })();
    if (!isMe) listBlocked().then((b) => { if (live) setIsBlocked(b.includes(targetId)); }).catch(() => {});
    if (!isMe && isModerator && !demo) isBanned(targetId).then((v) => { if (live) setBanned(v); }).catch(() => {});
    return () => { live = false; };
  }, [targetId, reload, isModerator, isMe, userId, demo]);

  const fillForm = (x: Profile) => {
    setName(x.display_name ?? '');
    setUsername(x.username ?? '');
    setBio(x.bio ?? '');
  };
  const startEdit = () => {
    if (!p) return;
    fillForm(p);
    setMsg(null);
    setEditing(true);
  };
  const cancelEdit = () => {
    if (p) fillForm(p);
    setMsg(null);
    setEditing(false);
  };
  const keepUsername = async () => {
    try { await confirmUsername(userId!); setReload((n) => n + 1); }
    catch (e: any) { setMsg(e.message); }
  };

  const save = async () => {
    const uErr = validateUsername(username);
    if (uErr) { setMsg(uErr); return; }
    setSaving(true); setMsg(null);
    try {
      const u = normalizeUsername(username);
      const display_name = name.trim() || null;
      const nextBio = bio.trim();
      await updateProfile(userId!, { ...(u !== p?.username ? { username: u } : {}), display_name, bio: nextBio });
      setUsername(u);
      setName(display_name ?? '');
      setBio(nextBio);
      setP((cur) => (cur ? {
        ...cur,
        username: u,
        display_name,
        bio: nextBio,
        username_confirmed: u !== cur.username ? true : cur.username_confirmed,
      } : cur));
      setMsg('Saved.');
      setEditing(false);
      setReload((n) => n + 1);
    } catch (e: any) { setMsg(e.message); } finally { setSaving(false); }
  };

  const pickAvatar = async () => {
    const r = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], allowsEditing: true, aspect: [1, 1], quality: 0.7 });
    if (r.canceled || !r.assets[0]) return;
    try {
      const path = await uploadAvatar(userId!, r.assets[0].uri, r.assets[0].mimeType ?? 'image/jpeg');
      await updateProfile(userId!, { avatar_path: path });
      setP((cur) => (cur ? { ...cur, avatar_path: path } : cur));
    } catch (e: any) { setMsg(e.message); }
  };

  const signOut = async () => { if (demo) { setDemo(false); } else { await supabase.auth.signOut(); } router.replace('/sign-in'); if (Platform.OS === 'web' && demo) window.location.href = `${process.env.EXPO_BASE_URL ?? ''}/`; };

  const messageThem = async () => {
    if (!p || isMe) return;
    setMessaging(true); setMsg(null);
    try { router.push(`/rooms/${await openDm(p.id)}`); }
    catch (e: any) { setMsg(e.message); }
    finally { setMessaging(false); }
  };

  // Sign out lives only on this screen. Guidelines stay on the sign-in agreement, so they are not repeated here.
  const leave = !userId || isMe ? (
    <Pressable onPress={userId ? signOut : () => router.replace('/sign-in')} accessibilityRole="button" style={{ alignSelf: 'flex-start' }}>
      <Text style={[styles.rowPrimary, { color: userId && !demo ? colors.danger : colors.navy }]}>{!userId ? 'Sign in' : demo ? 'Exit demo' : 'Sign out'}</Text>
    </Pressable>
  ) : null;
  if (phase === 'loading') {
    return (
      <Page>
        {inTab ? null : <Stack.Screen options={{ title: '' }} />}
        <View style={{ paddingVertical: 28, alignItems: 'center' }}><ActivityIndicator color={colors.navy} /></View>
        {leave}
      </Page>
    );
  }
  if (!p) {
    return (
      <Page>
        {inTab ? null : <Stack.Screen options={{ title: '' }} />}
        <EmptyState icon="alert-circle-outline" title="Couldn’t load this profile" body={loadError ?? 'Something went wrong.'}
          action={<Button title="Retry" onPress={() => { setPhase('loading'); setReload((n) => n + 1); }} />} />
        {leave}
      </Page>
    );
  }
  const isOnline = online.some((u) => u.user_id === p.id);

  const mod = isModerator && !demo;
  const meetupValue = isMe ? (
    <View style={{ gap: 8, alignItems: 'flex-start' }}>
      <MeetupConnect p={p} onChange={() => setReload((n) => n + 1)}
        note={p.meetup_name && proGroups.length ? 'This removes the member link only. Meetup Pro connections stay until you disconnect that group.' : null} />
      {meetupNote ? <Text style={[styles.muted, { fontSize: fs(13) }]}>{meetupNote}</Text> : null}
    </View>
  ) : (p.meetup_name ?? 'Not connected');
  const proValue = proGroups.length ? (
    <MeetupProConnect groups={proGroups} onChange={() => setReload((n) => n + 1)} />
  ) : null;
  return (
    <Page>
      {inTab ? null : <Stack.Screen options={{ title: primaryName(p) }} />}
      <HighlightPanel title={primaryName(p)} subtitle={p.display_name?.trim() ? handle(p) : null}
        media={<Pressable onPress={isMe && editing ? pickAvatar : undefined} disabled={!isMe || !editing} accessibilityLabel={isMe && editing ? 'Change photo' : undefined}>
          <Avatar name={primaryName(p)} path={p.avatar_path} userId={p.id} size={64} online={isOnline} /></Pressable>}
        pills={<>
          {isOnline ? <StatusPill label="Online" tone="success" /> : null}
          {isMe && isModerator ? <StatusPill label="Moderator" tone="gold" /> : null}
          {p.meetup_is_member ? <StatusPill label="Meetup member" tone="info" /> : null}
          {!isMe && mod && banned ? <StatusPill label="Banned" tone="danger" /> : null}
        </>}
        actions={isMe ? (
          editing
            ? <Button small variant="neutral" icon="camera-outline" title={p.avatar_path ? 'Change photo' : 'Add photo'} onPress={pickAvatar} />
            : <Button small variant="neutral" icon="create-outline" title="Edit" onPress={startEdit} />
        ) : <>
          {!isBlocked ? <Button small icon="chatbubble-outline" title="Message" onPress={messageThem} loading={messaging} /> : null}
          <Button small variant="neutral" icon="flag-outline" title="Report" onPress={() => setReporting(true)} />
          <Button small variant="danger" title={isBlocked ? 'Unblock' : 'Block'} onPress={async () => {
            if (isBlocked) { await unblockUser(userId!, p.id); setIsBlocked(false); } else { await blockUser(userId!, p.id); setIsBlocked(true); }
          }} />
          {mod ? <Button small variant={banned ? 'neutral' : 'destructive'} icon="ban-outline" title={banned ? 'Unban' : 'Ban'} onPress={async () => {
            try { await setBan(p.id, !banned); setBanned(!banned); } catch (e: any) { setMsg(e.message); }
          }} /> : null}
        </>}
        fields={isMe
          ? (proValue ? [['Meetup', meetupValue], ['Meetup Pro', proValue]] : [['Meetup', meetupValue]])
          : [['Username', handle(p)], ['Meetup', meetupValue]]}>
        {isMe ? (editing ? (
          <>
            {p.username_confirmed === false ? <UsernamePrompt handleText={handle(p)} onKeep={keepUsername} /> : null}
            <Field label="Username" value={username} onChangeText={(v) => setUsername(normalizeUsername(v))} maxLength={25}
              placeholder="@your_name" autoCapitalize="none" autoCorrect={false}
              help={`@${normalizeUsername(username) || 'username'} · 3–24 lowercase letters, numbers, underscores`} />
            <Field label="Display name (optional)" value={name} onChangeText={setName} maxLength={50} placeholder="How friends know you" />
            <Field label="Bio" value={bio} onChangeText={setBio} multiline maxLength={280} />
            <View style={{ flexDirection: 'row', gap: 10, alignItems: 'center', flexWrap: 'wrap' }}>
              <Button title="Save" onPress={save} loading={saving} />
              <Button variant="neutral" title="Cancel" onPress={cancelEdit} disabled={saving} />
              {msg ? <Text style={[styles.muted, { fontSize: fs(13), flexShrink: 1 }]}>{msg}</Text> : null}
            </View>
          </>
        ) : (
          <>
            <ProfileFacts rows={[
              ['Username', handle(p)],
              ['Display name', p.display_name?.trim() || '—'],
              ['Bio', p.bio?.trim() || '—'],
            ]} />
            {msg ? <Text style={[styles.muted, { fontSize: fs(13) }]}>{msg}</Text> : null}
          </>
        )) : null}
      </HighlightPanel>
      {msg && !isMe ? <Text style={[styles.muted, { fontSize: fs(13) }]}>{msg}</Text> : null}

      {isMe && !demo ? <BiometricSetting /> : null}

      {!isMe ? (
        <SectionCard title="About">
          <FieldGrid fields={[['Bio', p.bio || '—']]} />
        </SectionCard>
      ) : null}

      {!isMe && p.meetup_name ? <SectionCard title="Meetup"><MeetupBadge p={p} /></SectionCard> : null}

      {isMe && mod ? (
        <ListView title="Analytics">
          <ListRow onPress={() => router.push('/me/analytics')} accessibilityLabel="Site and app traffic">
            <Text style={styles.rowPrimary}>Site and app traffic</Text>
          </ListRow>
        </ListView>
      ) : null}

      {leave}
      <ReportDialog visible={reporting} subject={fullName(p)} onClose={() => setReporting(false)} onSubmit={(reason) => report({ userId: p.id, reason })} />
    </Page>
  );
}
