// Owner on an event or group record. Same face as an RSVP row, and the same
// profile route as a People row: /profile?id=<user id>.
import { Pressable, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { router } from 'expo-router';
import { PersonFace } from './ui';
import { primaryName } from '../lib/names';
import { colors } from '../lib/theme';
import type { Profile } from '../lib/types';

export function OwnerFace({ profile }: { profile: Profile }) {
  const name = primaryName(profile);
  return (
    <Pressable
      onPress={() => router.push(`/profile?id=${profile.id}`)}
      accessibilityRole="link"
      accessibilityLabel={name}
      style={({ pressed }) => [{ alignSelf: 'flex-start', maxWidth: '100%', borderRadius: 6, paddingVertical: 2, paddingRight: 4 }, pressed ? { backgroundColor: colors.rowHover } : null]}
    >
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 2, minWidth: 0 }}>
        <PersonFace name={name} path={profile.avatar_path} userId={profile.id} />
        <Ionicons name="chevron-forward" size={14} color={colors.faint} />
      </View>
    </Pressable>
  );
}
