// Sanitized description: HTML or markdown becomes text runs. Scripts are not executed.
// Anchors and bare http(s) URLs are real links. javascript: and data: never are.
import React from 'react';
import { Linking, Platform, Text, View } from 'react-native';
import { parseRichText, safeHref, type Block, type Inline } from '../lib/rich-text';
import { colors, fonts, fs } from '../lib/theme';
import { styles } from './ui';

const linkStyle = {
  color: colors.link,
  textDecorationLine: 'underline' as const,
  textDecorationColor: colors.link,
  // The web text style sets text-decoration: none. The shorthand has to be set
  // again or the underline loses to that rule.
  ...(Platform.OS === 'web' ? { textDecoration: 'underline' } : {}),
};

function LinkRun({ href, children }: { href: string; children: React.ReactNode }) {
  const web = Platform.OS === 'web';
  // react-native-web turns href into an <a target="_blank">. Native Text has no href, so the press opens it.
  const anchor = web ? { href, hrefAttrs: { target: '_blank', rel: 'noopener noreferrer' } } : {};
  return (
    <Text accessibilityRole="link" style={linkStyle} {...anchor}
      onPress={() => { if (!web) Linking.openURL(href).catch(() => {}); }}>
      {children}
    </Text>
  );
}

function Runs({ nodes }: { nodes: Inline[] }) {
  return <>
    {nodes.map((n, i) => {
      if (n.t === 'text') return n.v;
      if (n.t === 'code') return <Text key={i}>{n.v}</Text>;
      if (n.t === 'strong') return <Text key={i} style={{ fontFamily: fonts.sansBold }}><Runs nodes={n.c} /></Text>;
      if (n.t === 'em') return <Text key={i} style={{ fontStyle: 'italic' }}><Runs nodes={n.c} /></Text>;
      const href = safeHref(n.href);
      if (!href) return <Runs key={i} nodes={n.c} />;
      return <LinkRun key={i} href={href}><Runs nodes={n.c} /></LinkRun>;
    })}
  </>;
}

function BlockText({ block }: { block: Block }) {
  if (block.t === 'h') {
    const size = block.level === 1 ? fs(18) : block.level === 2 ? fs(16) : fs(15);
    return <Text selectable style={{ fontFamily: fonts.sansBold, color: colors.navyDark, fontSize: size, lineHeight: size + 6 }}><Runs nodes={block.c} /></Text>;
  }
  if (block.t === 'ul' || block.t === 'ol') {
    return (
      <View style={{ gap: 4 }}>
        {block.items.map((item, i) => (
          <Text key={i} selectable style={styles.body}>
            {block.t === 'ol' ? `${i + 1}. ` : '• '}<Runs nodes={item} />
          </Text>
        ))}
      </View>
    );
  }
  return <Text selectable style={styles.body}><Runs nodes={block.c} /></Text>;
}

export function RichText({ source }: { source: string }) {
  const blocks = React.useMemo(() => parseRichText(source), [source]);
  if (!blocks.length) return null;
  return <View style={{ gap: 10 }}>{blocks.map((b, i) => <BlockText key={i} block={b} />)}</View>;
}
