// Session unlock policy. Google, Apple, and email stay the identity providers.
// Biometrics only re-open a session that is already on the device.
// Web never locks. A cold start locks when the member opted in. Background
// under a minute does not: the Face ID sheet and Control Center are `inactive`,
// not `background`, so they must not start the timer.

export const LOCK_AFTER_BACKGROUND_MS = 60_000;

export type BiometricKind = 'face' | 'fingerprint' | 'iris';

export type UnlockMethod = {
  /** Short name used in a sentence: "Face ID", "fingerprint", "face unlock". */
  name: string;
  /** Profile switch title. */
  toggle: string;
  /** OS prompt. Kept stable so a late hardware read cannot change it mid-prompt. */
  prompt: string;
  /** Lock screen line under the product name. */
  detail: string;
};

export type GateInput = {
  platform: string;
  demo: boolean;
  /** False until the restored session and the on-device preference have been read. */
  preferenceKnown: boolean;
  hasSession: boolean;
  enabled: boolean;
  unlocked: boolean;
  pathname?: string | null;
};

export type GateDecision = 'show-app' | 'lock' | 'hold';

export type AuthNotice = { event: string; userId: string | null };

export type LockSnapshot = { phase: 'open' | 'locked'; userId: string | null };

const KIND_ORDER: BiometricKind[] = ['face', 'fingerprint', 'iris'];

const IOS_NAME: Record<BiometricKind, string> = {
  face: 'Face ID',
  fingerprint: 'Touch ID',
  iris: 'Iris',
};

const ANDROID_NAME: Record<BiometricKind, string> = {
  face: 'face unlock',
  fingerprint: 'fingerprint',
  iris: 'iris',
};

export function orderedKinds(kinds: readonly BiometricKind[]): BiometricKind[] {
  const have = new Set(kinds);
  return KIND_ORDER.filter((kind) => have.has(kind));
}

function joinNames(names: string[]): string {
  if (names.length <= 1) return names[0] ?? 'biometrics';
  if (names.length === 2) return `${names[0]} or ${names[1]}`;
  return `${names.slice(0, -1).join(', ')}, or ${names[names.length - 1]}`;
}

/** Platform copy. Face ID and Touch ID are Apple names; Android says face unlock or fingerprint. */
export function unlockMethod(platform: string, kinds: readonly BiometricKind[]): UnlockMethod {
  const names = orderedKinds(kinds).map((kind) => (platform === 'ios' ? IOS_NAME[kind] : ANDROID_NAME[kind]));
  const name = names.length ? joinNames(names) : 'biometrics';
  return {
    name,
    toggle: `Unlock with ${name}`,
    prompt: 'Unlock Gnosis Events',
    detail: `Use ${name} to open your session.`,
  };
}

export function unavailableReason(input: {
  platform: string;
  hasHardware: boolean;
  enrolled: boolean;
  kinds: readonly BiometricKind[];
}): string | null {
  if (input.platform === 'web') return null;
  if (!input.hasHardware) {
    return input.platform === 'ios'
      ? 'This device doesn’t support Face ID or Touch ID.'
      : 'This phone doesn’t have a fingerprint sensor or face unlock.';
  }
  if (input.enrolled) return null;
  const kinds = orderedKinds(input.kinds);
  if (input.platform === 'ios') {
    if (kinds.length === 1 && kinds[0] === 'face') return 'Set up Face ID in Settings to use this.';
    if (kinds.length === 1 && kinds[0] === 'fingerprint') return 'Set up Touch ID in Settings to use this.';
    return 'Set up Face ID or Touch ID in Settings to use this.';
  }
  if (kinds.length === 1 && kinds[0] === 'fingerprint') return 'Add a fingerprint in system settings to use this.';
  if (kinds.length === 1 && kinds[0] === 'face') return 'Set up face unlock in system settings to use this.';
  if (kinds.length === 1 && kinds[0] === 'iris') return 'Set up iris unlock in system settings to use this.';
  return 'Add a fingerprint or face unlock in system settings to use this.';
}

/** Sign-in and the OAuth/magic-link callback stay reachable while the session is locked. */
export function isAuthRoute(pathname: string | null | undefined): boolean {
  if (!pathname) return false;
  let path = pathname.split('?')[0]?.split('#')[0] ?? '';
  if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
  if (path && !path.startsWith('/')) path = `/${path}`;
  return path === '/sign-in' || path === '/auth-callback';
}

/**
 * `hold` covers the signed-in UI until we know whether this device opted in,
 * so a restored session cannot flash events before the prompt.
 * Auth routes stay visible so a magic link can finish.
 */
export function gateDecision(input: GateInput): GateDecision {
  if (input.platform === 'web' || input.demo) return 'show-app';
  if (isAuthRoute(input.pathname)) return 'show-app';
  if (!input.preferenceKnown) return 'hold';
  if (!input.hasSession) return 'show-app';
  if (input.enabled && !input.unlocked) return 'lock';
  return 'show-app';
}

export function restoredPhase(userId: string | null, enabled: boolean): 'open' | 'locked' {
  return userId && enabled ? 'locked' : 'open';
}

/**
 * supabase-js emits SIGNED_IN when it recovers a stored session, not only when
 * the member just authenticated. Events seen before getSession resolves are
 * that recovery. A SIGNED_IN for someone else, or when nothing was stored, is
 * a real sign-in and must not show the lock (first signup, or the account fallback).
 */
export function reduceBootQueue(restoredUserId: string | null, enabled: boolean, queued: readonly AuthNotice[]): LockSnapshot {
  let userId = restoredUserId;
  let phase = restoredPhase(userId, enabled);
  for (const notice of queued) {
    if (notice.event === 'SIGNED_OUT') {
      userId = null;
      phase = 'open';
      continue;
    }
    if (notice.event !== 'SIGNED_IN') continue;
    const hydration = !!notice.userId && notice.userId === restoredUserId && userId === restoredUserId;
    if (hydration) continue;
    userId = notice.userId;
    phase = 'open';
  }
  return { phase, userId };
}

/** After startup, a new SIGNED_IN is the account fallback and counts as an unlock. Token refresh does not. */
export function reduceRuntimeEvent(state: LockSnapshot, notice: AuthNotice): LockSnapshot {
  if (notice.event === 'SIGNED_OUT') return { phase: 'open', userId: null };
  if (notice.event === 'SIGNED_IN') return { phase: 'open', userId: notice.userId };
  return state;
}

export function shouldRelock(input: {
  enabled: boolean;
  hasSession: boolean;
  authenticating: boolean;
  backgroundedAt: number | null;
  now: number;
  lockAfterMs?: number;
}): boolean {
  if (!input.enabled || !input.hasSession || input.authenticating) return false;
  if (input.backgroundedAt == null) return false;
  const limit = input.lockAfterMs ?? LOCK_AFTER_BACKGROUND_MS;
  return input.now - input.backgroundedAt >= limit;
}

/** `inactive` is the biometric sheet or a shade. Only `background` starts the lock timer. */
export function onAppState(input: {
  next: string;
  now: number;
  authenticating: boolean;
  backgroundedAt: number | null;
  enabled: boolean;
  hasSession: boolean;
  lockAfterMs?: number;
}): { backgroundedAt: number | null; relock: boolean } {
  if (input.authenticating) return { backgroundedAt: input.backgroundedAt, relock: false };
  if (input.next === 'background') return { backgroundedAt: input.now, relock: false };
  if (input.next === 'active') {
    const relock = shouldRelock(input);
    return { backgroundedAt: null, relock };
  }
  return { backgroundedAt: input.backgroundedAt, relock: false };
}

export function unlockFailureMessage(error: string | null | undefined, methodName: string): string {
  const name = methodName ? methodName.charAt(0).toUpperCase() + methodName.slice(1) : 'Biometrics';
  switch (error) {
    case 'user_cancel':
    case 'system_cancel':
    case 'app_cancel':
      return `${name} was canceled.`;
    case 'user_fallback':
      return `Use your account to sign in. ${name} doesn’t accept the device passcode here.`;
    case 'lockout':
      return `${name} is temporarily locked. Try again later, or sign in with your account.`;
    case 'not_enrolled':
    case 'not_available':
    case 'passcode_not_set':
      return `${name} isn’t available on this phone.`;
    case 'authentication_failed':
      return `${name} didn’t match. Try again.`;
    default:
      return `Couldn’t unlock with ${methodName || 'biometrics'}.`;
  }
}

/** SecureStore keys are alphanumeric plus ".", "-", and "_". UUIDs already fit. */
export function biometricStorageKey(kind: 'enabled' | 'marker', userId: string): string | null {
  const id = userId.trim().replace(/[^A-Za-z0-9._-]/g, '');
  if (!id || id.length > 80) return null;
  const prefix = kind === 'enabled' ? 'nycpprc.bio.enabled' : 'nycpprc.bio.marker';
  return `${prefix}.${id}`;
}

/** Short-lived proof that this device unlocked this member. Not a password and not an OAuth token. */
export function encodeUnlockMarker(marker: { at: number; token: string }): string {
  return `${marker.at}.${marker.token}`;
}

export function decodeUnlockMarker(raw: string | null | undefined): { at: number; token: string } | null {
  if (!raw) return null;
  const match = /^(\d{10,16})\.([0-9a-f-]{36})$/i.exec(raw.trim());
  if (!match) return null;
  return { at: Number(match[1]), token: match[2] };
}
