// Shared send bar for a direct message and the Socrates thread.
import React from 'react';
import { ActivityIndicator, Platform, Pressable, Text, TextInput, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { colors, fonts, fs } from '../lib/theme';
import { useKeyboardInset } from './keyboard-safe-screen';

export function ChatComposer({
  value, onChangeText, onSend, sending, placeholder, error, blocked, includeSafeArea,
}: {
  value: string;
  onChangeText: (value: string) => void;
  onSend: () => void;
  sending?: boolean;
  placeholder: string;
  error?: string | null;
  /** Replaces the field when the member cannot send. */
  blocked?: string | null;
  /** Pad for the home indicator. Off when a tab bar already sits underneath. */
  includeSafeArea?: boolean;
}) {
  const insets = useSafeAreaInsets();
  const keyboard = useKeyboardInset();
  const canSend = !!value.trim() && !sending;
  const send = () => { if (canSend) onSend(); };
  return (
    <View style={{
      backgroundColor: '#fff',
      borderTopWidth: 1,
      borderTopColor: colors.line,
      paddingHorizontal: 12,
      paddingTop: 10,
      // The home indicator sits under the keyboard, so don't pad for it while typing.
      paddingBottom: 10 + (includeSafeArea && !keyboard.open ? insets.bottom : 0),
    }}>
      <View style={{ width: '100%', maxWidth: 840, alignSelf: 'center' }}>
        {error ? <Text style={{ color: colors.danger, fontFamily: fonts.sans, fontSize: fs(13), marginBottom: 8 }}>{error}</Text> : null}
        {blocked ? (
          <Text style={{ color: colors.muted, fontFamily: fonts.sans, fontSize: fs(14), textAlign: 'center', paddingVertical: 8 }}>{blocked}</Text>
        ) : (
          <View style={{
            flexDirection: 'row',
            alignItems: 'flex-end',
            gap: 8,
            backgroundColor: colors.paper,
            borderWidth: 1,
            borderColor: colors.lineStrong,
            borderRadius: 24,
            paddingLeft: 16,
            paddingRight: 6,
            paddingVertical: 6,
          }}>
            <TextInput
              testID="chat-composer"
              value={value}
              onChangeText={onChangeText}
              placeholder={placeholder}
              placeholderTextColor="#9aa1ad"
              multiline
              maxLength={2000}
              onFocus={keyboard.remeasure}
              blurOnSubmit={false}
              onKeyPress={(e: any) => {
                if (Platform.OS === 'web' && e.nativeEvent.key === 'Enter' && !e.nativeEvent.shiftKey) {
                  e.preventDefault();
                  send();
                }
              }}
              style={[{
                flex: 1,
                minHeight: 36,
                maxHeight: 120,
                paddingTop: 8,
                paddingBottom: 8,
                fontFamily: fonts.sans,
                fontSize: fs(15),
                lineHeight: fs(20),
                color: colors.ink,
                textAlignVertical: 'center',
              }, Platform.OS === 'web' ? ({ outlineWidth: 0 } as any) : null]}
            />
            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Send"
              accessibilityState={{ disabled: !canSend }}
              disabled={!canSend}
              onPress={send}
              hitSlop={4}
              style={({ pressed }) => ({
                width: 36,
                height: 36,
                flexShrink: 0,
                borderRadius: 18,
                alignItems: 'center',
                justifyContent: 'center',
                backgroundColor: canSend ? colors.navy : colors.line,
                opacity: pressed && canSend ? 0.85 : 1,
              })}
            >
              {sending ? <ActivityIndicator color="#fff" size="small" /> : <Ionicons name="send" size={16} color={canSend ? '#fff' : colors.faint} />}
            </Pressable>
          </View>
        )}
      </View>
    </View>
  );
}
