// City pins on OpenFreeMap (OpenStreetMap data). No Google Maps SDK and no API key.
// iOS and Android both render this page in a WebView. A binary that does not
// include react-native-webview shows the fallback instead of crashing the list.
import React, { useMemo, useState } from 'react';
import { Linking, Text, View } from 'react-native';
import { styles } from './ui';
import { buildEventMapHtml } from '../lib/event-map-html';
import { dispatchMapMessage, type MapMarker } from '../lib/event-map';
import { colors, fs, radius } from '../lib/theme';

const MISSING = 'This app version does not include the map yet. Update the app, or use the list.';
const FAILED = 'The map could not load. Use the list.';

export function EventMap({ markers, height, onOpen, onLock }: {
  markers: readonly MapMarker[];
  height: number;
  onOpen: (id: string) => void;
  onLock?: (locked: boolean) => void;
}) {
  return (
    <MapBoundary height={height}>
      <NativeMap markers={markers} height={height} onOpen={onOpen} onLock={onLock} />
    </MapBoundary>
  );
}

function frame(height: number) {
  return {
    height,
    borderRadius: radius,
    overflow: 'hidden' as const,
    borderWidth: 1,
    borderColor: colors.line,
    backgroundColor: '#e8e4dc',
  };
}

function MapNote({ height, body }: { height: number; body: string }) {
  return (
    <View style={[frame(height), { alignItems: 'center', justifyContent: 'center', padding: 16 }]}>
      <Text style={[styles.muted, { fontSize: fs(13), textAlign: 'center' }]}>{body}</Text>
    </View>
  );
}

class MapBoundary extends React.Component<{ height: number; children: React.ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError(): { failed: boolean } {
    return { failed: true };
  }
  render() {
    if (this.state.failed) return <MapNote height={this.props.height} body={MISSING} />;
    return this.props.children;
  }
}

function NativeMap({ markers, height, onOpen, onLock }: {
  markers: readonly MapMarker[];
  height: number;
  onOpen: (id: string) => void;
  onLock?: (locked: boolean) => void;
}) {
  const [failed, setFailed] = useState(false);
  const html = useMemo(() => buildEventMapHtml(markers), [markers]);
  const ids = useMemo(() => new Set(markers.map((marker) => marker.id)), [markers]);
  let WebView: React.ComponentType<Record<string, unknown>> | null = null;
  try {
    WebView = require('react-native-webview').WebView;
  } catch {
    return <MapNote height={height} body={MISSING} />;
  }
  if (!WebView) return <MapNote height={height} body={MISSING} />;
  if (failed) return <MapNote height={height} body={FAILED} />;
  const MapView = WebView;
  return (
    <View style={frame(height)} onTouchEnd={() => onLock?.(false)} onTouchCancel={() => onLock?.(false)}>
      <MapView
        style={{ flex: 1, backgroundColor: 'transparent' }}
        originWhitelist={['*']}
        source={{ html, baseUrl: 'https://tiles.openfreemap.org' }}
        javaScriptEnabled
        domStorageEnabled
        scrollEnabled={false}
        bounces={false}
        nestedScrollEnabled
        setSupportMultipleWindows={false}
        androidLayerType="hardware"
        showsHorizontalScrollIndicator={false}
        showsVerticalScrollIndicator={false}
        accessibilityLabel="Map of club events by city"
        onShouldStartLoadWithRequest={(req: { url: string; isTopFrame?: boolean; navigationType?: string }) => {
          const url = req.url || '';
          if (url.startsWith('about:') || url.startsWith('data:') || url.startsWith('blob:')) return true;
          if (!url.startsWith('https://')) return false;
          if (req.isTopFrame && req.navigationType === 'click') return false;
          return true;
        }}
        onError={() => setFailed(true)}
        onMessage={(event: { nativeEvent: { data: string } }) => {
          dispatchMapMessage(event.nativeEvent.data, ids, {
            onOpen,
            onLink: (url) => { Linking.openURL(url).catch(() => {}); },
            onLock: (locked) => onLock?.(locked),
            onError: () => setFailed(true),
          });
        }}
      />
    </View>
  );
}
