// Shared top of a club record: cover band, serif title, compact actions.
// The stack bar is hidden on these screens. BackChevron in ui.tsx is the back control.
import type { ReactNode } from 'react';
import { Text, View } from 'react-native';
import { EventCover } from './events';
import { styles } from './ui';
import { PUBLIC_GROUP_HERO_ASPECT } from '../lib/public-group';
import { colors, radius } from '../lib/theme';

/** Full content width, 2.4:1, center-cropped. Renders nothing when there is no image. */
export function CoverBand({ url, onError }: { url?: string | null; onError?: () => void }) {
  if (!url) return null;
  return (
    <View style={{ borderRadius: radius, overflow: 'hidden', borderWidth: 1, borderColor: colors.line }}>
      <EventCover url={url} fill aspectRatio={PUBLIC_GROUP_HERO_ASPECT} radius={0} onError={onError} />
    </View>
  );
}

/** Serif name, one meta line, optional status. No type label. */
export function EntityTitle({ title, meta, pills }: { title: string; meta?: string | null; pills?: ReactNode }) {
  return (
    <View style={{ gap: 4 }}>
      <Text accessibilityRole="header" style={styles.h1}>{title}</Text>
      {meta ? <Text style={styles.muted}>{meta}</Text> : null}
      {pills ? <View style={{ flexDirection: 'row', gap: 6, marginTop: 4, flexWrap: 'wrap' }}>{pills}</View> : null}
    </View>
  );
}

/** Edit, Analytics, Delete, and the other small record actions. */
export function ActionRow({ children }: { children: ReactNode }) {
  return <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8, alignItems: 'center' }}>{children}</View>;
}
