// Preview-only event chats. The live host gate is public.can_link_event_chat.
type DemoEventChat = {
  room_id: string;
  title: string;
  created_by: string;
  member_ids: string[];
  links: { event_id: string; source: string }[];
  series_ids: string[];
  created_at: string;
};
const demoChats: DemoEventChat[] = [];
const DEMO_SERIES: Record<string, { series_id: string; series_title: string }> = {
  'e-genealogy': { series_id: 'demo-nietzsche', series_title: 'Nietzsche readings' },
  'e-ethics': { series_id: 'demo-nietzsche', series_title: 'Nietzsche readings' },
};
const demoSeriesId = (eventId: string) => DEMO_SERIES[eventId]?.series_id ?? null;

export function demoGroupById(roomId: string): DemoEventChat | null {
  return demoChats.find((chat) => chat.room_id === roomId) ?? null;
}

export function demoCanLinkEventChat(eventId: string): boolean {
  return demoEvents.some((event) => event.id === eventId && event.created_by === DEMO_ME);
}

export function demoEventChatTargets(anchorId: string) {
  if (!demoCanLinkEventChat(anchorId)) throw new Error('not_allowed');
  const series = demoSeriesId(anchorId);
  return demoEvents.filter((event) => event.created_by === DEMO_ME || (series && demoSeriesId(event.id) === series)).map((event) => ({
    event_id: event.id,
    title: event.title,
    starts_at: event.starts_at,
    series_id: demoSeriesId(event.id),
    series_title: DEMO_SERIES[event.id]?.series_title ?? null,
  }));
}

export function demoEventChatPresets(eventId: string): { user_id: string; preset: 'rsvp' | 'attending' | 'hosting' }[] {
  if (!demoCanLinkEventChat(eventId)) throw new Error('not_allowed');
  if (eventId !== 'e-genealogy') return [];
  return [
    { user_id: 'u1', preset: 'rsvp' },
    { user_id: 'u2', preset: 'attending' },
    { user_id: 'u3', preset: 'hosting' },
  ];
}

function demoChatSummary(chat: DemoEventChat, eventTitle: string | null) {
  return {
    room_id: chat.room_id,
    title: chat.title,
    created_by: chat.created_by,
    member_count: chat.member_ids.length,
    created_at: chat.created_at,
    event_count: chat.links.length,
    event_title: eventTitle,
  };
}

function demoNearestTitle(chat: DemoEventChat): string | null {
  const now = Date.now();
  const rows = chat.links
    .map((link) => demoEvents.find((event) => event.id === link.event_id))
    .filter((event): event is ClubEvent => !!event);
  rows.sort((a, b) => {
    const af = Date.parse(a.starts_at) < now ? 1 : 0;
    const bf = Date.parse(b.starts_at) < now ? 1 : 0;
    return af - bf || Math.abs(Date.parse(a.starts_at) - now) - Math.abs(Date.parse(b.starts_at) - now);
  });
  return rows[0]?.title ?? null;
}

export function demoListEventChats(eventId: string) {
  return demoChats
    .filter((chat) => chat.member_ids.includes(DEMO_ME) && chat.links.some((link) => link.event_id === eventId))
    .map((chat) => demoChatSummary(chat, demoNearestTitle(chat)));
}

export function demoListMyGroupChats() {
  return demoChats
    .filter((chat) => chat.member_ids.includes(DEMO_ME))
    .map((chat) => demoChatSummary(chat, demoNearestTitle(chat)));
}

export function demoRoomEventLinks(roomId: string) {
  const chat = demoGroupById(roomId);
  if (!chat || !chat.member_ids.includes(DEMO_ME)) return [];
  return chat.links.map((link) => {
    const event = demoEvents.find((row) => row.id === link.event_id);
    return {
      event_id: link.event_id,
      title: event?.title ?? 'Event',
      starts_at: event?.starts_at ?? new Date().toISOString(),
      source: link.source,
      series_id: demoSeriesId(link.event_id),
    };
  });
}

export function demoRoomSeries(roomId: string): string[] {
  const chat = demoGroupById(roomId);
  if (!chat || !chat.member_ids.includes(DEMO_ME)) return [];
  return [...chat.series_ids];
}

export function demoCreateEventChat(input: {
  eventId: string;
  title: string;
  memberIds: string[];
  alsoEventIds: string[];
  attachSeries: boolean;
}): string {
  if (!demoCanLinkEventChat(input.eventId)) throw new Error('not_allowed');
  const title = input.title.trim();
  if (title.length < 1 || title.length > 120) throw new Error('bad_title');
  const member_ids = [DEMO_ME];
  for (const id of input.memberIds) {
    if (!id || id === DEMO_ME || member_ids.includes(id)) continue;
    if (!demoProfiles[id]) throw new Error('user_not_found');
    member_ids.push(id);
  }
  const series = demoSeriesId(input.eventId);
  if (input.attachSeries && !series) throw new Error('no_series');
  const links: { event_id: string; source: string }[] = [];
  const addManual = (id: string) => {
    if (!demoEvents.some((event) => event.id === id)) throw new Error('not_allowed');
    const existing = links.find((link) => link.event_id === id);
    if (existing) existing.source = 'manual';
    else links.push({ event_id: id, source: 'manual' });
  };
  addManual(input.eventId);
  for (const id of input.alsoEventIds) addManual(id);
  const series_ids: string[] = [];
  if (input.attachSeries && series) {
    series_ids.push(series);
    for (const event of demoEvents) {
      if (demoSeriesId(event.id) === series && !links.some((link) => link.event_id === event.id)) {
        links.push({ event_id: event.id, source: 'series' });
      }
    }
  }
  const room_id = `group-${demoChats.length + 1}`;
  const created_at = new Date().toISOString();
  demoChats.unshift({ room_id, title, created_by: DEMO_ME, member_ids, links, series_ids, created_at });
  demoRooms.push({ id: room_id, kind: 'group', title, description: '', meetup_url: null, starts_at: null, ends_at: null });
  return room_id;
}

export function demoSetEventChatEvents(input: {
  roomId: string;
  add: string[];
  remove: string[];
  attachSeries: boolean;
  detachSeries: boolean;
  anchorEventId: string;
}) {
  const chat = demoChats.find((row) => row.room_id === input.roomId);
  if (!chat || chat.created_by !== DEMO_ME || !chat.member_ids.includes(DEMO_ME)) throw new Error('not_allowed');
  if (input.attachSeries && input.detachSeries) throw new Error('not_allowed');
  for (const id of input.add) {
    if (!demoEvents.some((event) => event.id === id)) throw new Error('not_allowed');
    const existing = chat.links.find((link) => link.event_id === id);
    if (existing) existing.source = 'manual';
    else chat.links.push({ event_id: id, source: 'manual' });
  }
  const remove = new Set(input.remove);
  chat.links = chat.links.filter((link) => !remove.has(link.event_id));
  const series = demoSeriesId(input.anchorEventId);
  if (input.attachSeries) {
    if (!series) throw new Error('no_series');
    if (!chat.series_ids.includes(series)) chat.series_ids.push(series);
    for (const event of demoEvents) {
      if (demoSeriesId(event.id) === series && !chat.links.some((link) => link.event_id === event.id)) {
        chat.links.push({ event_id: event.id, source: 'series' });
      }
    }
  } else if (input.detachSeries && series) {
    chat.series_ids = chat.series_ids.filter((id) => id !== series);
    chat.links = chat.links.filter((link) => link.source !== 'series' || demoSeriesId(link.event_id) !== series);
  }
}

