// Approximate place for anonymous pages, and the exact place after someone is entitled.
// The SQL helpers in 20261026000005_event_place_access.sql,
// 20261026000006_place_city_only.sql, and 20261027000002_public_place_no_venue.sql
// follow the same rules.
// Before an RSVP the place is a city, or "Online". A room name, a street, a Zoom
// or Discord label, a join URL, and a meeting id are not part of that line.

const STREET = /\b(?:street|st|avenue|ave|road|rd|boulevard|blvd|lane|ln|drive|dr|way|place|pl|court|ct|parkway|pkwy|terrace|ter|circle|cir)\b/i;
const ZIP = /\b\d{5}(?:-\d{4})?\b/;
const JOIN_URL = /zoom\.us|zoommtg:|discord\.gg|discord\.com\/invite/i;

function clean(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const s = value.trim();
  return s || null;
}

/** Comma, middle dot, or a spaced dash. Meetup sometimes prints "25 11th Avenue · New York, NY". */
function splitParts(raw: string): string[] {
  const normalized = raw
    .replace(/\s*[\u00b7\u2022|]\s*/g, ', ')
    .replace(/\s+[\u2013\u2014-]\s+/g, ', ');
  return normalized.split(/\s*,\s*/).map((part) => part.trim()).filter(Boolean);
}

function isStreetPart(part: string): boolean {
  return /^\d/.test(part) || STREET.test(part);
}

function isPostalPart(part: string): boolean {
  return /^\d{5}(?:-\d{4})?$/.test(part);
}

function isCountryPart(part: string): boolean {
  const n = part.toLowerCase();
  return n === 'us' || n === 'usa' || n === 'united states';
}

/** "Zoom", "Zoom Webinar", "via Zoom". Not a longer room name such as "Club Zoom room". */
function isZoomishPart(part: string): boolean {
  const n = part.toLowerCase().replace(/[^a-z\s]/g, ' ').replace(/\s+/g, ' ').trim();
  if (n === 'online' || n === 'online event' || n === 'virtual') return true;
  return /^(?:on|via|through|join)?\s*zoom(?:\s+(?:meeting|webinar|call|link|room|event))?$/.test(n);
}

/** Zoom or Discord as a platform label. Not a longer room name. */
function isPlatformPart(part: string): boolean {
  if (isZoomishPart(part)) return true;
  const n = part.toLowerCase().replace(/[^a-z\s]/g, ' ').replace(/\s+/g, ' ').trim();
  return /^(?:on|via|through|join)?\s*discord(?:\s+(?:voice|server|channel|call|link|room|event|stage))?$/.test(n);
}

function hasJoinUrl(value?: string | null): boolean {
  return JOIN_URL.test(value ?? '');
}

export function isOnlinePlace(name?: string | null, address?: string | null): boolean {
  const n = (name ?? '').toLowerCase().replace(/[^a-z]/g, '');
  if (n === 'online' || n === 'onlineevent' || n === 'virtual' || n === 'virtualevent' || n === 'zoom' || n === 'discord') return true;
  if (isPlatformPart(name ?? '')) return true;
  if (hasJoinUrl(name) || hasJoinUrl(address)) return true;
  const a = (address ?? '').trim();
  if (!a) return false;
  if (isPlatformPart(a)) return true;
  // "Zoom Webinar, New York" is still an online listing. A street in the same line is a physical place.
  if (splitParts(a).some(isPlatformPart) && !splitParts(a).some(isStreetPart) && !/^\s*\d/.test(a)) return true;
  return false;
}

/** City and state. Null when the only thing we have is a street, a Zoom label, or a meeting link. */
export function publicLocality(address?: string | null): string | null {
  const raw = clean(address);
  if (!raw) return null;
  if (hasJoinUrl(raw) || /^https?:\/\//i.test(raw)) return null;
  const kept: string[] = [];
  for (let part of splitParts(raw)) {
    part = part.replace(/\s+\d{5}(?:-\d{4})?$/, '').trim();
    if (!part || isPlatformPart(part) || isStreetPart(part) || isPostalPart(part) || isCountryPart(part)) continue;
    if (ZIP.test(part) && part.split(/\s+/).length === 1) continue;
    kept.push(part);
  }
  return kept.length ? kept.join(', ') : null;
}

/**
 * Public venue label. Online listings are "Online".
 * A room, a pier, a library, or a street is not public — the city is.
 */
export function publicVenueName(name?: string | null, address?: string | null): string | null {
  if (isOnlinePlace(name, address)) return 'Online';
  const raw = clean(name);
  if (raw && (hasJoinUrl(raw) || isPlatformPart(raw))) return 'Online';
  return null;
}

/** One line for a public card or a locked member screen. City, or Online. Never a room, a street, or a join link. */
export function publicPlaceLine(name?: string | null, address?: string | null): string {
  const city = publicLocality(address);
  if (isOnlinePlace(name, address) || publicVenueName(name, address) === 'Online') {
    return city ? `Online · ${city}` : 'Online';
  }
  return city || 'Place to be announced';
}

/**
 * Address field before the place is unlocked.
 * The city when we have one. "Online" when the listing is online and there is no city.
 * Never a street, a Zoom label, or a join link.
 */
export function publicAddressLine(name?: string | null, address?: string | null): string {
  const city = publicLocality(address);
  if (city) return city;
  if (isOnlinePlace(name, address)) return 'Online';
  return '';
}

/** Exact place for someone who is entitled. "Zoom" stays a label when that is all Meetup stored. */
export function exactPlaceLine(name?: string | null, address?: string | null): string {
  const venue = clean(name);
  const line = clean(address);
  if (line && /^zoom$/i.test(line)) {
    if (venue && !isOnlinePlace(venue, null)) return `${venue} · Zoom`;
    return 'Online · Zoom';
  }
  const parts = [venue, line].filter((p): p is string => !!p);
  return parts.join(' · ') || 'TBA';
}

/** What a place field shows. `href` means `text` is the zoom.us link. `link` is a zoom.us URL shown with a street or a room name. */
export type ShownPlace = {
  text: string;
  href: string | null;
  link: string | null;
};

/**
 * Details rows before the place is unlocked.
 * Starts and ends are already formatted. Venue is only "Online".
 * Address is the city, or "Online" when there is no city.
 */
export function lockedDetailFields(starts: string, ends: string, name?: string | null, address?: string | null): [string, string][] {
  const venue = publicVenueName(name, address);
  const fields: [string, string][] = [
    ['Starts', starts],
    ['Ends', ends],
  ];
  if (venue) fields.push(['Venue', venue]);
  fields.push(['Address', publicAddressLine(name, address)]);
  return fields;
}

/** Where, before the place is unlocked. City, or Online. No room name, street, Zoom/Discord label, or join link. */
export function lockedWhere(name?: string | null, address?: string | null): ShownPlace {
  return { text: publicPlaceLine(name, address), href: null, link: null };
}

const ZOOM_ONLY_LINE = /^(?:online|zoom|virtual|online event|online · zoom|online · virtual|tba)$/i;
const ZOOM_ADDRESS = /^(?:zoom|online|online event|virtual)$/i;

/**
 * Where, for a viewer who may see the join URL.
 * An online Zoom label becomes the URL. A street or a city stays, with the URL beside it.
 * Pass a null URL for a viewer who should keep the approximate place.
 */
export function entitledWhere(name?: string | null, address?: string | null, meetingUrl?: string | null): ShownPlace {
  const exact = exactPlaceLine(name, address);
  const href = safeMeetingUrl(meetingUrl);
  if (!href) return { text: exact, href: null, link: null };
  if (ZOOM_ONLY_LINE.test(exact.trim())) return { text: href, href, link: null };
  const addr = clean(address);
  if (addr && ZOOM_ADDRESS.test(addr)) {
    const venue = clean(name);
    if (venue && !isOnlinePlace(venue, null)) return { text: venue, href: null, link: href };
  }
  return { text: exact, href: null, link: href };
}

/**
 * Address, for a viewer who may see the join URL.
 * "Zoom" (or a blank online address) becomes the URL. A street stays, with the URL beside it.
 */
export function entitledAddress(address?: string | null, meetingUrl?: string | null): ShownPlace {
  const href = safeMeetingUrl(meetingUrl);
  const line = clean(address);
  if (!href) return { text: line ?? '', href: null, link: null };
  if (!line || ZOOM_ADDRESS.test(line)) return { text: href, href, link: null };
  return { text: line, href: null, link: href };
}

/** Drop Zoom and Discord join links, and meeting ids, from text shown before the place is unlocked. */
export function publicDescription(description?: string | null): string {
  if (!description) return '';
  return description
    .replace(/zoommtg:\S+/gi, '')
    .replace(/https?:\/\/(?:[a-z0-9-]+\.)*zoom\.us\/[^\s<>"')\]]+/gi, '')
    .replace(/https?:\/\/(?:(?:www\.)?discord\.gg|discord\.com\/invite)\/[^\s<>"')\]]+/gi, '')
    .replace(/\b(?:meeting|webinar)\s+id\s*[:#]?\s*\d[\d\s-]{8,}\d/gi, '')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/[ \t]+\n/g, '\n')
    .trim();
}

/** https link on zoom.us only. Anything else is not opened from the event screen. */
export function safeMeetingUrl(url?: string | null): string | null {
  const raw = clean(url);
  if (!raw) return null;
  try {
    const u = new URL(raw);
    if (u.protocol !== 'https:' && u.protocol !== 'http:') return null;
    const host = u.hostname.toLowerCase();
    if (host !== 'zoom.us' && !host.endsWith('.zoom.us')) return null;
    u.protocol = 'https:';
    u.hash = '';
    return u.toString();
  } catch {
    return null;
  }
}
