// Confirm sheet for deleting a club group. Meetup itself is left as it is.
import React from 'react';
import { View } from 'react-native';
import { ConfirmSheet, IncludedRow } from './confirm-sheet';

export function DeleteGroupSheet({ visible, busy, error, onCancel, onConfirm }: {
  visible: boolean;
  busy: boolean;
  error: string | null;
  onCancel: () => void;
  onConfirm: () => void;
}) {
  return (
    <ConfirmSheet visible={visible} title="Delete this group?" busy={busy} error={error} confirmTitle="Delete group"
      body="This removes it from Gnosis Events. Events stay, and are no longer linked to this group. The Meetup group is not deleted."
      onCancel={onCancel}
      onConfirm={onConfirm}>
      <View style={{ gap: 10 }}>
        <IncludedRow label="The club group" />
        <IncludedRow label="The public web page, when one exists" />
        <IncludedRow label="The Meetup link stored in Gnosis Events" />
      </View>
    </ConfirmSheet>
  );
}
