// Moderator-facing owner on an event or group. Same profile the People rows open.
import { useEffect, useState } from 'react';
import { getProfile } from './api';
import type { Profile } from './types';

/** Null until the profile loads, and when the caller is not showing an owner. */
export function useOwnerProfile(ownerId: string | null | undefined, show: boolean): Profile | null {
  const [profile, setProfile] = useState<Profile | null>(null);
  useEffect(() => {
    if (!show || !ownerId) {
      setProfile(null);
      return;
    }
    let live = true;
    getProfile(ownerId).then((row) => {
      if (live) setProfile(row);
    }).catch(() => {
      if (live) setProfile(null);
    });
    return () => { live = false; };
  }, [ownerId, show]);
  return profile;
}
