// Club groups (public.groups) are the versioned record.
// Publish to sends the current version to the public page, or records the
// existing Meetup group link. Meetup’s member count is never read or shown.
import { DEMO_ME, demoEvents, demoProfiles, isDemo } from './demo';
import {
  CLUB_GROUP_ABOUT, CLUB_GROUP_CITY, CLUB_GROUP_COVER, CLUB_GROUP_ID, CLUB_GROUP_MEETUP,
  CLUB_GROUP_NAME, CLUB_GROUP_SLUG, publicGroupPath,
} from './group-views';
import { publicAppUrl } from './public-url';
import { publicationSelect, safeMeetupUrl } from './publications';
import { copyPublicPath } from './share-link';
import { EVENT_END_FALLBACK_MS, eventEndMs } from './format';
import { eventInPublicDirectory } from './event-visibility';
import { PUBLIC_EVENT_COLUMNS, PUBLIC_EVENT_COLUMNS_LEGACY, preparePublishedEvents } from './events';
import { sponsorInput, type GroupSponsorDraft } from './public-group';
import { signedInUserId, supabase } from './supabase';
import type { ClubGroup, GroupPublication, GroupSnapshot, GroupSponsor, PublicEvent, PublicGroup, PublicGroupOrganizer, PublicGroupSponsor } from './types';

export type GroupInput = {
  name: string;
  slug: string;
  description: string;
  locality: string | null;
  image_url: string | null;
  meetup_url: string | null;
};

const GROUP_COLUMNS = 'id,name,slug,description,locality,image_url,meetup_url,archived,created_by,current_version,public_published_at,created_at,updated_at';
const GROUP_COLUMNS_OWNER = `${GROUP_COLUMNS},owner_id`;

type GroupQuery = PromiseLike<{ data: unknown; error: { message: string } | null }>;

/** owner_id is optional until migration 20261028000002. */
async function selectGroupRows(run: (columns: string) => GroupQuery) {
  let result = await run(GROUP_COLUMNS_OWNER);
  if (result.error && /owner_id/.test(result.error.message)) result = await run(GROUP_COLUMNS);
  return result;
}

const PUBLIC_GROUP_COLUMNS = 'id,slug,name,description,locality,image_url,meetup_url,public_published_at';

function groupSnapshot(g: Pick<ClubGroup, 'current_version' | 'name' | 'slug' | 'description' | 'locality' | 'image_url' | 'meetup_url'>): GroupSnapshot {
  return {
    version: g.current_version,
    name: g.name,
    slug: g.slug,
    description: g.description,
    locality: g.locality,
    image_url: g.image_url,
    meetup_url: g.meetup_url,
  };
}

export function publicGroupUrl(slug: string): string {
  return publicAppUrl(publicGroupPath(slug));
}

export async function copyPublicGroupLink(slug: string): Promise<'copied' | 'shared' | 'dismissed'> {
  return copyPublicPath(publicGroupPath(slug));
}

function demoGroup(): ClubGroup {
  const now = new Date().toISOString();
  return {
    id: CLUB_GROUP_ID,
    name: CLUB_GROUP_NAME,
    slug: CLUB_GROUP_SLUG,
    description: CLUB_GROUP_ABOUT,
    locality: CLUB_GROUP_CITY,
    image_url: CLUB_GROUP_COVER,
    meetup_url: CLUB_GROUP_MEETUP,
    archived: false,
    created_by: DEMO_ME,
    owner_id: DEMO_ME,
    current_version: 1,
    public_published_at: now,
    created_at: now,
    updated_at: now,
  };
}

const demoGroups: ClubGroup[] = [demoGroup()];
const demoGroupPublications: GroupPublication[] = (() => {
  const g = demoGroups[0];
  const snap = groupSnapshot(g);
  const now = g.public_published_at ?? new Date().toISOString();
  const row = (channel: string, external: boolean): GroupPublication => ({
    id: `gpub-${channel}`,
    group_id: g.id,
    channel,
    status: 'published',
    published_version: g.current_version,
    published_at: now,
    snapshot: snap,
    external_id: external ? g.slug : null,
    external_url: external ? g.meetup_url : null,
    last_error: null,
    updated_at: now,
  });
  return [row('meetup', true), row('web', false)];
})();

function groupsMissing(message: string): boolean {
  return /schema cache|could not find the table|relation ["']?public\.groups["']? does not exist|relation ["']?groups["']? does not exist/i.test(message);
}

function explainGroupError(message: string): string {
  if (groupsMissing(message)) return 'Groups aren’t in the database yet. Apply supabase/migrations/20261028000001_club_groups.sql in the SQL editor.';
  if (/groups_slug|duplicate key|23505/i.test(message)) return 'That web address is already used.';
  if (/not a moderator|42501/i.test(message)) return 'Only moderators can change groups.';
  if (/group not found|P0002/i.test(message)) return 'This group is already gone.';
  if (/archived groups stay off/i.test(message)) return 'Archived groups stay off Meetup in Gnosis Events. Restore the group first.';
  if (/meetup group url/i.test(message)) return 'Add a Meetup group URL before publishing.';
  if (/delete_club_group|schema cache|could not find the function/i.test(message)) return 'Deleting groups isn’t available yet.';
  return message;
}

export async function listGroups(includeArchived = false): Promise<ClubGroup[]> {
  if (isDemo()) return demoGroups.filter((g) => includeArchived || !g.archived).map((g) => ({ ...g }));
  const load = (hideDeleted: boolean) => selectGroupRows((columns) => {
    let query = supabase.from('groups').select(columns).order('name', { ascending: true });
    if (hideDeleted) query = query.is('deleted_at', null);
    if (!includeArchived) query = query.eq('archived', false);
    return query;
  });
  let result = await load(true);
  if (result.error && /deleted_at/.test(result.error.message)) {
    result = await load(false);
    if (result.error) throw new Error(explainGroupError(result.error.message));
    const rows = (result.data ?? []) as ClubGroup[];
    return includeArchived ? rows : rows.filter((g) => !g.archived);
  }
  if (result.error) throw new Error(explainGroupError(result.error.message));
  return (result.data ?? []) as ClubGroup[];
}

export async function getGroup(id: string): Promise<ClubGroup | null> {
  if (isDemo()) return demoGroups.find((g) => g.id === id) ?? null;
  const load = (hideDeleted: boolean) => selectGroupRows((columns) => {
    let query = supabase.from('groups').select(columns).eq('id', id);
    if (hideDeleted) query = query.is('deleted_at', null);
    return query.maybeSingle();
  });
  let res = await load(true);
  if (res.error && /deleted_at/.test(res.error.message)) res = await load(false);
  if (res.error) {
    if (/invalid input syntax for type uuid/i.test(res.error.message)) return null;
    throw new Error(explainGroupError(res.error.message));
  }
  return (res.data as ClubGroup | null) ?? null;
}

export async function getPublishedGroup(slug: string): Promise<PublicGroup | null> {
  if (isDemo()) {
    const g = demoGroups.find((row) => row.slug === slug && !row.archived && row.public_published_at);
    if (!g) return null;
    return {
      id: g.id, slug: g.slug, name: g.name, description: g.description, locality: g.locality,
      image_url: g.image_url, meetup_url: g.meetup_url, public_published_at: g.public_published_at,
    };
  }
  const { data, error } = await supabase.from('published_groups').select(PUBLIC_GROUP_COLUMNS).eq('slug', slug).maybeSingle();
  if (error) {
    if (groupsMissing(error.message) || /published_groups/.test(error.message)) return null;
    throw new Error(explainGroupError(error.message));
  }
  return (data as PublicGroup | null) ?? null;
}

function demoPublishedForGroup(groupId: string): PublicEvent[] {
  return demoEvents
    .filter((e) => e.group_id === groupId && !e.archived && e.public_published_at && eventInPublicDirectory(e))
    .map((e) => ({
      id: e.id, title: e.title, description: e.description, starts_at: e.starts_at, ends_at: e.ends_at,
      venue_name: e.venue_name, venue_address: e.venue_locality ?? null, image_url: e.image_url ?? null,
      meetup_url: e.meetup_url, meetup_publish_status: e.meetup_publish_status, public_published_at: e.public_published_at,
      visibility: e.visibility,
    }));
}

function publishedEventStillOpen(event: PublicEvent, now = Date.now()): boolean {
  const end = eventEndMs(event);
  return end == null || end > now;
}

async function queryPublishedGroupEvents(run: (columns: string) => GroupQuery): Promise<PublicEvent[]> {
  let result = await run(PUBLIC_EVENT_COLUMNS);
  if (result.error && /visibility/.test(result.error.message)) result = await run(PUBLIC_EVENT_COLUMNS_LEGACY);
  if (result.error) throw new Error(explainGroupError(result.error.message));
  return preparePublishedEvents((result.data ?? []) as unknown as PublicEvent[]);
}

/** Upcoming published events for one group. Same end rule as the public event list. */
export async function listPublishedGroupEvents(groupId: string): Promise<PublicEvent[]> {
  if (isDemo()) {
    return demoPublishedForGroup(groupId).filter((event) => publishedEventStillOpen(event)).sort((a, b) => a.starts_at.localeCompare(b.starts_at));
  }
  const now = Date.now();
  const nowIso = new Date(now).toISOString();
  const openEndedCutoff = new Date(now - EVENT_END_FALLBACK_MS).toISOString();
  return queryPublishedGroupEvents((columns) => supabase.from('published_events').select(columns)
    .eq('group_id', groupId)
    .or(`ends_at.gt.${nowIso},and(ends_at.is.null,starts_at.gt.${openEndedCutoff})`)
    .order('starts_at', { ascending: true }));
}

export async function listGroupPublications(groupId: string): Promise<GroupPublication[]> {
  if (isDemo()) return demoGroupPublications.filter((p) => p.group_id === groupId).map((p) => ({ ...p, snapshot: p.snapshot ? { ...p.snapshot } : null }));
  const { data, error } = await supabase.from('group_publications')
    .select(publicationSelect('group_id'))
    .eq('group_id', groupId);
  if (error) throw new Error(explainGroupError(error.message));
  return (data ?? []) as GroupPublication[];
}

function touchDemo(id: string, patch: Partial<ClubGroup>): ClubGroup {
  const g = demoGroups.find((row) => row.id === id);
  if (!g) throw new Error('Group not found.');
  const before = groupSnapshot(g);
  Object.assign(g, patch, { updated_at: new Date().toISOString() });
  const after = groupSnapshot(g);
  if (JSON.stringify(before) !== JSON.stringify(after)) g.current_version += 1;
  return g;
}

export async function saveGroup(input: GroupInput, id?: string): Promise<string> {
  const meetup = input.meetup_url ? safeMeetupUrl(input.meetup_url) : null;
  if (input.meetup_url && !meetup) throw new Error('Meetup URL must be an https link on meetup.com.');
  const row = { ...input, meetup_url: meetup, image_url: input.image_url?.trim() || null, locality: input.locality?.trim() || null };
  if (isDemo()) {
    if (!id) {
      const created: ClubGroup = {
        ...demoGroup(),
        id: `g-${row.slug}`,
        ...row,
        owner_id: DEMO_ME,
        created_by: DEMO_ME,
        archived: false,
        current_version: 1,
        public_published_at: null,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      };
      demoGroups.push(created);
      return created.id;
    }
    touchDemo(id, row);
    return id;
  }
  if (id) {
    const { error } = await supabase.from('groups').update(row).eq('id', id);
    if (error) throw new Error(explainGroupError(error.message));
    return id;
  }
  const owner_id = await signedInUserId();
  const { data, error } = await supabase.from('groups').insert({ ...row, owner_id, created_by: owner_id }).select('id').single();
  if (error) throw new Error(explainGroupError(error.message));
  return data.id as string;
}

export async function setGroupArchived(id: string, archived: boolean) {
  if (isDemo()) {
    const g = demoGroups.find((row) => row.id === id);
    if (!g) return;
    g.archived = archived;
    if (archived) {
      g.public_published_at = null;
      const web = demoGroupPublications.find((p) => p.group_id === id && p.channel === 'web');
      if (web && web.status === 'published') web.status = 'unpublished';
    }
    return;
  }
  const { error } = await supabase.from('groups').update({ archived }).eq('id', id);
  if (error) throw new Error(explainGroupError(error.message));
}

/** Moderator-only. Publishing again sends the current version. Archived groups stay off. */
export async function setGroupPublished(id: string, published: boolean): Promise<string | null> {
  if (isDemo()) {
    const g = demoGroups.find((row) => row.id === id);
    if (!g) throw new Error('Group not found.');
    if (g.archived && published) throw new Error('Archived groups stay off the public page.');
    g.public_published_at = published ? new Date().toISOString() : null;
    let web = demoGroupPublications.find((p) => p.group_id === id && p.channel === 'web');
    if (!web) {
      web = {
        id: `gpub-web-${id}`, group_id: id, channel: 'web', status: 'unpublished',
        published_version: null, published_at: null, snapshot: null, external_id: null, external_url: null,
        last_error: null, updated_at: new Date().toISOString(),
      };
      demoGroupPublications.push(web);
    }
    if (published) {
      web.status = 'published';
      web.published_version = g.current_version;
      web.published_at = g.public_published_at;
      web.snapshot = groupSnapshot(g);
      web.last_error = null;
    } else if (web.status === 'published') {
      web.status = 'unpublished';
    }
    return g.public_published_at;
  }
  const { data, error } = await supabase.from('groups')
    .update({ public_published_at: published ? new Date().toISOString() : null })
    .eq('id', id)
    .select('public_published_at')
    .maybeSingle();
  if (error) throw new Error(explainGroupError(error.message));
  if (!data) throw new Error('You can’t change the public page.');
  if (published && !data.public_published_at) throw new Error('Archived groups stay off the public page.');
  return data.public_published_at;
}

/**
 * Records the Meetup group link as published or unpublished.
 * Does not call Meetup and does not import a member count.
 */
export async function setGroupMeetupPublished(id: string, published: boolean): Promise<string | null> {
  if (isDemo()) {
    const g = demoGroups.find((row) => row.id === id);
    if (!g) throw new Error('Group not found.');
    if (published && !safeMeetupUrl(g.meetup_url)) throw new Error('Add a Meetup group URL before publishing.');
    let row = demoGroupPublications.find((p) => p.group_id === id && p.channel === 'meetup');
    if (!row) {
      row = {
        id: `gpub-meetup-${id}`, group_id: id, channel: 'meetup', status: 'unpublished',
        published_version: null, published_at: null, snapshot: null, external_id: null, external_url: g.meetup_url,
        last_error: null, updated_at: new Date().toISOString(),
      };
      demoGroupPublications.push(row);
    }
    if (published) {
      row.status = 'published';
      row.published_version = g.current_version;
      row.published_at = new Date().toISOString();
      row.snapshot = groupSnapshot(g);
      row.external_id = g.slug;
      row.external_url = g.meetup_url;
      row.last_error = null;
    } else {
      row.status = 'unpublished';
    }
    return g.meetup_url;
  }
  const { data, error } = await supabase.rpc('set_group_meetup_published', { p_group_id: id, p_published: published });
  if (error) throw new Error(explainGroupError(error.message));
  return typeof data === 'string' ? data : null;
}

/** Soft-delete. Events stay and lose the link. The Meetup group is not deleted. */
export async function deleteGroup(id: string) {
  if (isDemo()) {
    const i = demoGroups.findIndex((row) => row.id === id);
    if (i >= 0) demoGroups.splice(i, 1);
    return;
  }
  const { error } = await supabase.rpc('delete_club_group', { p_group_id: id });
  if (error) throw new Error(explainGroupError(error.message));
}

const demoSponsors: GroupSponsor[] = [];
const SPONSOR_COLUMNS = 'id,group_id,title,body,image_url,link_url,sort_order,created_at,updated_at';
const PUBLIC_SPONSOR_COLUMNS = 'id,group_id,title,body,image_url,link_url,sort_order';

function sponsorsMissing(message: string): boolean {
  return /schema cache|could not find the table|could not find the relation|does not exist/i.test(message)
    && /group_sponsors|published_group_sponsors/i.test(message);
}

function explainSponsorError(message: string): string {
  if (sponsorsMissing(message)) return 'Sponsors aren’t in the database yet. Apply supabase/migrations/20261031000001_group_sponsors.sql in the SQL editor.';
  if (/group_sponsors_image_url_chk/i.test(message)) return 'Image URL must be an https URL.';
  if (/group_sponsors_link_url_chk/i.test(message)) return 'Link must be an https URL.';
  if (/group_sponsors_title_check/i.test(message)) return 'Title is required.';
  if (/group_sponsors_body_check/i.test(message)) return 'Body is too long.';
  return explainGroupError(message);
}

function sponsorSort(a: { sort_order: number; id: string }, b: { sort_order: number; id: string }) {
  return a.sort_order - b.sort_order || a.id.localeCompare(b.id);
}

function demoSponsorsFor(groupId: string): GroupSponsor[] {
  return demoSponsors.filter((row) => row.group_id === groupId).sort(sponsorSort).map((row) => ({ ...row }));
}

/** Sponsors on the club group. Moderators only, including before the group is published. */
export async function listGroupSponsors(groupId: string): Promise<GroupSponsor[]> {
  if (isDemo()) return demoSponsorsFor(groupId);
  const { data, error } = await supabase.from('group_sponsors').select(SPONSOR_COLUMNS).eq('group_id', groupId).order('sort_order', { ascending: true }).order('id', { ascending: true });
  if (error) throw new Error(explainSponsorError(error.message));
  return (data ?? []) as GroupSponsor[];
}

/**
 * Sponsors for a published group. Missing table reads as none so the public
 * page still loads before the migration is applied. No sample rows.
 */
export async function listPublishedGroupSponsors(groupId: string): Promise<PublicGroupSponsor[]> {
  if (isDemo()) {
    const g = demoGroups.find((row) => row.id === groupId);
    if (!g || g.archived || !g.public_published_at) return [];
    return demoSponsorsFor(groupId).map(({ id, group_id, title, body, image_url, link_url, sort_order }) => ({ id, group_id, title, body, image_url, link_url, sort_order }));
  }
  const { data, error } = await supabase.from('published_group_sponsors').select(PUBLIC_SPONSOR_COLUMNS).eq('group_id', groupId).order('sort_order', { ascending: true }).order('id', { ascending: true });
  if (error) {
    if (sponsorsMissing(error.message)) return [];
    throw new Error(explainSponsorError(error.message));
  }
  return (data ?? []) as PublicGroupSponsor[];
}

const PUBLIC_ORGANIZER_COLUMNS = 'group_id,display_name,username,avatar_path';

function organizersMissing(message: string): boolean {
  return /schema cache|could not find the table|could not find the relation|does not exist/i.test(message)
    && /published_group_organizers/.test(message);
}

/** Owner of a published group. Missing view reads as none so the page still loads. */
export async function listPublishedGroupOrganizers(groupId: string): Promise<PublicGroupOrganizer[]> {
  if (isDemo()) {
    const g = demoGroups.find((row) => row.id === groupId);
    if (!g || g.archived || !g.public_published_at || !g.owner_id) return [];
    const profile = demoProfiles[g.owner_id];
    if (!profile) return [];
    return [{
      group_id: groupId,
      display_name: profile.display_name ?? null,
      username: profile.username ?? null,
      avatar_path: profile.avatar_path ?? null,
    }];
  }
  const { data, error } = await supabase.from('published_group_organizers').select(PUBLIC_ORGANIZER_COLUMNS).eq('group_id', groupId);
  if (error) {
    if (organizersMissing(error.message)) return [];
    throw new Error(explainGroupError(error.message));
  }
  return (data ?? []) as PublicGroupOrganizer[];
}

export async function saveGroupSponsor(groupId: string, draft: GroupSponsorDraft, id?: string): Promise<void> {
  const fields = sponsorInput(draft);
  if (isDemo()) {
    const now = new Date().toISOString();
    if (id) {
      const row = demoSponsors.find((item) => item.id === id && item.group_id === groupId);
      if (!row) throw new Error('This sponsor is already gone.');
      Object.assign(row, fields, { updated_at: now });
      return;
    }
    const sort_order = demoSponsorsFor(groupId).reduce((max, row) => Math.max(max, row.sort_order), -1) + 1;
    demoSponsors.push({ id: `s-${now}`, group_id: groupId, ...fields, sort_order, created_at: now, updated_at: now });
    return;
  }
  if (id) {
    const { data, error } = await supabase.from('group_sponsors').update(fields).eq('id', id).eq('group_id', groupId).select('id').maybeSingle();
    if (error) throw new Error(explainSponsorError(error.message));
    if (!data) throw new Error('This sponsor is already gone.');
    return;
  }
  const existing = await listGroupSponsors(groupId);
  const sort_order = existing.reduce((max, row) => Math.max(max, row.sort_order), -1) + 1;
  const { error } = await supabase.from('group_sponsors').insert({ ...fields, group_id: groupId, sort_order });
  if (error) throw new Error(explainSponsorError(error.message));
}

export async function deleteGroupSponsor(groupId: string, id: string): Promise<void> {
  if (isDemo()) {
    const index = demoSponsors.findIndex((row) => row.id === id && row.group_id === groupId);
    if (index >= 0) demoSponsors.splice(index, 1);
    return;
  }
  const { error } = await supabase.from('group_sponsors').delete().eq('id', id).eq('group_id', groupId);
  if (error) throw new Error(explainSponsorError(error.message));
}

/** Move a sponsor up (-1) or down (1). Rewrites sort order for that group. */
export async function moveGroupSponsor(groupId: string, id: string, direction: -1 | 1): Promise<void> {
  const rows = await listGroupSponsors(groupId);
  const index = rows.findIndex((row) => row.id === id);
  const nextIndex = index + direction;
  if (index < 0 || nextIndex < 0 || nextIndex >= rows.length) return;
  const next = rows.slice();
  const [item] = next.splice(index, 1);
  next.splice(nextIndex, 0, item);
  if (isDemo()) {
    next.forEach((row, order) => {
      const stored = demoSponsors.find((candidate) => candidate.id === row.id);
      if (stored) stored.sort_order = order;
    });
    return;
  }
  for (let order = 0; order < next.length; order++) {
    if (next[order].sort_order === order) continue;
    const { error } = await supabase.from('group_sponsors').update({ sort_order: order }).eq('id', next[order].id).eq('group_id', groupId);
    if (error) throw new Error(explainSponsorError(error.message));
  }
}
