// Private 1:1 Ask thread. Same bubbles and composer as a direct message. Text only.
import React, { useCallback, useEffect, useRef, useState } from 'react';
import { ActivityIndicator, FlatList, Text, View } from 'react-native';
import { Redirect, router, Stack, useFocusEffect } from 'expo-router';
import { NotFound } from './mod';
import { ChatComposer } from './chat-composer';
import { ChatThreadHeader } from './chat-thread-header';
import { KeyboardSafeScreen, useStickToBottom } from './keyboard-safe-screen';
import { TranscriptMessage } from './transcript';
import { colors, fonts, fs } from '../lib/theme';
import { SOCRATES, canAskSocrates } from '../lib/config';
import { askSocrates, getProfile, listSocratesMessages } from '../lib/api';
import { useSession } from '../lib/session';
import { fmtTime } from '../lib/format';
import { primaryName } from '../lib/names';
import type { Profile, SocratesMessage } from '../lib/types';

const BURST_MS = 5 * 60_000;

export function SocratesThread({ embedded = false }: { embedded?: boolean }) {
  const { userId, loading, isModerator, moderatorChecked, demo } = useSession();
  // debug: God mode only — see canAskSocrates.
  const allowed = canAskSocrates({ userId, isModerator, demo });
  const [me, setMe] = useState<Profile | null>(null);
  const [msgs, setMsgs] = useState<SocratesMessage[] | null>(null);
  const [text, setText] = useState('');
  const [sending, setSending] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const list = useRef<FlatList<SocratesMessage>>(null);
  const stick = useStickToBottom(list);

  const goBack = () => { if (router.canGoBack()) router.back(); else router.replace('/chat'); };

  useFocusEffect(useCallback(() => {
    if (!allowed) return;
    let live = true;
    listSocratesMessages()
      .then((rows) => { if (live) { setMsgs(rows); setErr(null); } })
      .catch((e) => { if (live) { setMsgs([]); setErr(e.message); } });
    return () => { live = false; };
  }, [allowed]));

  useEffect(() => { if (allowed && userId) getProfile(userId).then(setMe).catch(() => {}); }, [allowed, userId]);
  useEffect(() => { setTimeout(() => list.current?.scrollToEnd({ animated: false }), 50); }, [msgs?.length]);

  const send = async () => {
    const body = text.trim();
    if (!body || sending) return;
    setSending(true); setErr(null);
    try {
      const sent = await askSocrates(body);
      setText('');
      setMsgs((cur) => {
        const next = [...(cur ?? [])];
        for (const row of [sent.question, sent.answer]) {
          if (!next.some((item) => item.id === row.id)) next.push(row);
        }
        return next;
      });
    } catch (e: any) { setErr(e.message); } finally { setSending(false); }
  };

  const screen = embedded ? null : <Stack.Screen options={{ headerShown: false, title: SOCRATES.name }} />;

  if (loading || (userId && !demo && !moderatorChecked)) {
    return (
      <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', backgroundColor: colors.paper }}>
        {screen}
        <ActivityIndicator color={colors.navy} />
      </View>
    );
  }
  if (!userId) return <Redirect href="/sign-in" />;
  if (!allowed) return <>{screen}<NotFound /></>;
  if (msgs === null && !err) {
    return (
      <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', backgroundColor: colors.paper }}>
        {screen}
        <ActivityIndicator color={colors.navy} />
      </View>
    );
  }

  const rows = msgs ?? [];
  return (
    <KeyboardSafeScreen>
      {screen}
      <ChatThreadHeader
        name={SOCRATES.name}
        detail={SOCRATES.subtitle}
        online
        onBack={embedded ? undefined : goBack}
      />
      <FlatList
        ref={list}
        style={{ flex: 1, minHeight: 0 }}
        data={rows}
        onScroll={stick.onScroll}
        onLayout={stick.onLayout}
        scrollEventThrottle={stick.scrollEventThrottle}
        keyExtractor={(m) => String(m.id)}
        keyboardShouldPersistTaps="handled"
        contentContainerStyle={{ paddingHorizontal: 16, paddingTop: 8, paddingBottom: 16, width: '100%', maxWidth: 840, alignSelf: 'center', flexGrow: 1 }}
        ListEmptyComponent={
          <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', padding: 24 }}>
            <Text style={{ fontFamily: fonts.sans, fontSize: fs(15), color: colors.muted, textAlign: 'center' }}>Ask about an event, a reading, or how a group works.</Text>
          </View>
        }
        renderItem={({ item: m, index }) => {
          const mine = m.role === 'user';
          const prev = rows[index - 1];
          const next = rows[index + 1];
          const grouped = !!(prev && prev.role === m.role && Date.parse(m.created_at) - Date.parse(prev.created_at) < BURST_MS);
          const showTime = !(next && next.role === m.role && Date.parse(next.created_at) - Date.parse(m.created_at) < BURST_MS);
          return (
            <TranscriptMessage
              label={mine ? 'You' : SOCRATES.name}
              time={fmtTime(m.created_at)}
              body={m.body}
              grouped={grouped}
              showTime={showTime}
              mine={mine}
              accent={!mine}
              avatarName={mine ? primaryName(me) : SOCRATES.name}
              avatarPath={mine ? me?.avatar_path : null}
              avatarUserId={mine ? userId : null}
              onPressAvatar={mine && userId ? () => router.push(`/profile?id=${userId}`) : undefined}
              avatarLabel={mine ? 'Your profile' : undefined}
            />
          );
        }}
      />
      <ChatComposer
        value={text}
        onChangeText={setText}
        onSend={send}
        sending={sending}
        placeholder="Ask about a group"
        error={err}
        includeSafeArea={!embedded}
      />
    </KeyboardSafeScreen>
  );
}
