// Publish-to for a club group. Web sends the public page. Meetup v1 records the
// existing group link. Neither path reads a Meetup member count.
import React, { useCallback, useState } from 'react';
import { Linking, Text, View } from 'react-native';
import { router, useFocusEffect } from 'expo-router';
import { EventCover } from './events';
import { PublishChannelList, PublishConfirmLine, PublishLinkLine, PublishRecordPage, useCopiedShare, usePublishAction } from './publish-to';
import { BackChevron, Button, EmptyState, ErrorText, FieldGrid, Page, styles } from './ui';
import { publicGroupPath } from '../lib/group-views';
import { channelLabel, publicationOutOfDate, publicationStatus, publicationSync, publishedVersionLine, safeMeetupUrl } from '../lib/publications';
import {
  copyPublicGroupLink, getGroup, listGroupPublications, publicGroupUrl,
  setGroupMeetupPublished, setGroupPublished,
} from '../lib/groups';
import { fmtDate } from '../lib/format';
import type { ClubGroup, GroupPublication, GroupSnapshot } from '../lib/types';

export function GroupPublishList({ group }: { group: ClubGroup }) {
  const [rows, setRows] = useState<GroupPublication[] | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const load = useCallback(async () => {
    try { setRows(await listGroupPublications(group.id)); setErr(null); }
    catch (e: any) { setErr(e.message); }
  }, [group.id]);
  useFocusEffect(useCallback(() => { load(); }, [load]));
  const open = useCallback((channel: string) => {
    router.push(`/groups/${group.id}/publish/${encodeURIComponent(channel)}`);
  }, [group.id]);
  return (
    <PublishChannelList currentVersion={group.current_version} rows={rows} error={err} onOpen={open}
      footnote="Edits stay on this club group until you publish." />
  );
}

function SnapshotBody({ snapshot }: { snapshot: GroupSnapshot }) {
  return (
    <>
      {snapshot.image_url ? <View style={{ marginBottom: 12 }}><EventCover url={snapshot.image_url} width={220} /></View> : null}
      <FieldGrid fields={[
        ['Name', snapshot.name],
        ['City', snapshot.locality ?? '—'],
        ['Web address', snapshot.slug],
        ['Meetup', snapshot.meetup_url ?? '—'],
      ]} />
      {snapshot.description ? <Text style={[styles.body, { marginTop: 14 }]}>{snapshot.description}</Text> : null}
    </>
  );
}

function blurb(channel: string, s: { archived: boolean; on: boolean; outOfDate: boolean; linked: boolean }) {
  if (channel === 'web') {
    if (s.archived) return 'Archived groups stay off the public page. Restore the group before publishing.';
    if (s.outOfDate) return 'The public page is still the last version you published. Publish changes to send the current group.';
    if (s.on) return 'Anyone with the link can see the name, city, about, and cover you last published. Later edits stay on the club group until you publish changes.';
    return 'The public page is off. Publishing sends this group to gnosis.events.';
  }
  if (channel === 'meetup') {
    if (!s.linked) return 'Add the Meetup group URL on the club group, then publish. This records that link. It does not create a Meetup group, and it does not bring Meetup’s member count into the app.';
    if (s.outOfDate) return 'Gnosis Events is still showing the last version you marked published. Publish changes records the current group against that same Meetup link. Meetup’s member count stays on Meetup.';
    if (s.on) return 'This club group is marked published on Meetup. The link opens the Meetup group. Edits here do not change Meetup until you publish changes, and member counts are not imported.';
    return 'A Meetup URL is saved, and this channel is not marked published. Publishing records the link in Gnosis Events. It does not change the Meetup group.';
  }
  return 'This channel uses the same publish record. Publishing it is not available in this version of the app.';
}

export function GroupPublishScreen({ groupId, channel }: { groupId: string; channel: string }) {
  const [group, setGroup] = useState<ClubGroup | null | undefined>(undefined);
  const [pub, setPub] = useState<GroupPublication | null>(null);
  const [confirming, setConfirming] = useState(false);
  const load = useCallback(async () => {
    const row = await getGroup(groupId);
    setGroup(row);
    if (!row) { setPub(null); return; }
    const pubs = await listGroupPublications(row.id);
    setPub(pubs.find((p) => p.channel === channel) ?? null);
  }, [groupId, channel]);
  const { err, setErr, note, busy, run } = usePublishAction(load);
  const { copy, title: copyTitle } = useCopiedShare(setErr);
  useFocusEffect(useCallback(() => { load().catch((e) => setErr(e.message)); }, [load, setErr]));
  const clearConfirm = () => setConfirming(false);

  const backFallback = `/groups/${groupId}`;
  if (group === undefined) return <Page><BackChevron fallback={backFallback} /><ErrorText>{err}</ErrorText></Page>;
  if (group === null) return <Page><BackChevron fallback="/groups" /><EmptyState icon="people-outline" title="Group not found" /></Page>;

  const label = channelLabel(channel);
  const status = publicationStatus(pub);
  const sync = publicationSync(group.current_version, pub);
  const webOn = channel === 'web' && pub?.status === 'published' && !group.archived;
  const meetupOn = channel === 'meetup' && pub?.status === 'published';
  const outOfDate = publicationOutOfDate(group.current_version, pub);
  const meetupUrl = safeMeetupUrl(pub?.external_url ?? group.meetup_url);
  const linked = !!meetupUrl;
  const known = channel === 'web' || channel === 'meetup';
  const publicSlug = webOn && pub?.snapshot?.slug ? pub.snapshot.slug : group.slug;

  const publishWeb = () => run('web', async () => {
    await setGroupPublished(group.id, true);
    return outOfDate || webOn ? 'Published the latest version to the public page.' : 'Public page is on.';
  }, clearConfirm);
  const unpublishWeb = () => run('web-off', async () => {
    await setGroupPublished(group.id, false);
    return 'Public page is off. Members can still open this group after they sign in.';
  }, clearConfirm);
  const publishMeetup = () => run('meetup', async () => {
    await setGroupMeetupPublished(group.id, true);
    return outOfDate || meetupOn
      ? 'Recorded the latest version against the Meetup group link.'
      : 'Marked published on Meetup. The Meetup group itself is unchanged, and its member count is not imported.';
  }, clearConfirm);
  const unpublishMeetup = () => run('meetup-off', async () => {
    await setGroupMeetupPublished(group.id, false);
    return 'Meetup is no longer marked published in Gnosis Events. The Meetup group is left as it is.';
  }, clearConfirm);

  return (
    <PublishRecordPage label={label} subtitle={group.name} backFallback={backFallback}
      status={status} sync={sync}
      fields={[['Last published', fmtDate(pub?.published_at)], ['City', group.locality ?? '—']]}
      error={err} note={note} lastError={pub?.last_error ?? null}
      body={blurb(channel, { archived: group.archived, on: webOn || meetupOn, outOfDate, linked })}
      versionLine={publishedVersionLine('club group', group.current_version, pub?.published_version)}
      extras={<>
        {channel === 'web' && webOn ? <PublishLinkLine>{publicGroupUrl(publicSlug)}</PublishLinkLine> : null}
        {channel === 'meetup' && meetupUrl ? <PublishLinkLine>{meetupUrl}</PublishLinkLine> : null}
        {confirming && channel === 'web' ? <PublishConfirmLine>Unpublish? The link will stop showing this group.</PublishConfirmLine> : null}
        {confirming && channel === 'meetup' ? <PublishConfirmLine>Unmark Meetup in Gnosis Events? The Meetup group stays.</PublishConfirmLine> : null}
      </>}
      actions={<>
        {channel === 'web' && webOn ? <Button small variant="neutral" icon="link-outline" title={copyTitle} onPress={() => { void copy(() => copyPublicGroupLink(publicSlug)); }} /> : null}
        {channel === 'web' && webOn ? <Button small variant="neutral" icon="open-outline" title="View public page" onPress={() => router.push(publicGroupPath(publicSlug))} /> : null}
        {channel === 'meetup' && meetupUrl ? <Button small variant="neutral" icon="open-outline" title="Open on Meetup" onPress={() => Linking.openURL(meetupUrl)} /> : null}
        {known && channel === 'web' && !group.archived && !webOn ? <Button small icon="globe-outline" title="Publish" loading={busy === 'web'} onPress={publishWeb} /> : null}
        {known && channel === 'web' && webOn && outOfDate ? <Button small icon="cloud-upload-outline" title="Publish changes" loading={busy === 'web'} onPress={publishWeb} /> : null}
        {known && channel === 'web' && webOn && !confirming ? <Button small variant="danger" icon="eye-off-outline" title="Unpublish" onPress={() => setConfirming(true)} /> : null}
        {known && channel === 'meetup' && linked && !group.archived && !meetupOn ? <Button small icon="cloud-upload-outline" title="Publish" loading={busy === 'meetup'} onPress={publishMeetup} /> : null}
        {known && channel === 'meetup' && meetupOn && outOfDate ? <Button small icon="cloud-upload-outline" title="Publish changes" loading={busy === 'meetup'} onPress={publishMeetup} /> : null}
        {known && channel === 'meetup' && meetupOn && !confirming ? <Button small variant="danger" icon="eye-off-outline" title="Unpublish" onPress={() => setConfirming(true)} /> : null}
        {confirming && channel === 'web' ? <Button small variant="danger" title="Unpublish" loading={busy === 'web-off'} onPress={unpublishWeb} /> : null}
        {confirming && channel === 'meetup' ? <Button small variant="danger" title="Unpublish" loading={busy === 'meetup-off'} onPress={unpublishMeetup} /> : null}
        {confirming ? <Button small variant="neutral" title="Keep" disabled={!!busy} onPress={clearConfirm} /> : null}
      </>}
      snapshot={pub?.snapshot ? <SnapshotBody snapshot={pub.snapshot} /> : null} />
  );
}
