// Local platform events (public.events) are the versioned record.
// Publish to sends the current version to Meetup or the public page.
// Meetup sync publishes web only when that channel has no row yet and the
// club event has not ended, and takes the page down when Meetup cancels the
// listing. It does not publish changes.
// Anonymous clients read published_events: the web channel's snapshot, not later edits.
import { FunctionsHttpError } from '@supabase/supabase-js';
import { publicAppUrl } from './public-url';
import { copyPublicPath } from './share-link';
import { publicationSelect } from './publications';
import { publicDescription, publicLocality, publicVenueName } from './place';
import { signedInUserId, supabase } from './supabase';
import { EVENT_END_FALLBACK_MS, attendanceClosed, attendanceClosedMessage, eventEndMs, isAttendanceClosedMessage } from './format';
import { EVENTS_PAST_DAYS } from './event-relation';
import { isDemo, demoEvents, demoPublications } from './demo';
import { trackAppEvent } from './analytics';
import { eventInPublicDirectory, eventVisibility, hiddenBlocksPublish } from './event-visibility';
import type { ClubEvent, EventApplication, EventApplicationStatus, EventPublication, EventSnapshot, EventVisibility, PublicEvent } from './types';

export type EventInput = Pick<ClubEvent, 'title' | 'description' | 'starts_at' | 'ends_at' | 'venue_name' | 'venue_address'> & {
  /** Set when the editor picked a group. Omitted leaves the stored group alone. */
  group_id?: string | null;
  /** Set from the god-mode form. Omitted leaves the stored type alone. */
  visibility?: EventVisibility;
};

/** Columns on public.published_events. The view redacts the room name, the street, and any join link. Hidden rows are not in the view. */
export const PUBLIC_EVENT_COLUMNS = 'id,title,description,starts_at,ends_at,venue_name,venue_address,image_url,meetup_url,meetup_publish_status,public_published_at,visibility';
export const PUBLIC_EVENT_COLUMNS_LEGACY = PUBLIC_EVENT_COLUMNS.replace(',visibility', '');

/** Member select. The room name, the street, and the join URL are not in this list. created_by or owner_id marks Hosting. place_kind is the list-safe format. group_id and owner_id are optional until their migrations. */
const EVENT_COLUMNS = 'id,created_by,title,description,starts_at,ends_at,venue_locality,meetup_id,meetup_url,meetup_publish_status,room_id,archived,created_at,updated_at,image_url,current_version,public_published_at';
const EVENT_COLUMNS_PLACE = `${EVENT_COLUMNS},place_kind`;
const EVENT_COLUMNS_GROUP = `${EVENT_COLUMNS_PLACE},group_id`;
const EVENT_COLUMNS_OWNER = `${EVENT_COLUMNS_GROUP},owner_id`;
const EVENT_COLUMNS_VISIBILITY = `${EVENT_COLUMNS_OWNER},visibility`;
const EVENT_COLUMNS_LEGACY = EVENT_COLUMNS.replace(',venue_locality', '');

export type EventJoinDetails = {
  venue_name: string | null;
  venue_address: string | null;
  online_meeting_url: string | null;
};

// The demo member is going to the Iliad reading, so My Upcoming shows Hosting and Going.
const demoGoing = new Set<string>(['e-iliad']);
const demoUnlisted = new Map<string, string>();
const demoApplications: EventApplication[] = [];

function ensureDemoToken(eventId: string): string {
  for (const [token, id] of demoUnlisted) if (id === eventId) return token;
  const token = (demoUnlisted.size + 1).toString(16).padStart(32, 'a');
  demoUnlisted.set(token, eventId);
  return token;
}

function demoTeaser(e: ClubEvent): PublicEvent {
  return {
    id: e.id,
    title: e.title,
    description: publicDescription(e.description),
    starts_at: e.starts_at,
    ends_at: e.ends_at,
    venue_name: publicVenueName(e.venue_name, e.venue_address),
    venue_address: publicLocality(e.venue_address),
    image_url: e.image_url ?? null,
    meetup_url: null,
    meetup_publish_status: null,
    public_published_at: null,
    visibility: eventVisibility(e.visibility),
  };
}

export function publicEventPath(id: string) {
  return `/e/${id}`;
}

/** Shareable URL. On web, follow the prefix the page is actually served from (/app in production). */
export function publicEventUrl(id: string) {
  return publicAppUrl(publicEventPath(id));
}

export async function copyPublicEventLink(id: string): Promise<'copied' | 'shared' | 'dismissed'> {
  return copyPublicPath(publicEventPath(id));
}

function eventSnapshot(e: Pick<ClubEvent, 'current_version' | 'title' | 'description' | 'starts_at' | 'ends_at' | 'venue_name' | 'venue_address' | 'image_url'>): EventSnapshot {
  return {
    version: e.current_version, title: e.title, description: e.description, starts_at: e.starts_at, ends_at: e.ends_at,
    venue_name: e.venue_name, venue_address: e.venue_address, image_url: e.image_url ?? null,
  };
}

/** What the public page is allowed to show. The database stores this on the web channel. */
function publicSnapshot(s: EventSnapshot): EventSnapshot {
  return {
    ...s,
    description: publicDescription(s.description),
    venue_name: publicVenueName(s.venue_name, s.venue_address),
    venue_address: publicLocality(s.venue_address),
  };
}

function demoUpsertPublication(eventId: string, channel: string, patch: Partial<EventPublication>) {
  const now = new Date().toISOString();
  const i = demoPublications.findIndex((p) => p.event_id === eventId && p.channel === channel);
  if (i < 0) {
    demoPublications.push({
      id: `pub-${channel}-${eventId}`, event_id: eventId, channel, status: 'unpublished',
      published_version: null, published_at: null, snapshot: null, external_id: null, external_url: null,
      last_error: null, updated_at: now, ...patch,
    });
  } else {
    demoPublications[i] = { ...demoPublications[i], ...patch, updated_at: now };
  }
}

export { EVENTS_PAST_DAYS };

// The events table holds 1000+ rows and PostgREST caps responses (max_rows, usually 1000),
// so an unfiltered ascending fetch drops the newest rows — including every upcoming event.
// Only fetch the window the UI renders: anything starting or ending within the last
// EVENTS_PAST_DAYS onward, plus (for moderators) archived rows.
type EventQuery = PromiseLike<{ data: unknown; error: { message: string } | null }>;

function hideDeleted<T extends { is: (column: string, value: null) => T }>(query: T, hide: boolean): T {
  return hide ? query.is('deleted_at', null) : query;
}

async function selectEvents(run: (columns: string, hideDeletedRows: boolean) => EventQuery): Promise<ClubEvent[]> {
  const load = async (hideDeletedRows: boolean) => {
    // owner_id is optional until migration 20261028000002. group_id until 20261028000001.
    // place_kind until 20261026000009. venue_locality is optional on older databases.
    let result = await run(EVENT_COLUMNS_VISIBILITY, hideDeletedRows);
    if (result.error && /visibility/.test(result.error.message)) result = await run(EVENT_COLUMNS_OWNER, hideDeletedRows);
    if (result.error && /owner_id/.test(result.error.message)) result = await run(EVENT_COLUMNS_GROUP, hideDeletedRows);
    if (result.error && /group_id/.test(result.error.message)) result = await run(EVENT_COLUMNS_PLACE, hideDeletedRows);
    if (result.error && /place_kind/.test(result.error.message)) result = await run(EVENT_COLUMNS, hideDeletedRows);
    if (result.error && /venue_locality/.test(result.error.message)) result = await run(EVENT_COLUMNS_LEGACY, hideDeletedRows);
    return result;
  };
  let result = await load(true);
  if (result.error && /deleted_at/.test(result.error.message)) result = await load(false);
  if (result.error) throw result.error;
  return (result.data ?? []) as ClubEvent[];
}

/** City from the stored locality, else from the street line. The street itself is not returned. */
function memberLocality(locality?: string | null, address?: string | null): string | null {
  return publicLocality(locality) ?? publicLocality(address);
}

/** Room name stays off a locked row. Online stays "Online" so the list can say so. */
function lockedVenueName(row: { place_kind?: string | null; venue_name?: string | null; venue_locality?: string | null; venue_address?: string | null }): string | null {
  if (row.place_kind === 'online') return 'Online';
  return publicVenueName(row.venue_name, row.venue_locality ?? row.venue_address);
}

function lockMemberEvent(row: ClubEvent): ClubEvent {
  const locality = memberLocality(row.venue_locality, row.venue_address);
  return {
    ...row,
    venue_locality: locality,
    venue_name: lockedVenueName({ ...row, venue_locality: locality }),
    venue_address: null,
    online_meeting_url: null,
    place_unlocked: false,
  };
}

/** What an anonymous reader is allowed to hold. Drops a room name the view might still send. */
function asPublicEvent(row: PublicEvent): PublicEvent {
  return {
    ...row,
    visibility: eventVisibility(row.visibility),
    description: publicDescription(row.description),
    venue_name: publicVenueName(row.venue_name, row.venue_address),
    venue_address: publicLocality(row.venue_address),
  };
}

/** Directory rows only. A hidden event is not searchable here even if a stale row arrives. */
export function preparePublishedEvents(rows: PublicEvent[]): PublicEvent[] {
  return rows.map(asPublicEvent).filter((row) => eventInPublicDirectory(row));
}

async function selectPublished(run: (columns: string) => EventQuery): Promise<PublicEvent[]> {
  let result = await run(PUBLIC_EVENT_COLUMNS);
  if (result.error && /visibility/.test(result.error.message)) result = await run(PUBLIC_EVENT_COLUMNS_LEGACY);
  if (result.error) throw result.error;
  return preparePublishedEvents((result.data ?? []) as PublicEvent[]);
}

export async function listEvents(includeArchived = false): Promise<ClubEvent[]> {
  if (isDemo()) return demoEvents.map((e) => lockMemberEvent(e));
  const cutoff = new Date(Date.now() - EVENTS_PAST_DAYS * 86400_000).toISOString();
  let rows = await selectEvents((columns, hideDeletedRows) => hideDeleted(supabase.from('events').select(columns)
    .eq('archived', false)
    .or(`starts_at.gte.${cutoff},ends_at.gte.${cutoff}`)
    .order('starts_at', { ascending: true }), hideDeletedRows));
  if (includeArchived) {
    const arch = await selectEvents((columns, hideDeletedRows) => hideDeleted(supabase.from('events').select(columns)
      .eq('archived', true).order('starts_at', { ascending: false }).limit(500), hideDeletedRows));
    rows = rows.concat(arch);
  }
  return rows.map((row) => lockMemberEvent(row));
}

export type MemberEventLinks = {
  /** App RSVP rows (event_rsvps) for this member. */
  attendingIds: string[];
  /** Meetup listing ids where this member is a host. */
  hostedMeetupIds: string[];
};

function relationLookupMissing(message: string) {
  return /schema cache|could not find the (table|relation|function)/i.test(message);
}

function idsFromRows(data: unknown, key: string): string[] {
  if (!Array.isArray(data)) return [];
  const ids: string[] = [];
  for (const row of data) {
    if (typeof row === 'string') {
      if (row) ids.push(row);
      continue;
    }
    if (!row || typeof row !== 'object' || !(key in row)) continue;
    const id = (row as Record<string, unknown>)[key];
    if (typeof id === 'string' && id) ids.push(id);
  }
  return ids;
}

/**
 * One pair of reads for the Events list. Not one query per row.
 * A missing table or function leaves that set empty so an unmigrated database still lists events.
 */
export async function listMemberEventLinks(userId: string): Promise<MemberEventLinks> {
  if (isDemo()) return { attendingIds: [...demoGoing], hostedMeetupIds: [] };
  const [rsvps, hosted] = await Promise.all([
    supabase.from('event_rsvps').select('event_id').eq('user_id', userId).limit(2000),
    supabase.rpc('my_hosted_meetup_ids'),
  ]);
  if (rsvps.error && !relationLookupMissing(rsvps.error.message)) throw rsvps.error;
  if (hosted.error && !relationLookupMissing(hosted.error.message)) throw hosted.error;
  return {
    attendingIds: rsvps.error ? [] : idsFromRows(rsvps.data, 'event_id'),
    hostedMeetupIds: hosted.error ? [] : idsFromRows(hosted.data, 'my_hosted_meetup_ids'),
  };
}

async function selectEvent(id: string): Promise<ClubEvent | null> {
  const rows = await selectEvents((columns, hideDeletedRows) => hideDeleted(supabase.from('events').select(columns).eq('id', id).limit(1), hideDeletedRows));
  return rows[0] ?? null;
}

/** Exact street and Zoom link. Null when this member is not entitled. A missing function means the migration is not applied yet. */
export async function getEventJoinDetails(eventId: string): Promise<EventJoinDetails | null> {
  if (isDemo()) {
    if (!demoGoing.has(eventId)) return null;
    const e = demoEvents.find((row) => row.id === eventId);
    if (!e) return null;
    return { venue_name: e.venue_name, venue_address: e.venue_address, online_meeting_url: e.online_meeting_url ?? null };
  }
  const { data, error } = await supabase.rpc('event_join_details', { p_event_id: eventId });
  if (error) {
    if (/event_join_details|schema cache|could not find the function/i.test(error.message)) return null;
    throw error;
  }
  const row = (Array.isArray(data) ? data[0] : data) as EventJoinDetails | undefined;
  return row ?? null;
}

export async function myEventRsvp(eventId: string, userId: string): Promise<boolean> {
  if (isDemo()) return demoGoing.has(eventId);
  const { data, error } = await supabase.from('event_rsvps').select('event_id').eq('event_id', eventId).eq('user_id', userId).maybeSingle();
  if (error) {
    if (/event_rsvps|schema cache|could not find the (table|relation)/i.test(error.message)) return false;
    throw error;
  }
  return !!data;
}

/** App Attend. Idempotent. Does not write a Meetup RSVP. Refuses a past event before insert. */
export async function attendEvent(eventId: string, userId: string): Promise<void> {
  if (isDemo()) {
    const demo = demoEvents.find((row) => row.id === eventId);
    if (demo && attendanceClosed(demo)) throw new Error(attendanceClosedMessage(demo));
    demoGoing.add(eventId);
    return;
  }
  const row = await selectEvent(eventId);
  if (!row) throw new Error('This event isn’t available.');
  if (attendanceClosed(row)) throw new Error(attendanceClosedMessage(row));
  const { error } = await supabase.from('event_rsvps').insert({ event_id: eventId, user_id: userId });
  if (error && !/duplicate key|23505/i.test(error.message)) {
    if (isAttendanceClosedMessage(error.message)) throw new Error(attendanceClosedMessage(row));
    throw error;
  }
  if (!error) trackAppEvent('rsvp', { action: 'attend' });
}

export async function myEventApplication(eventId: string, userId: string): Promise<EventApplicationStatus | null> {
  if (isDemo()) return demoApplications.find((row) => row.event_id === eventId && row.user_id === userId)?.status ?? null;
  const { data, error } = await supabase.from('event_applications').select('status').eq('event_id', eventId).eq('user_id', userId).maybeSingle();
  if (error) {
    if (relationLookupMissing(error.message)) return null;
    throw error;
  }
  const status = data && typeof data === 'object' && 'status' in data ? data.status : null;
  if (status === 'pending' || status === 'approved' || status === 'declined') return status;
  return null;
}

export async function listEventApplications(eventId: string): Promise<EventApplication[]> {
  if (isDemo()) return demoApplications.filter((row) => row.event_id === eventId).map((row) => ({ ...row }));
  const { data, error } = await supabase.from('event_applications')
    .select('event_id,user_id,status,created_at,decided_at')
    .eq('event_id', eventId)
    .order('created_at', { ascending: true });
  if (error) {
    if (relationLookupMissing(error.message)) return [];
    throw error;
  }
  return (data ?? []) as EventApplication[];
}

/** Private events. Does not create an RSVP. A declined application can be sent again. */
export async function applyToEvent(eventId: string): Promise<EventApplicationStatus> {
  if (isDemo()) {
    const event = demoEvents.find((row) => row.id === eventId);
    if (!event || eventVisibility(event.visibility) !== 'private') throw new Error('This event is not available.');
    if (attendanceClosed(event)) throw new Error(attendanceClosedMessage(event));
    const existing = demoApplications.find((row) => row.event_id === eventId && row.user_id === 'demo-me');
    if (existing?.status === 'approved') throw new Error('You are already approved.');
    if (existing) {
      existing.status = 'pending';
      existing.decided_at = null;
      return 'pending';
    }
    demoApplications.push({ event_id: eventId, user_id: 'demo-me', status: 'pending', created_at: new Date().toISOString(), decided_at: null });
    return 'pending';
  }
  const { data, error } = await supabase.rpc('apply_to_event', { p_event_id: eventId });
  if (error) {
    if (isAttendanceClosedMessage(error.message)) throw new Error(error.message);
    throw error;
  }
  return data === 'approved' || data === 'declined' || data === 'pending' ? data : 'pending';
}

/** Owner or moderator. Approve writes a normal RSVP. Decline removes one. */
export async function decideEventApplication(eventId: string, userId: string, approve: boolean): Promise<void> {
  if (isDemo()) {
    const row = demoApplications.find((item) => item.event_id === eventId && item.user_id === userId);
    if (!row) throw new Error('Application not found.');
    row.status = approve ? 'approved' : 'declined';
    row.decided_at = new Date().toISOString();
    if (approve) demoGoing.add(eventId);
    else demoGoing.delete(eventId);
    return;
  }
  const { error } = await supabase.rpc('decide_event_application', { p_event_id: eventId, p_user_id: userId, p_approve: approve });
  if (error) throw error;
}

/** Hidden event teaser. Empty when the token does not match a live hidden event. */
export async function getUnlistedEvent(token: string): Promise<PublicEvent | null> {
  if (!/^[0-9a-f]{32}$/.test(token)) return null;
  if (isDemo()) {
    const id = demoUnlisted.get(token);
    const event = id ? demoEvents.find((row) => row.id === id) : undefined;
    if (!event || event.archived || eventVisibility(event.visibility) !== 'hidden') return null;
    return demoTeaser(event);
  }
  const { data, error } = await supabase.rpc('unlisted_event', { p_token: token });
  if (error) {
    if (relationLookupMissing(error.message)) return null;
    throw error;
  }
  const row = (Array.isArray(data) ? data[0] : data) as PublicEvent | undefined;
  return row ? asPublicEvent(row) : null;
}

/** Signed-in RSVP through the secret link. One account, no plus-ones. Returns the event id. */
export async function attendUnlistedEvent(token: string): Promise<string> {
  if (isDemo()) {
    const id = demoUnlisted.get(token);
    const event = id ? demoEvents.find((row) => row.id === id) : undefined;
    if (!event || eventVisibility(event.visibility) !== 'hidden') throw new Error('This event is not available.');
    if (attendanceClosed(event)) throw new Error(attendanceClosedMessage(event));
    demoGoing.add(event.id);
    return event.id;
  }
  const { data, error } = await supabase.rpc('attend_unlisted_event', { p_token: token });
  if (error) {
    if (isAttendanceClosedMessage(error.message)) throw new Error(error.message);
    throw new Error(error.message || 'This event is not available.');
  }
  if (typeof data !== 'string' || !data) throw new Error('This event is not available.');
  trackAppEvent('rsvp', { action: 'attend' });
  return data;
}

/** Moderator or owner. Null unless the event is hidden. */
export async function eventUnlistedToken(eventId: string): Promise<string | null> {
  if (isDemo()) {
    const event = demoEvents.find((row) => row.id === eventId);
    if (!event || eventVisibility(event.visibility) !== 'hidden') return null;
    return ensureDemoToken(eventId);
  }
  const { data, error } = await supabase.rpc('event_unlisted_token', { p_event_id: eventId });
  if (error) {
    if (relationLookupMissing(error.message)) return null;
    throw error;
  }
  return typeof data === 'string' && data ? data : null;
}

export async function cancelAttend(eventId: string, userId: string): Promise<void> {
  if (isDemo()) { demoGoing.delete(eventId); return; }
  const { error } = await supabase.from('event_rsvps').delete().eq('event_id', eventId).eq('user_id', userId);
  if (error) throw error;
  trackAppEvent('rsvp', { action: 'cancel' });
}

/** Moderator edit form. Includes the street. The member event page uses getEvent, which does not. */
export async function getEventForEdit(id: string): Promise<ClubEvent | null> {
  if (isDemo()) return demoEvents.find((row) => row.id === id) ?? null;
  const row = await selectEvent(id);
  if (!row) return null;
  row.venue_locality = memberLocality(row.venue_locality);
  row.place_unlocked = true;
  row.venue_name = null;
  row.venue_address = null;
  row.online_meeting_url = null;
  try {
    const join = await getEventJoinDetails(id);
    if (join) {
      row.venue_name = join.venue_name;
      row.venue_address = join.venue_address;
      row.online_meeting_url = join.online_meeting_url;
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    if (!/event_join_details|schema cache|could not find the function/i.test(message)) throw err;
  }
  return row;
}

export async function getEvent(id: string): Promise<ClubEvent | null> {
  if (isDemo()) {
    const e = demoEvents.find((row) => row.id === id);
    if (!e) return null;
    if (!demoGoing.has(id)) return lockMemberEvent(e);
    return { ...e, venue_locality: memberLocality(e.venue_locality, e.venue_address), place_unlocked: true };
  }
  const row = await selectEvent(id);
  if (!row) return null;
  const locked = lockMemberEvent(row);
  try {
    const join = await getEventJoinDetails(id);
    if (join) {
      locked.venue_name = join.venue_name ?? locked.venue_name;
      locked.venue_address = join.venue_address;
      locked.online_meeting_url = join.online_meeting_url;
      locked.place_unlocked = true;
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    if (!/event_join_details|schema cache|could not find the function/i.test(message)) throw err;
  }
  return locked;
}

/** Demo public card. Same web snapshot the published_events view serves. */
function demoPublishedEvent(e: ClubEvent): PublicEvent | null {
  if (e.archived || !eventInPublicDirectory(e)) return null;
  const web = demoPublications.find((p) => p.event_id === e.id && p.channel === 'web' && p.status === 'published');
  if (!web?.snapshot) return null;
  const meetup = demoPublications.find((p) => p.event_id === e.id && p.channel === 'meetup' && (p.status === 'published' || p.status === 'cancelled'));
  const s = publicSnapshot(web.snapshot);
  return {
    id: e.id, title: s.title, description: s.description, starts_at: s.starts_at, ends_at: s.ends_at,
    venue_name: s.venue_name, venue_address: s.venue_address, image_url: s.image_url,
    meetup_url: meetup?.external_url ?? null,
    meetup_publish_status: meetup?.status === 'cancelled' ? 'CANCELLED' : meetup?.status === 'published' ? 'PUBLISHED' : null,
    public_published_at: web.published_at,
    visibility: eventVisibility(e.visibility),
  };
}

/**
 * Every published public page, soonest first.
 * The view is the web-channel snapshot. Anonymous clients can select it.
 * Unfiltered: PostgREST max-rows (usually 1000) keeps the oldest rows and
 * drops later ones. The preview uses listUpcomingPublishedEvents.
 * getPublishedEvent still loads one past page by id while it stays published.
 */
async function listPublishedEvents(): Promise<PublicEvent[]> {
  if (isDemo()) {
    return demoEvents.map(demoPublishedEvent).filter((e): e is PublicEvent => !!e).sort((a, b) => a.starts_at.localeCompare(b.starts_at));
  }
  return selectPublished((columns) => supabase.from('published_events').select(columns).order('starts_at', { ascending: true }));
}

/**
 * Published pages that have not ended, soonest first.
 * End instant matches eventEndMs: ends_at when set, otherwise starts_at + 3h.
 * Filtered in the query so a backlog of past published rows cannot crowd out
 * upcoming ones under PostgREST's row cap.
 */
export async function listUpcomingPublishedEvents(): Promise<PublicEvent[]> {
  if (isDemo()) {
    const rows = await listPublishedEvents();
    return rows.filter((e) => {
      const end = eventEndMs(e);
      return end != null && end > Date.now();
    });
  }
  const now = Date.now();
  const nowIso = new Date(now).toISOString();
  const openEndedCutoff = new Date(now - EVENT_END_FALLBACK_MS).toISOString();
  return selectPublished((columns) => supabase.from('published_events').select(columns)
    .or(`ends_at.gt.${nowIso},and(ends_at.is.null,starts_at.gt.${openEndedCutoff})`)
    .order('starts_at', { ascending: true }));
}

/** Public page read. The view returns the web snapshot, not unpublished edits. Hidden events are not here. */
export async function getPublishedEvent(id: string): Promise<PublicEvent | null> {
  if (isDemo()) {
    const e = demoEvents.find((row) => row.id === id);
    return e ? demoPublishedEvent(e) : null;
  }
  try {
    const rows = await selectPublished((columns) => supabase.from('published_events').select(columns).eq('id', id).limit(1));
    return rows[0] ?? null;
  } catch (error) {
    const message = error && typeof error === 'object' && 'message' in error && typeof error.message === 'string' ? error.message : '';
    if (/invalid input syntax for type uuid/i.test(message)) return null;
    throw error;
  }
}

export async function listEventPublications(eventId: string): Promise<EventPublication[]> {
  if (isDemo()) return demoPublications.filter((p) => p.event_id === eventId);
  const { data, error } = await supabase.from('event_publications')
    .select(publicationSelect('event_id'))
    .eq('event_id', eventId);
  if (error) throw error;
  return (data ?? []) as EventPublication[];
}

/** Moderator-only. Publishing again sends the current version (publish changes). Archived events stay off. */
export async function setEventPublished(id: string, published: boolean): Promise<string | null> {
  if (isDemo()) {
    const e = demoEvents.find((row) => row.id === id);
    if (!e) throw new Error('Event not found.');
    if (e.archived && published) throw new Error('Archived events stay off the public page.');
    if (published && hiddenBlocksPublish(e.visibility)) throw new Error('Hidden events are not published to the web directory or Meetup.');
    e.public_published_at = published ? new Date().toISOString() : null;
    if (published) {
      demoUpsertPublication(id, 'web', { status: 'published', published_version: e.current_version, published_at: e.public_published_at, snapshot: publicSnapshot(eventSnapshot(e)), last_error: null });
    } else {
      const row = demoPublications.find((p) => p.event_id === id && p.channel === 'web');
      if (row) demoUpsertPublication(id, 'web', { status: 'unpublished' });
    }
    return e.public_published_at;
  }
  if (published) {
    const current = await selectEvent(id);
    if (current && hiddenBlocksPublish(current.visibility)) throw new Error('Hidden events are not published to the web directory or Meetup.');
  }
  const { data, error } = await supabase.from('events')
    .update({ public_published_at: published ? new Date().toISOString() : null })
    .eq('id', id)
    .select('public_published_at')
    .maybeSingle();
  if (error) throw error;
  if (!data) throw new Error('You can’t change the public page.');
  if (published && !data.public_published_at) throw new Error('Archived events stay off the public page.');
  return data.public_published_at;
}

/** Create or update. On create with withRoom, also creates a linked chat room (kind 'event'). Returns the id. */
export async function saveEvent(input: EventInput, id?: string, withRoom = false): Promise<string> {
  if (isDemo()) {
    if (!id) return demoEvents[0].id;
    const e = demoEvents.find((row) => row.id === id);
    if (e) {
      const changed = e.title !== input.title || e.description !== input.description || e.starts_at !== input.starts_at
        || e.ends_at !== input.ends_at || e.venue_name !== input.venue_name || e.venue_address !== input.venue_address;
      Object.assign(e, input, { updated_at: new Date().toISOString() });
      if (input.visibility === 'hidden') ensureDemoToken(e.id);
      if (changed) e.current_version += 1;
    }
    return id;
  }
  const payload: EventInput = { ...input };
  if (!payload.visibility) delete payload.visibility;
  if (id) {
    const { error } = await supabase.from('events').update(payload).eq('id', id);
    if (error) throw error;
    const { data: ev } = await supabase.from('events').select('room_id').eq('id', id).maybeSingle();
    if (ev?.room_id) await supabase.from('rooms').update({ title: input.title, starts_at: input.starts_at, ends_at: input.ends_at }).eq('id', ev.room_id);
    return id;
  }
  const owner_id = await signedInUserId();
  let room_id: string | null = null;
  if (withRoom) {
    const { data: room, error } = await supabase.from('rooms').insert({ kind: 'event', title: input.title, description: input.description.slice(0, 500), starts_at: input.starts_at, ends_at: input.ends_at }).select('id').single();
    if (error) throw error;
    room_id = room.id;
  }
  const { data, error } = await supabase.from('events').insert({ ...payload, room_id, owner_id, created_by: owner_id }).select('id').single();
  if (error) throw error;
  return data.id;
}

export async function setEventArchived(id: string, archived: boolean) {
  if (isDemo()) {
    const e = demoEvents.find((row) => row.id === id);
    if (!e) return;
    e.archived = archived;
    if (archived) {
      e.public_published_at = null;
      const web = demoPublications.find((p) => p.event_id === id && p.channel === 'web' && p.status === 'published');
      if (web) demoUpsertPublication(id, 'web', { status: 'unpublished' });
    }
    return;
  }
  // Archiving clears public_published_at in the database trigger and unpublishes web. Restoring does not publish.
  const { error } = await supabase.from('events').update({ archived }).eq('id', id);
  if (error) throw error;
}

export type DeleteEventOptions = {
  /** Clear the club Meetup id. Does not cancel the listing on Meetup. */
  unlinkMeetup?: boolean;
};

function explainDeleteError(message: string): string {
  const m = message.toLowerCase();
  if (m.includes('not allowed') || m.includes('42501')) return 'You can’t delete this event.';
  if (m.includes('event not found') || m.includes('p0002')) return 'This event is already gone.';
  if (/delete_club_event|schema cache|could not find the function/i.test(message)) return 'Deleting events isn’t available yet.';
  return message;
}

/** Moderator, creator, or linked Meetup host. False when the check is not deployed yet. */
export async function canDeleteEvent(id: string): Promise<boolean> {
  if (isDemo()) return false;
  const { data, error } = await supabase.rpc('event_delete_allowed', { p_event_id: id });
  if (error) {
    if (/event_delete_allowed|schema cache|could not find the function/i.test(error.message)) return false;
    throw error;
  }
  return data === true;
}

/**
 * Soft-delete. Always removes the club event, its app RSVPs, and the public page.
 * Meetup is not cancelled. There is no RSVP email or tip cleanup in this path.
 */
export async function deleteEvent(id: string, options: DeleteEventOptions = {}) {
  if (isDemo()) {
    const i = demoEvents.findIndex((row) => row.id === id);
    if (i >= 0) demoEvents.splice(i, 1);
    return;
  }
  const { error } = await supabase.rpc('delete_club_event', {
    p_event_id: id,
    p_unlink_meetup: options.unlinkMeetup === true,
  });
  if (error) throw new Error(explainDeleteError(error.message));
}

export type MeetupAction = 'publish' | 'update' | 'unpublish' | 'pull';
export async function meetupEventAction(event_id: string, action: MeetupAction): Promise<{ meetup_url?: string | null; status?: string; warnings: string[]; applied?: boolean }> {
  if (isDemo()) {
    const e = demoEvents.find((row) => row.id === event_id);
    if (!e) throw new Error('Event not found.');
    let warn = 'Demo mode — nothing was sent to Meetup.';
    if ((action === 'publish' || action === 'update') && hiddenBlocksPublish(e.visibility)) {
      throw new Error('Hidden events are not published to Meetup.');
    }
    if (action === 'publish') {
      if (e.meetup_id) throw new Error('Already on Meetup. Use Push.');
      e.meetup_id = `demo-${e.id}`;
      e.meetup_url = 'https://www.meetup.com/reading-philosophy/';
      e.meetup_publish_status = 'PUBLISHED';
      demoUpsertPublication(e.id, 'meetup', { status: 'published', published_version: e.current_version, published_at: new Date().toISOString(), snapshot: eventSnapshot(e), external_id: e.meetup_id, external_url: e.meetup_url, last_error: null });
    } else if (action === 'update') {
      if (!e.meetup_id) throw new Error('This event is not on Meetup yet. Publish it first.');
      e.meetup_publish_status = 'PUBLISHED';
      demoUpsertPublication(e.id, 'meetup', { status: 'published', published_version: e.current_version, published_at: new Date().toISOString(), snapshot: eventSnapshot(e), external_id: e.meetup_id, external_url: e.meetup_url, last_error: null });
    } else if (action === 'unpublish') {
      if (!e.meetup_id) throw new Error('This event is not on Meetup yet. Publish it first.');
      e.meetup_publish_status = 'CANCELLED';
      const row = demoPublications.find((p) => p.event_id === e.id && p.channel === 'meetup');
      demoUpsertPublication(e.id, 'meetup', { status: 'cancelled', external_id: e.meetup_id, external_url: row?.external_url ?? e.meetup_url });
    } else if (action === 'pull') {
      if (!e.meetup_id) throw new Error('This event is not on Meetup yet. Publish it first.');
      const row = demoPublications.find((p) => p.event_id === e.id && p.channel === 'meetup');
      const snap = row?.snapshot;
      if (!snap) throw new Error('Nothing has been sent to Meetup yet.');
      const image = snap.image_url ?? null;
      const changed = e.title !== snap.title || e.description !== snap.description || e.starts_at !== snap.starts_at
        || (e.ends_at ?? null) !== (snap.ends_at ?? null) || (e.venue_name ?? null) !== (snap.venue_name ?? null)
        || (e.venue_address ?? null) !== (snap.venue_address ?? null) || (e.image_url ?? null) !== image;
      e.title = snap.title;
      e.description = snap.description;
      e.starts_at = snap.starts_at;
      e.ends_at = snap.ends_at;
      e.venue_name = snap.venue_name;
      e.venue_address = snap.venue_address;
      e.image_url = image;
      e.updated_at = new Date().toISOString();
      if (changed) e.current_version += 1;
      if (row.status !== 'cancelled') e.meetup_publish_status = 'PUBLISHED';
      demoUpsertPublication(e.id, 'meetup', {
        status: row.status === 'cancelled' ? 'cancelled' : 'published',
        published_version: e.current_version,
        published_at: new Date().toISOString(),
        snapshot: eventSnapshot(e),
        external_id: e.meetup_id,
        external_url: e.meetup_url,
        last_error: null,
      });
      warn = 'Demo mode. Club event set to the last sent listing.';
    }
    return { warnings: [warn], applied: action === 'pull', meetup_url: e.meetup_url, status: e.meetup_publish_status ?? undefined };
  }
  const { data, error } = await supabase.functions.invoke('meetup-publish-event', { body: { event_id, action } });
  if (error) {
    let msg = 'Meetup request failed.';
    if (error instanceof FunctionsHttpError) { try { const j = await error.context.json(); msg = j.message ?? j.error ?? msg; } catch {} }
    throw new Error(msg);
  }
  return { warnings: [], ...data };
}

export async function eventIdForMeetup(meetupId: string): Promise<string | null> {
  if (isDemo()) return demoEvents.find((e) => e.meetup_id === meetupId)?.id ?? null;
  let res = await supabase.from('events').select('id').eq('meetup_id', meetupId).is('deleted_at', null).maybeSingle();
  if (res.error && /deleted_at/.test(res.error.message)) {
    res = await supabase.from('events').select('id').eq('meetup_id', meetupId).maybeSingle();
  }
  return res.data?.id ?? null;
}
