// Lifts a bottom-pinned composer above the software keyboard.
// Same inset as sign-in: KeyboardAvoidingView padding with a screen-space
// offset, then lib/keyboard-inset's tail when that still leaves the frame
// covered (Android edge-to-edge, web, or a short status-bar gap).
import React, { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type ComponentRef, type ReactNode, type RefObject } from 'react';
import { Dimensions, Keyboard, KeyboardAvoidingView, Platform, View } from 'react-native';
import { initialWindowMetrics } from 'react-native-safe-area-context';
import { colors } from '../lib/theme';
import {
  KEYBOARD_SETTLE_FRAMES,
  KEYBOARD_TAIL_CATCH_UP,
  coveredByKeyboard,
  keyboardTopFromEvent,
  nextKeyboardTail,
  visualKeyboardOverlap,
} from '../lib/keyboard-inset';

type Box = { x: number; y: number; width: number; height: number };
type Measurable = { measureInWindow?: (cb: (x: number, y: number, width: number, height: number) => void) => void };
type StickList = { scrollToEnd: (options?: { animated?: boolean }) => void };
type KeyboardEnd = { endCoordinates: { screenY: number; height: number }; duration?: number };

const KeyboardInsetContext = createContext({ open: false, remeasure: () => {} });

/** Whether the surrounding KeyboardSafeScreen currently has the software keyboard open. */
export function useKeyboardInset() {
  return useContext(KeyboardInsetContext);
}

function measureBox(node: unknown, cb: (box: Box) => void) {
  const view = node as Measurable | null;
  if (view && typeof view.measureInWindow === 'function') {
    view.measureInWindow((x, y, width, height) => cb({ x, y, width, height }));
  }
}

/**
 * Keep the latest messages against the composer when the thread gets shorter
 * (keyboard open, or the field grows). Leave a reader who scrolled up where they are.
 */
export function useStickToBottom<T extends StickList>(listRef: RefObject<T | null>) {
  const pinned = useRef(true);
  const height = useRef(0);
  const onScroll = useCallback((e: { nativeEvent: { contentOffset: { y: number }; contentSize: { height: number }; layoutMeasurement: { height: number } } }) => {
    const { contentOffset, contentSize, layoutMeasurement } = e.nativeEvent;
    pinned.current = contentSize.height - layoutMeasurement.height - contentOffset.y < 80;
  }, []);
  const onLayout = useCallback((e: { nativeEvent: { layout: { height: number } } }) => {
    const h = e.nativeEvent.layout.height;
    const changed = height.current > 0 && Math.abs(h - height.current) > 1;
    height.current = h;
    if (changed && pinned.current) requestAnimationFrame(() => listRef.current?.scrollToEnd({ animated: false }));
  }, [listRef]);
  return { onScroll, onLayout, scrollEventThrottle: 16 as const };
}

export function KeyboardSafeScreen({ children }: { children: ReactNode }) {
  const frameRef = useRef<ComponentRef<typeof View>>(null);
  const viewportRef = useRef<ComponentRef<typeof View>>(null);
  const tailRef = useRef(0);
  const keyboardLimitRef = useRef<number | null>(null);
  const keyboardDurationRef = useRef(0);
  // Distance from the physical top of the screen to this view. The shell pads
  // the status bar outside the screen, and the nested safe-area context reports
  // top as 0, so KeyboardAvoidingView's parent-relative y would stop short.
  const [offset, setOffset] = useState(() => (
    Platform.OS === 'web' ? 0 : Math.max(0, Math.round(initialWindowMetrics?.insets.top ?? 0))
  ));
  // Extra padding when the avoiding view has not cleared the keyboard.
  const [tail, setTail] = useState(0);
  const [keyboardTop, setKeyboardTop] = useState<number | null>(null);

  const revealRef = useRef<(attempt: number) => void>(() => {});
  revealRef.current = (attempt: number) => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    measureBox(viewport, (view) => {
      const limit = keyboardLimitRef.current;
      if (limit == null) return;
      if (view.height < 1 && attempt < KEYBOARD_SETTLE_FRAMES) {
        requestAnimationFrame(() => revealRef.current(attempt + 1));
        return;
      }
      const stillCovered = coveredByKeyboard(view.y, view.height, limit);
      // Give KeyboardAvoidingView a few frames to pad before adding our own.
      if (stillCovered > KEYBOARD_TAIL_CATCH_UP && attempt < KEYBOARD_SETTLE_FRAMES) {
        requestAnimationFrame(() => revealRef.current(attempt + 1));
        return;
      }
      if (keyboardLimitRef.current == null) return;
      const nextTail = nextKeyboardTail(view.y, view.height, keyboardLimitRef.current, tailRef.current);
      if (nextTail !== tailRef.current) {
        tailRef.current = nextTail;
        setTail(nextTail);
      }
    });
  };

  const remeasure = useCallback(() => {
    if (keyboardLimitRef.current == null) return;
    revealRef.current(0);
  }, []);

  useEffect(() => {
    if (Platform.OS !== 'web' || typeof window === 'undefined') return;
    const vv = window.visualViewport;
    if (!vv) return;
    const sync = () => {
      const overlap = visualKeyboardOverlap(window.innerHeight, vv.height, vv.offsetTop);
      const top = overlap > 0 ? vv.height : null;
      keyboardLimitRef.current = top;
      keyboardDurationRef.current = 0;
      tailRef.current = overlap;
      setTail((prev) => (prev === overlap ? prev : overlap));
      setKeyboardTop((prev) => (prev === top ? prev : top));
    };
    vv.addEventListener('resize', sync);
    vv.addEventListener('scroll', sync);
    sync();
    return () => {
      vv.removeEventListener('resize', sync);
      vv.removeEventListener('scroll', sync);
    };
  }, []);

  useEffect(() => {
    if (Platform.OS === 'web') return;
    const showEvent = Platform.OS === 'ios' ? 'keyboardWillShow' : 'keyboardDidShow';
    const hideEvent = Platform.OS === 'ios' ? 'keyboardWillHide' : 'keyboardDidHide';
    const apply = (e: KeyboardEnd) => {
      const top = keyboardTopFromEvent(e.endCoordinates.screenY, e.endCoordinates.height, Dimensions.get('window').height);
      keyboardLimitRef.current = top;
      keyboardDurationRef.current = Platform.OS === 'ios' ? Math.max(0, e.duration ?? 250) : 0;
      setKeyboardTop((prev) => (prev === top ? prev : top));
    };
    const show = Keyboard.addListener(showEvent, apply);
    // A taller emoji keyboard does not hide and show again; it only changes frame.
    const change = Platform.OS === 'ios'
      ? Keyboard.addListener('keyboardWillChangeFrame', (e) => {
        const top = keyboardTopFromEvent(e.endCoordinates.screenY, e.endCoordinates.height, Dimensions.get('window').height);
        const windowHeight = Dimensions.get('window').height;
        if (top == null || (windowHeight > 0 && top >= windowHeight - 1)) return;
        apply(e);
      })
      : null;
    const hide = Keyboard.addListener(hideEvent, () => {
      keyboardLimitRef.current = null;
      keyboardDurationRef.current = 0;
      tailRef.current = 0;
      setTail(0);
      setKeyboardTop(null);
    });
    return () => {
      show.remove();
      change?.remove();
      hide.remove();
    };
  }, []);

  useEffect(() => {
    if (keyboardTop == null) return;
    // Wait out the iOS keyboard animation on the first lift. A later correction
    // should measure the layout that just committed.
    const delay = tail > 0 ? 0 : keyboardDurationRef.current;
    const id = setTimeout(() => revealRef.current(0), delay);
    return () => clearTimeout(id);
  }, [keyboardTop, tail]);

  const onFrameLayout = () => {
    if (Platform.OS === 'web') return;
    measureBox(frameRef.current, (frame) => {
      const next = Math.max(0, Math.round(frame.y));
      setOffset((prev) => (Math.abs(prev - next) <= 1 ? prev : next));
    });
  };

  // If our fallback padding landed and the avoiding view then caught up, drop
  // the extra padding so the composer is not followed by a blank gap.
  const onViewportLayout = () => {
    const limit = keyboardLimitRef.current;
    if (limit == null || tailRef.current <= 0) return;
    measureBox(viewportRef.current, (view) => {
      if (keyboardLimitRef.current == null) return;
      const nextTail = nextKeyboardTail(view.y, view.height, keyboardLimitRef.current, tailRef.current);
      if (nextTail < tailRef.current) {
        tailRef.current = nextTail;
        setTail(nextTail);
      }
    });
  };

  const open = keyboardTop != null;
  const inset = useMemo(() => ({ open, remeasure }), [open, remeasure]);

  return (
    <KeyboardInsetContext.Provider value={inset}>
      <View ref={frameRef} style={{ flex: 1, minHeight: 0, backgroundColor: colors.paper }} onLayout={onFrameLayout}>
        {/* Android edge-to-edge keeps the window full height, so padding (not an
            undefined behavior) has to lift the composer. Web uses the tail below. */}
        <KeyboardAvoidingView
          behavior={Platform.OS === 'web' ? undefined : 'padding'}
          keyboardVerticalOffset={offset}
          style={{ flex: 1, minHeight: 0 }}
        >
          <View
            ref={viewportRef}
            style={{ flex: 1, minHeight: 0, paddingBottom: tail }}
            collapsable={false}
            onLayout={onViewportLayout}
          >
            {children}
          </View>
        </KeyboardAvoidingView>
      </View>
    </KeyboardInsetContext.Provider>
  );
}
