// First-party product events. Coarse inserts go through track_app_event (the
// caller's own user id). Event-page views go through the track-event-view edge
// function, which records the request IP and user agent. Failures are ignored
// so a missing migration never blocks the app.
import { useEffect, useRef } from 'react';
import { Platform } from 'react-native';
import { supabase } from './supabase';
import { isDemo } from './demo';
import { peekDeviceLocation } from './device-location';
import { parseEventAnalytics, parseGroupAnalytics, screenNameFromPath, type AppAnalyticsSummary, type AppEventName, type EventAnalytics, type GroupAnalytics } from './analytics-screen';

export {
  APP_EVENTS,
  APP_EVENT_LABELS,
  dailyEventTotals,
  eventViewDetail,
  eventViewPlace,
  eventViewerLabel,
  namedEventTotals,
  screenLabel,
  screenNameFromPath,
  viewerCountSentence,
} from './analytics-screen';
export type { AppAnalyticsDay, AppAnalyticsSummary, AppEventName, AppEventTotal, EventAnalytics, EventAnalyticsView, GroupAnalytics, GroupAnalyticsEvent } from './analytics-screen';
export { parseGroupAnalytics } from './analytics-screen';

let disabled = false;
const seen = new Map<string, number>();
const EVENT_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function platform(): 'ios' | 'android' | 'web' | null {
  if (Platform.OS === 'ios' || Platform.OS === 'android' || Platform.OS === 'web') return Platform.OS;
  return null;
}

function recent(key: string, ms: number): boolean {
  if (ms <= 0) return false;
  const now = Date.now();
  const prev = seen.get(key);
  if (prev != null && now - prev < ms) return true;
  seen.set(key, now);
  return false;
}

function missingFunction(error: { message?: string; code?: string }, fn: string): boolean {
  const msg = `${error.message ?? ''} ${error.code ?? ''}`;
  return error.code === 'PGRST202' || (new RegExp(fn, 'i').test(msg) && /schema cache|does not exist|could not find/i.test(msg));
}

function send(name: AppEventName, props: Record<string, string>): void {
  if (disabled || isDemo()) return;
  void supabase.rpc('track_app_event', {
    p_name: name,
    p_screen: name === 'screen_view' ? props.screen ?? null : null,
    p_props: props,
    p_platform: platform(),
  }).then(({ error }) => {
    if (error && missingFunction(error, 'track_app_event')) disabled = true;
  }, () => {});
}

/** Record one named event. Identical calls inside dedupe.ms collapse (strict-mode double effects). */
export function trackAppEvent(name: AppEventName, props: Record<string, string> = {}, dedupe?: { key?: string; ms?: number }): void {
  const key = dedupe?.key ?? `${name}:${JSON.stringify(props)}`;
  const ms = dedupe?.ms ?? (name === 'send_message' ? 0 : 800);
  if (recent(key, ms)) return;
  send(name, props);
}

export function trackScreen(pathname: string): void {
  if (recent(`screen:${pathname}`, 800)) return;
  send('screen_view', { screen: screenNameFromPath(pathname) });
}

async function devicePoint(): Promise<{ lat: number; lng: number } | null> {
  try {
    return await Promise.race([
      peekDeviceLocation(),
      new Promise<null>((resolve) => setTimeout(() => resolve(null), 1000)),
    ]);
  } catch {
    return null;
  }
}

async function sendEventPageView(eventId: string, surface: 'app' | 'public'): Promise<void> {
  const point = await devicePoint();
  await supabase.functions.invoke('track-event-view', {
    body: {
      event_id: eventId,
      surface,
      platform: platform(),
      device_latitude: point?.lat ?? null,
      device_longitude: point?.lng ?? null,
    },
  }).then(() => {}, () => {});
}

/**
 * One view of a member event page or the public event page.
 * The edge function stores IP, user agent, and place. Demo mode stays local.
 * Does not ask for device location; a fix the app already has is attached.
 */
export function trackEventPageView(eventId: string, surface: 'app' | 'public'): void {
  if (isDemo() || !EVENT_ID.test(eventId)) return;
  if (recent(`event-view:${surface}:${eventId}`, 120_000)) return;
  void sendEventPageView(eventId, surface);
}

/** One screen_view per path change for a signed-in member. Demo mode stays local. */
export function useTrackScreen(pathname: string | null | undefined, enabled: boolean): void {
  const last = useRef<string | null>(null);
  useEffect(() => {
    if (!enabled) {
      last.current = null;
      return;
    }
    if (!pathname || pathname === last.current) return;
    last.current = pathname;
    trackScreen(pathname);
  }, [pathname, enabled]);
}

export async function getAppAnalytics(days: number): Promise<AppAnalyticsSummary> {
  const { data, error } = await supabase.rpc('app_analytics_summary', { p_days: days });
  if (error) {
    const msg = error.message ?? '';
    if (missingFunction(error, 'app_analytics_summary')) {
      throw new Error('App events aren’t in the database yet. Apply supabase/migrations/20261026000010_app_analytics.sql in the SQL editor.');
    }
    if (/not a moderator|42501/i.test(msg)) throw new Error('Only moderators can view app events.');
    throw new Error(msg || 'Couldn’t load app events.');
  }
  const body = typeof data === 'string' ? JSON.parse(data) as AppAnalyticsSummary : data as AppAnalyticsSummary;
  if (!body || !Array.isArray(body.totals) || !Array.isArray(body.series) || !Array.isArray(body.screens)) {
    throw new Error('App events returned an unexpected result.');
  }
  return body;
}

/** Moderator-only funnel and view log for one event. */
export async function getEventAnalytics(eventId: string): Promise<EventAnalytics> {
  const { data, error } = await supabase.rpc('app_analytics_event', { p_event_id: eventId });
  if (error) {
    const msg = error.message ?? '';
    if (missingFunction(error, 'app_analytics_event')) {
      throw new Error('Event analytics aren’t in the database yet. Apply supabase/migrations/20261027000005_event_page_analytics.sql in the SQL editor.');
    }
    if (/not a moderator|42501/i.test(msg)) throw new Error('Only moderators can view event analytics.');
    throw new Error(msg || 'Couldn’t load event analytics.');
  }
  return parseEventAnalytics(data, eventId);
}

/** Moderator-only funnel for one group: its events' page views and app RSVPs. No Meetup headcount. */
export async function getGroupAnalytics(groupId: string): Promise<GroupAnalytics> {
  const { data, error } = await supabase.rpc('app_analytics_group', { p_group_id: groupId });
  if (error) {
    const msg = error.message ?? '';
    if (missingFunction(error, 'app_analytics_group')) {
      throw new Error('Group analytics aren’t in the database yet. Apply supabase/migrations/20261028000001_club_groups.sql in the SQL editor.');
    }
    if (/not a moderator|42501/i.test(msg)) throw new Error('Only moderators can view group analytics.');
    if (/group not found|P0002/i.test(msg)) throw new Error('Group not found.');
    throw new Error(msg || 'Couldn’t load group analytics.');
  }
  return parseGroupAnalytics(data, groupId);
}
