// How a member relates to a club event on the Events tab.
// Hosting wins over Attending. Empty groups are the caller's to hide.

/** How far back the Past toggle looks. The list query uses the same window. */
export const EVENTS_PAST_DAYS = 30;

/** No ends_at: the club list treats the event as over this long after it starts. */
const OPEN_ENDED_MS = 2 * 3_600_000;

export type EventTimeRange = 'upcoming' | 'past';
export type EventListSort = 'soonest' | 'latest';
export type EventRelation = 'hosting' | 'attending' | 'visible';

export type EventRelationContext = {
  userId: string | null;
  attendingIds: ReadonlySet<string>;
  hostedMeetupIds: ReadonlySet<string>;
};

/** End instant used by the club list. ends_at when set, otherwise starts_at plus 2 hours. */
export function clubListEndMs(e: { starts_at: string; ends_at: string | null }): number {
  return e.ends_at ? Date.parse(e.ends_at) : Date.parse(e.starts_at) + OPEN_ENDED_MS;
}

/**
 * Hosting: this member owns the club event, created it, or is a Meetup host for its listing.
 * Ownership and creation can differ after a transfer. Both count, for this list only.
 * Attending: they have an app RSVP and they are not already hosting.
 * Other Events: everything else on the list. The relation key stays `visible`.
 */
export function classifyEventRelation(
  event: { id: string; created_by?: string | null; owner_id?: string | null; meetup_id?: string | null },
  ctx: EventRelationContext,
): EventRelation {
  const meetupId = event.meetup_id ?? null;
  const hosting = ctx.userId != null && (
    event.owner_id === ctx.userId
    || event.created_by === ctx.userId
    || (meetupId != null && meetupId !== '' && ctx.hostedMeetupIds.has(meetupId))
  );
  if (hosting) return 'hosting';
  if (ctx.attendingIds.has(event.id)) return 'attending';
  return 'visible';
}

/** Preserves the incoming order, which the caller has already sorted. */
export function groupEventsByRelation<T extends { id: string; created_by?: string | null; owner_id?: string | null; meetup_id?: string | null }>(
  events: readonly T[],
  ctx: EventRelationContext,
): Record<EventRelation, T[]> {
  const hosting: T[] = [];
  const attending: T[] = [];
  const visible: T[] = [];
  for (const event of events) {
    const relation = classifyEventRelation(event, ctx);
    if (relation === 'hosting') hosting.push(event);
    else if (relation === 'attending') attending.push(event);
    else visible.push(event);
  }
  return { hosting, attending, visible };
}

type RangeEvent = {
  title: string;
  description: string;
  venue_name?: string | null;
  starts_at: string;
  ends_at: string | null;
  archived: boolean;
};

/** Live events in the selected time range. Archived rows stay out. Search and sort apply here. */
export function eventsInRange<T extends RangeEvent>(
  events: readonly T[],
  opts: { range: EventTimeRange; sort: EventListSort; query: string; now: number },
): T[] {
  const needle = opts.query.trim().toLowerCase();
  const cutoff = opts.now - EVENTS_PAST_DAYS * 86_400_000;
  const matched = events.filter((e) => {
    if (e.archived) return false;
    if (!needle) return true;
    return `${e.title} ${e.description} ${e.venue_name ?? ''}`.toLowerCase().includes(needle);
  });
  const inRange = matched.filter((e) => {
    const end = clubListEndMs(e);
    if (opts.range === 'upcoming') return end > opts.now;
    return end <= opts.now && Date.parse(e.starts_at) >= cutoff;
  });
  const dir = opts.sort === 'soonest' ? 1 : -1;
  return inRange.slice().sort((a, b) => dir * (Date.parse(a.starts_at) - Date.parse(b.starts_at)));
}
