// Cross-platform action sheet / text prompt (Alert.prompt is iOS-only, Alert is limited on web).
import React, { useState } from 'react';
import { Modal, Pressable, Text, View } from 'react-native';
import { Button, Field, styles } from './ui';
import { colors } from '../lib/theme';

export type Action = { label: string; onPress: () => void; danger?: boolean };

export function ActionSheet({ visible, title, actions, onClose }: { visible: boolean; title: string; actions: Action[]; onClose: () => void }) {
  return (
    <Modal transparent visible={visible} animationType="fade" onRequestClose={onClose}>
      <Pressable style={{ flex: 1, backgroundColor: 'rgba(18,41,75,.35)', justifyContent: 'flex-end' }} onPress={onClose}>
        <Pressable style={{ backgroundColor: colors.paper, padding: 20, borderTopLeftRadius: 18, borderTopRightRadius: 18, gap: 10, maxWidth: 640, width: '100%', alignSelf: 'center' }}>
          <Text style={styles.h2}>{title}</Text>
          {actions.map((a) => <Button key={a.label} title={a.label} variant={a.danger ? 'danger' : 'ghost'} onPress={() => { onClose(); a.onPress(); }} />)}
          <Button title="Cancel" variant="ghost" onPress={onClose} />
        </Pressable>
      </Pressable>
    </Modal>
  );
}

export function ReportDialog({ visible, subject, onSubmit, onClose }: { visible: boolean; subject: string; onSubmit: (reason: string) => Promise<void>; onClose: () => void }) {
  const [reason, setReason] = useState('');
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState(false);
  const close = () => { setReason(''); setDone(false); onClose(); };
  return (
    <Modal transparent visible={visible} animationType="fade" onRequestClose={close}>
      <View style={{ flex: 1, backgroundColor: 'rgba(18,41,75,.35)', justifyContent: 'center', padding: 20 }}>
        <View style={{ backgroundColor: colors.paper, borderRadius: 16, padding: 20, maxWidth: 520, width: '100%', alignSelf: 'center' }}>
          <Text style={styles.h2}>Report {subject}</Text>
          {done ? <>
            <Text style={[styles.body, { marginVertical: 12 }]}>Thanks. We’ll review it within 24 hours.</Text>
            <Button title="Close" onPress={close} />
          </> : <>
            <Text style={[styles.muted, { marginVertical: 8 }]}>Private to the organizers.</Text>
            <Field value={reason} onChangeText={setReason} multiline placeholder="What happened?" maxLength={1000} />
            <View style={{ flexDirection: 'row', gap: 10, justifyContent: 'flex-end' }}>
              <Button title="Cancel" variant="ghost" onPress={close} small />
              <Button title="Send" small disabled={!reason.trim()} loading={busy}
                onPress={async () => { setBusy(true); try { await onSubmit(reason.trim()); setDone(true); } finally { setBusy(false); } }} />
            </View>
          </>}
        </View>
      </View>
    </Modal>
  );
}
