// One private thread. The /rooms/[id] route and the wide Chat pane both use this.
// kind=dm is a 1:1. kind=group is an event chat. Older shared rooms stay paused.
import React, { useCallback, useEffect, useRef, useState } from 'react';
import { ActivityIndicator, FlatList, Text, View } from 'react-native';
import { router, Stack, useFocusEffect } from 'expo-router';
import type { RealtimeChannel } from '@supabase/supabase-js';
import { Button, EmptyState, Page } from './ui';
import { ChatComposer } from './chat-composer';
import { ChatThreadHeader } from './chat-thread-header';
import { KeyboardSafeScreen, useStickToBottom } from './keyboard-safe-screen';
import { TranscriptMessage } from './transcript';
import { ActionSheet, ReportDialog } from './Prompt';
import { colors, fonts, fs } from '../lib/theme';
import { blockUser, getProfiles, getRoom, listBlocked, listMessages, listRoomMemberIds, report, sendMessage, softDeleteMessage } from '../lib/api';
import { threadRoomId } from '../lib/chat-errors';
import { trackAppEvent } from '../lib/analytics';
import { useSession } from '../lib/session';
import { usePresence } from '../lib/presence';
import { supabase } from '../lib/supabase';
import { setActivePushRoom } from '../lib/push';
import { fmtTime } from '../lib/format';
import { handle, primaryName } from '../lib/names';
import type { Message, Profile, Room } from '../lib/types';

const BURST_MS = 5 * 60_000;

export function DirectThread({ roomId: roomIdInput, embedded = false }: { roomId: string | string[]; embedded?: boolean }) {
  const roomId = threadRoomId(roomIdInput);
  const { userId, isModerator, demo } = useSession();
  const { online, setRoom } = usePresence();
  const [room, setRoomData] = useState<Room | null | undefined>(undefined);
  const [peerId, setPeerId] = useState<string | null>(null);
  const [memberIds, setMemberIds] = useState<string[]>([]);
  const [msgs, setMsgs] = useState<Message[]>([]);
  const [profiles, setProfiles] = useState<Record<string, Profile>>({});
  const [blocked, setBlocked] = useState<string[]>([]);
  const [text, setText] = useState('');
  const [sending, setSending] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [sheet, setSheet] = useState<Message | null>(null);
  const [reporting, setReporting] = useState<{ messageId?: number; userId?: string; label: string } | null>(null);
  const chan = useRef<RealtimeChannel | null>(null);
  const list = useRef<FlatList<Message>>(null);
  const stick = useStickToBottom(list);

  const ensureProfiles = useCallback(async (ids: string[]) => {
    const p = await getProfiles([...new Set(ids.filter(Boolean))]);
    setProfiles((cur) => ({ ...cur, ...p }));
  }, []);

  const goBack = () => { if (router.canGoBack()) router.back(); else router.replace('/chat'); };

  useFocusEffect(useCallback(() => {
    const privateRoom = room?.kind === 'dm' || room?.kind === 'group';
    if (!roomId || room === null || (room && !privateRoom)) {
      setRoom(null);
      setActivePushRoom(null);
      return;
    }
    // Mark the thread while it is focused, including the moment it is still loading,
    // so a message for this chat does not also raise an alert.
    setActivePushRoom(roomId);
    if (privateRoom) setRoom(roomId);
    return () => {
      setRoom(null);
      setActivePushRoom(null);
    };
  }, [roomId, room, setRoom]));

  useEffect(() => {
    if (!userId) return;
    if (!roomId) { setRoomData(null); return; }
    let live = true;
    setRoomData(undefined);
    setPeerId(null);
    setMsgs([]);
    setErr(null);
    (async () => {
      try {
        const r = await getRoom(roomId);
        if (!live) return;
        setRoomData(r);
        if (r && !demo) trackAppEvent('open_chat', { kind: r.kind === 'dm' ? 'dm' : r.kind === 'group' ? 'group' : 'room' }, { key: `open_chat:${roomId}` });
        if (!r || (r.kind !== 'dm' && r.kind !== 'group')) return;
        const [b, m, ids] = await Promise.all([
          listBlocked(),
          listMessages(roomId),
          listRoomMemberIds(roomId),
        ]);
        if (!live) return;
        setBlocked(b);
        setMsgs(m);
        const peer = r.kind === 'dm' ? (ids.find((x) => x !== userId) ?? null) : null;
        setPeerId(peer);
        setMemberIds(ids);
        ensureProfiles([...m.map((x) => x.user_id), ...ids]);
        if (demo) return;
        try {
          const { data } = await supabase.auth.getSession();
          if (data.session?.access_token) await supabase.realtime.setAuth(data.session.access_token);
        } catch { /* subscribe still uses whatever auth the client has */ }
        if (!live) return;
        const ch = supabase.channel(`room:${roomId}`)
          .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages', filter: `room_id=eq.${roomId}` }, ({ new: row }) => {
            const msg = row as Message;
            setMsgs((cur) => (cur.some((x) => x.id === msg.id) ? cur : [...cur, msg]));
            ensureProfiles([msg.user_id]);
          })
          .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'messages', filter: `room_id=eq.${roomId}` }, ({ new: row }) => {
            const msg = row as Message;
            setMsgs((cur) => cur.map((x) => (x.id === msg.id ? msg : x)));
          })
          // Non-moderators can't see the soft-deleted row via RLS, so moderators also broadcast the removal.
          .on('broadcast', { event: 'message_deleted' }, ({ payload }) => setMsgs((cur) => cur.filter((x) => x.id !== payload.id)))
          .subscribe();
        if (!live) { supabase.removeChannel(ch); return; }
        chan.current = ch;
      } catch (e: any) {
        if (live) setErr(e.message);
      }
    })();
    return () => {
      live = false;
      if (chan.current) { supabase.removeChannel(chan.current); chan.current = null; }
    };
  }, [roomId, userId, demo, ensureProfiles]);

  useEffect(() => { setTimeout(() => list.current?.scrollToEnd({ animated: false }), 50); }, [msgs.length]);

  const send = async () => {
    const body = text.trim();
    if (!body || !roomId || sending) return;
    setSending(true); setErr(null);
    try {
      const m = await sendMessage(roomId, body);
      setText('');
      setMsgs((cur) => (cur.some((x) => x.id === m.id) ? cur : [...cur, m]));
    } catch (e: any) { setErr(e.message); } finally { setSending(false); }
  };

  const screen = embedded ? null : <Stack.Screen options={{ headerShown: false, title: 'Chat' }} />;
  const visible = msgs.filter((m) => !blocked.includes(m.user_id) && (isModerator || !m.deleted_at));
  const peer = peerId ? profiles[peerId] : undefined;
  const peerName = peer ? primaryName(peer) : (online.find((u) => u.user_id === peerId)?.name ?? 'Direct message');
  const peerOnline = !!peerId && online.some((u) => u.user_id === peerId) && !blocked.includes(peerId);

  if (room === undefined) {
    return (
      <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', backgroundColor: colors.paper }}>
        {embedded ? null : <Stack.Screen options={{ headerShown: false, title: 'Chat' }} />}
        <ActivityIndicator color={colors.navy} />
      </View>
    );
  }
  if (!room) {
    return (
      <Page>
        {screen}
        <EmptyState icon="lock-closed-outline" title="This conversation isn’t available" body="It may be private, or the link is no longer valid."
          action={embedded ? undefined : <Button variant="neutral" small title="Back to chat" onPress={goBack} />} />
      </Page>
    );
  }
  // reading / event / open_hours stay club-wide in the database and paused in the app.
  if (room.kind !== 'dm' && room.kind !== 'group') {
    return (
      <Page>
        {screen}
        <EmptyState icon="chatbubbles-outline" title="Group chats are paused" body="Direct messages are on the Chat tab. Event chats a host adds you to show up under Groups."
          action={embedded ? undefined : <Button variant="neutral" small title="Back to chat" onPress={goBack} />} />
      </Page>
    );
  }
  const isGroup = room.kind === 'group';
  const peopleLabel = memberIds.length === 1 ? '1 person' : `${memberIds.length} people`;
  const iBlocked = !isGroup && !!peerId && blocked.includes(peerId);

  return (
    <KeyboardSafeScreen>
      {embedded ? null : <Stack.Screen options={{ headerShown: false, title: isGroup ? room.title : peerName }} />}
      <ChatThreadHeader
        name={isGroup ? room.title : peerName}
        detail={isGroup ? null : (peer?.username ? handle(peer) : null)}
        statusText={isGroup ? peopleLabel : null}
        online={isGroup ? false : peerOnline}
        avatarPath={isGroup ? null : peer?.avatar_path}
        avatarUserId={isGroup ? null : peerId}
        onBack={embedded ? undefined : goBack}
        onPressAvatar={!isGroup && peerId ? () => router.push(`/profile?id=${peerId}`) : undefined}
        avatarLabel={!isGroup && peerId ? `${peerName}'s profile` : undefined}
        onProfile={!isGroup && peerId ? () => router.push(`/profile?id=${peerId}`) : undefined}
      />
      <FlatList
        ref={list}
        style={{ flex: 1, minHeight: 0 }}
        data={visible}
        onScroll={stick.onScroll}
        onLayout={stick.onLayout}
        scrollEventThrottle={stick.scrollEventThrottle}
        keyExtractor={(m) => String(m.id)}
        keyboardShouldPersistTaps="handled"
        contentContainerStyle={{ paddingHorizontal: 16, paddingTop: 8, paddingBottom: 16, width: '100%', maxWidth: 840, alignSelf: 'center', flexGrow: 1 }}
        ListEmptyComponent={
          <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', padding: 24 }}>
            <Text style={{ fontFamily: fonts.sans, fontSize: fs(15), color: colors.muted, textAlign: 'center' }}>No messages yet. Say hello.</Text>
          </View>
        }
        renderItem={({ item: m, index }) => {
          const mine = m.user_id === userId;
          const p = profiles[m.user_id];
          const name = primaryName(p);
          const prev = visible[index - 1];
          const next = visible[index + 1];
          const grouped = !!(prev && prev.user_id === m.user_id && Date.parse(m.created_at) - Date.parse(prev.created_at) < BURST_MS);
          const showTime = !(next && next.user_id === m.user_id && Date.parse(next.created_at) - Date.parse(m.created_at) < BURST_MS);
          return (
            <TranscriptMessage
              label={mine ? 'You' : name}
              handleText={!mine && p?.display_name?.trim() ? handle(p) : null}
              time={fmtTime(m.created_at)}
              body={m.deleted_at ? `[removed] ${m.body}` : m.body}
              grouped={grouped}
              showTime={showTime}
              dim={!!m.deleted_at}
              mine={mine}
              avatarName={name}
              avatarPath={p?.avatar_path}
              avatarUserId={m.user_id}
              onPressAvatar={() => router.push(`/profile?id=${m.user_id}`)}
              avatarLabel={`${name}'s profile`}
              onLongPress={() => setSheet(m)}
              onMenu={!mine || isModerator ? () => setSheet(m) : undefined}
            />
          );
        }}
      />
      <ChatComposer
        value={text}
        onChangeText={setText}
        onSend={send}
        sending={sending}
        placeholder="Message"
        error={err}
        includeSafeArea={!embedded}
        blocked={iBlocked ? 'You blocked this member. Unblock them on their profile to send a message.' : null}
      />
      <ActionSheet visible={!!sheet} title="Message options" onClose={() => setSheet(null)} actions={sheet ? [
        ...(sheet.user_id !== userId ? [
          { label: 'Report', onPress: () => setReporting({ messageId: sheet.id, userId: sheet.user_id, label: 'message' }) },
          { label: `Block ${handle(profiles[sheet.user_id])}`, danger: true, onPress: async () => {
            await blockUser(userId!, sheet.user_id); setBlocked((b) => [...b, sheet.user_id]); } },
        ] : []),
        ...(isModerator && !sheet.deleted_at ? [{ label: 'Remove (moderator)', danger: true, onPress: async () => {
          await softDeleteMessage(sheet.id);
          chan.current?.send({ type: 'broadcast', event: 'message_deleted', payload: { id: sheet.id } });
          setMsgs((cur) => cur.map((x) => (x.id === sheet.id ? { ...x, deleted_at: new Date().toISOString() } : x)));
        } }] : []),
      ] : []} />
      <ReportDialog visible={!!reporting} subject={reporting?.label ?? ''} onClose={() => setReporting(null)}
        onSubmit={(reason) => report({ messageId: reporting?.messageId, userId: reporting?.userId, reason })} />
    </KeyboardSafeScreen>
  );
}
