// Slim bar above a 1:1 thread: who it is, whether they are online, and how to leave.
import React from 'react';
import { Pressable, Text, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { Avatar } from './ui';
import { colors, fonts, fs } from '../lib/theme';

export function ChatThreadHeader({
  name, detail, online, statusText, avatarPath, avatarUserId, onBack, onPressAvatar, avatarLabel, onProfile,
}: {
  name: string;
  detail?: string | null;
  online: boolean;
  /** Replaces Online / Offline. Used for a group chat's member count. */
  statusText?: string | null;
  avatarPath?: string | null;
  avatarUserId?: string | null;
  onBack?: () => void;
  onPressAvatar?: () => void;
  avatarLabel?: string;
  onProfile?: () => void;
}) {
  const avatar = <Avatar name={name} path={avatarPath} userId={avatarUserId} size={40} online={online} />;
  return (
    <View style={{
      flexDirection: 'row',
      alignItems: 'center',
      gap: 10,
      paddingHorizontal: 12,
      paddingVertical: 10,
      backgroundColor: '#fff',
      borderBottomWidth: 1,
      borderBottomColor: colors.line,
    }}>
      {onBack ? (
        <Pressable onPress={onBack} accessibilityRole="button" accessibilityLabel="Back to chat" hitSlop={8} style={{ padding: 4 }}>
          <Ionicons name="chevron-back" size={22} color={colors.navy} />
        </Pressable>
      ) : null}
      {onPressAvatar ? (
        <Pressable onPress={onPressAvatar} accessibilityRole="button" accessibilityLabel={avatarLabel}>{avatar}</Pressable>
      ) : avatar}
      <View style={{ flex: 1, minWidth: 0 }}>
        <Text style={{ fontFamily: fonts.sansBold, fontSize: fs(16), color: colors.navyDark }} numberOfLines={1}>{name}</Text>
        <Text numberOfLines={1} style={{ marginTop: 1 }}>
          <Text style={{ fontFamily: fonts.sansMedium, fontSize: fs(12), color: statusText ? colors.muted : online ? colors.online : colors.faint }}>{statusText || (online ? 'Online' : 'Offline')}</Text>
          {detail ? <Text style={{ fontFamily: fonts.sans, fontSize: fs(12), color: colors.muted }}>{` · ${detail}`}</Text> : null}
        </Text>
      </View>
      {onProfile ? (
        <Pressable onPress={onProfile} accessibilityRole="button" accessibilityLabel="Profile" hitSlop={8} style={{ padding: 6 }}>
          <Ionicons name="person-outline" size={20} color={colors.navy} />
        </Pressable>
      ) : null}
    </View>
  );
}
