// Shareable URL on the public site. On web, follow the prefix the page is
// actually served from ("" at https://gnosis.events, or /app for the legacy host).
import { Platform } from 'react-native';
import { WEB_ORIGIN } from './config';

export function publicAppUrl(route: string): string {
  const path = route.startsWith('/') ? route : `/${route}`;
  if (Platform.OS === 'web' && typeof window !== 'undefined') {
    const base = (process.env.EXPO_BASE_URL ?? '').replace(/\/$/, '');
    const loc = window.location.pathname;
    const prefix = loc === base || loc.startsWith(`${base}/`) ? base : '';
    return `${window.location.origin}${prefix}${path}`;
  }
  return `${WEB_ORIGIN}${path}`;
}
