// Meetup descriptions arrive as HTML or as the markdown the organizer typed.
// Bare http(s) URLs become links. The renderer never injects raw HTML.

export type Inline =
  | { t: 'text'; v: string }
  | { t: 'strong'; c: Inline[] }
  | { t: 'em'; c: Inline[] }
  | { t: 'link'; href: string; c: Inline[] }
  | { t: 'code'; v: string };

export type Block =
  | { t: 'p'; c: Inline[] }
  | { t: 'h'; level: 1 | 2 | 3; c: Inline[] }
  | { t: 'ul'; items: Inline[][] }
  | { t: 'ol'; items: Inline[][] };

const NAMED: Record<string, string> = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
  rsquo: '\u2019', lsquo: '\u2018', sbquo: '\u201a', rdquo: '\u201d', ldquo: '\u201c', bdquo: '\u201e',
  ndash: '\u2013', mdash: '\u2014', hellip: '\u2026', bull: '\u2022', trade: '\u2122', copy: '\u00a9', reg: '\u00ae',
};

// Windows-1252 bytes 0x80–0x9F. UTF-8 read as that code page becomes these characters.
const CP1252_BYTE: Record<number, number> = {
  0x20ac: 0x80, 0x201a: 0x82, 0x0192: 0x83, 0x201e: 0x84, 0x2026: 0x85,
  0x2020: 0x86, 0x2021: 0x87, 0x02c6: 0x88, 0x2030: 0x89, 0x0160: 0x8a,
  0x2039: 0x8b, 0x0152: 0x8c, 0x017d: 0x8e, 0x2018: 0x91, 0x2019: 0x92,
  0x201c: 0x93, 0x201d: 0x94, 0x2022: 0x95, 0x2013: 0x96, 0x2014: 0x97,
  0x02dc: 0x98, 0x2122: 0x99, 0x0161: 0x9a, 0x203a: 0x9b, 0x0153: 0x9c,
  0x017e: 0x9e, 0x0178: 0x9f,
};

function cp1252Byte(cp: number): number | null {
  if (cp <= 0x7f || (cp >= 0xa0 && cp <= 0xff)) return cp;
  return CP1252_BYTE[cp] ?? null;
}

/** One Windows-1252 reinterpretation of UTF-8, or null when the bytes are not UTF-8. */
function decodeCp1252AsUtf8(s: string): string | null {
  const bytes: number[] = [];
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (cp == null) return null;
    const b = cp1252Byte(cp);
    if (b == null) return null;
    bytes.push(b);
  }
  try {
    return new TextDecoder('utf-8', { fatal: true }).decode(Uint8Array.from(bytes));
  } catch {
    return null;
  }
}

/**
 * UTF-8 that was decoded as Windows-1252 (`Weâ€™re` → `We’re`).
 * A string that is already Unicode, or that is not valid UTF-8 when re-read, stays as it is.
 */
export function repairUtf8Mojibake(input: string): string {
  let current = input;
  for (let pass = 0; pass < 2; pass++) {
    const next = decodeCp1252AsUtf8(current);
    if (next == null || next === current) return current;
    current = next;
  }
  return current;
}

function decodeEntities(s: string): string {
  return s.replace(/&(#x?[0-9a-fA-F]+|[a-zA-Z]+);/g, (all, body: string) => {
    if (body[0] === '#') {
      const hex = body[1] === 'x' || body[1] === 'X';
      const cp = Number.parseInt(body.slice(hex ? 2 : 1), hex ? 16 : 10);
      if (!Number.isFinite(cp) || cp < 0 || cp > 0x10ffff) return all;
      if (cp < 32 && cp !== 9 && cp !== 10 && cp !== 13) return '';
      try { return String.fromCodePoint(cp); } catch { return all; }
    }
    return NAMED[body.toLowerCase()] ?? all;
  });
}

/** http(s) and mailto only. javascript:, data:, and broken URLs become plain text. */
export function safeHref(raw: string | null | undefined): string | null {
  if (!raw) return null;
  const href = decodeEntities(raw).trim().replace(/[\u0000-\u001f\s]+/g, '');
  if (!href) return null;
  if (/^mailto:/i.test(href)) {
    const rest = href.slice('mailto:'.length);
    if (!rest || /[<>"]/.test(rest)) return null;
    return href;
  }
  if (!/^https?:\/\//i.test(href)) return null;
  try {
    const u = new URL(href);
    if (u.protocol !== 'http:' && u.protocol !== 'https:') return null;
    return u.toString();
  } catch {
    return null;
  }
}

function isUrlBoundary(ch: string | undefined): boolean {
  if (ch == null) return true;
  // A letter, digit, or underscore glued on the left is part of a token, not a URL start.
  return !/[A-Za-z0-9%_]/.test(ch);
}

function countChar(s: string, ch: string): number {
  let n = 0;
  for (let i = 0; i < s.length; i++) if (s[i] === ch) n++;
  return n;
}

/** Sentence punctuation and an unmatched closing bracket are not part of the URL. */
function trimUrlTail(token: string): { url: string; rest: string } {
  let url = token;
  let rest = '';
  while (url) {
    const last = url[url.length - 1];
    const punct = last === '.' || last === ',' || last === ';' || last === ':' || last === '!' || last === '?';
    const extraParen = last === ')' && countChar(url, '(') < countChar(url, ')');
    const extraBracket = last === ']' && countChar(url, '[') < countChar(url, ']');
    if (!punct && !extraParen && !extraBracket) break;
    rest = last + rest;
    url = url.slice(0, -1);
  }
  return { url, rest };
}

/** http(s) or a bare www host. javascript: and data: never match. Display text keeps the original spelling. */
function matchUrl(s: string, i: number): { raw: string; href: string } | null {
  if (!isUrlBoundary(i > 0 ? s[i - 1] : undefined)) return null;
  const slice = s.slice(i);
  const http = /^https?:\/\/[^\s<>"'`*]+/i.exec(slice);
  if (http) {
    const { url } = trimUrlTail(http[0]);
    if (/^https?:\/\/\S/i.test(url)) {
      const href = safeHref(url);
      if (href) return { raw: url, href };
    }
  }
  const www = /^www\.[^\s<>"'`*]+/i.exec(slice);
  if (!www) return null;
  const { url } = trimUrlTail(www[0]);
  if (!/^www\.[a-z0-9-]+(?:\.[a-z0-9-]+)+/i.test(url)) return null;
  const href = safeHref(`https://${url}`);
  if (!href) return null;
  return { raw: url, href };
}

function linkifyString(text: string): Inline[] {
  const out: Inline[] = [];
  let i = 0;
  while (i < text.length) {
    const url = matchUrl(text, i);
    if (url) {
      out.push({ t: 'link', href: url.href, c: [{ t: 'text', v: url.raw }] });
      i += url.raw.length;
      continue;
    }
    const rel = text.slice(i + 1).search(/https?:\/\/|www\./i);
    const end = rel < 0 ? text.length : i + 1 + rel;
    if (end > i) out.push({ t: 'text', v: text.slice(i, end) });
    i = end;
  }
  return out;
}

function attr(raw: string, name: string): string | null {
  const m = new RegExp(`\\b${name}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s"'=<>]+))`, 'i').exec(raw);
  if (!m) return null;
  return decodeEntities(m[1] ?? m[2] ?? m[3] ?? '');
}

function looksLikeHtml(s: string): boolean {
  return /<\s*\/?\s*(p|br|div|a|strong|b|em|i|h[1-6]|ul|ol|li|blockquote)\b/i.test(s);
}

function stripDangerous(src: string): string {
  return src
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<\s*(script|style|iframe|object|embed|noscript|svg|math|template)\b[^>]*>[\s\S]*?<\s*\/\s*\1\s*>/gi, '')
    .replace(/<\s*(script|style|iframe|object|embed|noscript|svg|math|template)\b[^>]*>[\s\S]*$/gi, '')
    .replace(/<\s*(script|style|iframe|object|embed|noscript|svg|math|template)\b[^>]*\/?\s*>/gi, '');
}

function mergeText(nodes: Inline[]): Inline[] {
  const out: Inline[] = [];
  for (const n of nodes) {
    if (n.t === 'text') {
      const v = n.v.replace(/[ \t\f\v]+/g, ' ');
      if (!v) continue;
      const last = out[out.length - 1];
      if (last && last.t === 'text') last.v += v;
      else out.push({ t: 'text', v });
    } else if ((n.t === 'strong' || n.t === 'em' || n.t === 'link') && n.c.length === 0) {
      continue;
    } else out.push(n);
  }
  return out;
}

function trimEdges(nodes: Inline[]): Inline[] {
  const out = mergeText(nodes);
  const trim = (i: number, edge: 'start' | 'end') => {
    const n = out[i];
    if (!n || n.t !== 'text') return;
    const v = edge === 'start' ? n.v.replace(/^[ \n\t]+/, '') : n.v.replace(/[ \n\t]+$/, '');
    out[i] = { t: 'text', v };
  };
  if (out.length) { trim(0, 'start'); trim(out.length - 1, 'end'); }
  return out.filter((n) => n.t !== 'text' || n.v.length > 0);
}

function hasInlines(nodes: Inline[]): boolean {
  return nodes.some((n) => n.t !== 'text' || n.v.trim().length > 0);
}

function parseHtml(src: string): Block[] {
  const stripped = stripDangerous(src);
  const re = /<\s*(\/)?\s*([a-zA-Z][a-zA-Z0-9]*)\b([^>]*)>|([^<]+)/g;
  const blocks: Block[] = [];
  let inlines: Inline[] = [];
  const marks: { t: 'strong' | 'em' | 'link'; href?: string }[] = [];
  let mode: 'p' | 'h' | null = null;
  let level: 1 | 2 | 3 = 2;
  let list: { ordered: boolean; items: Inline[][] } | null = null;
  let inLi = false;

  const wrap = (node: Inline): Inline => marks.reduceRight((child, m) => {
    if (m.t === 'link' && m.href) return { t: 'link' as const, href: m.href, c: [child] };
    if (m.t === 'strong') return { t: 'strong' as const, c: [child] };
    if (m.t === 'em') return { t: 'em' as const, c: [child] };
    return child;
  }, node);

  const pushInline = (node: Inline) => { inlines.push(wrap(node)); };

  const flushBlock = () => {
    const c = trimEdges(inlines);
    inlines = [];
    if (!hasInlines(c)) { if (!inLi) mode = null; return; }
    if (inLi && list) list.items.push(c);
    else if (mode === 'h') blocks.push({ t: 'h', level, c });
    else blocks.push({ t: 'p', c });
    if (!inLi) mode = null;
  };

  const flushList = () => {
    flushBlock();
    if (list && list.items.some(hasInlines)) {
      blocks.push(list.ordered ? { t: 'ol', items: list.items.filter(hasInlines) } : { t: 'ul', items: list.items.filter(hasInlines) });
    }
    list = null;
    inLi = false;
  };

  let m: RegExpExecArray | null;
  while ((m = re.exec(stripped))) {
    if (m[4] != null) {
      const text = decodeEntities(m[4]).replace(/\s*\n\s*/g, ' ');
      if (!text) continue;
      if (!mode && !inLi && text.trim()) mode = 'p';
      if (text.trim() || mode || inLi) {
        // Text already inside an <a> stays one link. A bare URL in a text node becomes one.
        const insideLink = marks.some((mk) => mk.t === 'link');
        const parts = insideLink ? [{ t: 'text' as const, v: text }] : linkifyString(text);
        for (const part of parts) pushInline(part);
      }
      continue;
    }
    const close = Boolean(m[1]);
    const tag = m[2].toLowerCase();
    const attrs = m[3] ?? '';
    if (close) {
      if (tag === 'strong' || tag === 'b' || tag === 'em' || tag === 'i' || tag === 'a') {
        const want = tag === 'em' || tag === 'i' ? 'em' : tag === 'a' ? 'link' : 'strong';
        for (let i = marks.length - 1; i >= 0; i--) if (marks[i].t === want) { marks.splice(i, 1); break; }
      } else if (tag === 'li') {
        flushBlock();
        inLi = false;
      } else if (tag === 'ul' || tag === 'ol') flushList();
      else if (tag === 'p' || tag === 'div' || tag === 'blockquote' || /^h[1-6]$/.test(tag)) flushBlock();
      continue;
    }
    if (tag === 'br') { pushInline({ t: 'text', v: '\n' }); continue; }
    if (tag === 'ul' || tag === 'ol') {
      flushBlock();
      if (list) flushList();
      list = { ordered: tag === 'ol', items: [] };
      continue;
    }
    if (tag === 'li') {
      flushBlock();
      inLi = true;
      mode = 'p';
      continue;
    }
    if (/^h[1-6]$/.test(tag)) {
      flushBlock();
      mode = 'h';
      const n = Number(tag[1]);
      level = (n <= 1 ? 1 : n === 2 ? 2 : 3);
      continue;
    }
    if (tag === 'p' || tag === 'div' || tag === 'blockquote') {
      if (!(tag === 'p' && inLi && inlines.length === 0)) flushBlock();
      mode = 'p';
      continue;
    }
    if (tag === 'strong' || tag === 'b') { marks.push({ t: 'strong' }); continue; }
    if (tag === 'em' || tag === 'i') { marks.push({ t: 'em' }); continue; }
    if (tag === 'a') {
      const href = safeHref(attr(attrs, 'href'));
      if (href) marks.push({ t: 'link', href });
    }
  }
  flushList();
  flushBlock();
  return blocks;
}

function nextSpecial(s: string, from: number): number {
  const i = s.slice(from).search(/[*_`[\n]|!(?=\[)/);
  return i < 0 ? s.length : from + i;
}

function nextUrl(s: string, from: number, inLink: boolean): number {
  if (inLink) return -1;
  const re = /https?:\/\/|www\./gi;
  re.lastIndex = from;
  let m: RegExpExecArray | null;
  while ((m = re.exec(s))) {
    if (matchUrl(s, m.index)) return m.index;
    if (re.lastIndex <= m.index) re.lastIndex = m.index + 1;
  }
  return -1;
}

function nextBreak(s: string, from: number, inLink: boolean): number {
  const special = nextSpecial(s, from);
  const urlAt = nextUrl(s, from, inLink);
  if (urlAt < 0) return special;
  return Math.min(special, urlAt);
}

function parseInlines(s: string, inLink = false): Inline[] {
  const out: Inline[] = [];
  let i = 0;
  const pushText = (v: string) => {
    if (!v) return;
    const last = out[out.length - 1];
    if (last && last.t === 'text') last.v += v;
    else out.push({ t: 'text', v });
  };
  while (i < s.length) {
    if (!inLink) {
      const url = matchUrl(s, i);
      if (url) {
        out.push({ t: 'link', href: url.href, c: [{ t: 'text', v: url.raw }] });
        i += url.raw.length;
        continue;
      }
    }
    if (s.startsWith('**', i) || s.startsWith('__', i)) {
      const mark = s.slice(i, i + 2);
      const end = s.indexOf(mark, i + 2);
      if (end > i + 2) {
        const inner = parseInlines(s.slice(i + 2, end), inLink);
        if (inner.length) out.push({ t: 'strong', c: inner });
        i = end + 2;
        continue;
      }
    }
    if (s.startsWith('![', i)) {
      const img = /^!\[([^\]]*)\]\([^)\s]+\)/.exec(s.slice(i));
      if (img) { pushText(img[1]); i += img[0].length; continue; }
    }
    if (s[i] === '[') {
      const link = /^\[([^\]]+)\]\(([^)\s]+)\)/.exec(s.slice(i));
      if (link) {
        const href = safeHref(link[2]);
        if (href) out.push({ t: 'link', href, c: parseInlines(link[1], true) });
        else pushText(link[0]);
        i += link[0].length;
        continue;
      }
    }
    if (s[i] === '`') {
      const end = s.indexOf('`', i + 1);
      if (end > i + 1 && !s.slice(i + 1, end).includes('\n')) {
        out.push({ t: 'code', v: s.slice(i + 1, end) });
        i = end + 1;
        continue;
      }
    }
    if ((s[i] === '*' || s[i] === '_') && s[i + 1] !== s[i]) {
      const mark = s[i];
      const end = s.indexOf(mark, i + 1);
      const body = end > i ? s.slice(i + 1, end) : '';
      const tight = body.length > 0 && !body.includes('\n') && !body.startsWith(' ') && !body.endsWith(' ');
      if (tight) {
        out.push({ t: 'em', c: parseInlines(body, inLink) });
        i = end + 1;
        continue;
      }
    }
    if (s[i] === '\n') { pushText('\n'); i += 1; continue; }
    const next = nextBreak(s, i + 1, inLink);
    pushText(s.slice(i, next));
    i = next;
  }
  return trimEdges(out);
}

function parseMarkdown(src: string): Block[] {
  const text = src.replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
  if (!text) return [];
  const blocks: Block[] = [];
  for (const chunk of text.split(/\n\s*\n/)) {
    const lines = chunk.split('\n');
    const items = lines.map((l) => l.trim()).filter(Boolean);
    if (items.length && items.every((l) => /^[-*]\s+\S/.test(l))) {
      blocks.push({ t: 'ul', items: items.map((l) => parseInlines(l.replace(/^[-*]\s+/, ''))) });
      continue;
    }
    if (items.length && items.every((l) => /^\d+\.\s+\S/.test(l))) {
      blocks.push({ t: 'ol', items: items.map((l) => parseInlines(l.replace(/^\d+\.\s+/, ''))) });
      continue;
    }
    const head = /^(#{1,3})\s+(\S.*)$/.exec(chunk.trim());
    if (head && !chunk.includes('\n')) {
      const level = head[1].length as 1 | 2 | 3;
      const c = parseInlines(head[2]);
      if (hasInlines(c)) blocks.push({ t: 'h', level, c });
      continue;
    }
    const c = parseInlines(chunk);
    if (hasInlines(c)) blocks.push({ t: 'p', c });
  }
  return blocks;
}

export function parseRichText(source: string): Block[] {
  const raw = decodeEntities(repairUtf8Mojibake(source ?? ''));
  if (!raw.trim()) return [];
  try {
    return looksLikeHtml(raw) ? parseHtml(raw) : parseMarkdown(raw);
  } catch {
    const plain = raw.replace(/<[^>]+>/g, '').trim();
    const c = linkifyString(plain);
    return c.length ? [{ t: 'p', c }] : [];
  }
}

export function blockPlain(block: Block): string {
  const inlinePlain = (nodes: Inline[]): string => nodes.map((n) => {
    if (n.t === 'text' || n.t === 'code') return n.v;
    return inlinePlain(n.c);
  }).join('');
  if (block.t === 'ul' || block.t === 'ol') return block.items.map(inlinePlain).join('\n');
  return inlinePlain(block.c);
}
