// Private-event application queue. The owner and moderators see it.
// The public page does not.
import React, { useCallback, useState } from 'react';
import { Text, View } from 'react-native';
import { useFocusEffect } from 'expo-router';
import { OwnerFace } from './owner-face';
import { Button, EmptyState, ErrorText, SectionCard, StatusPill, styles } from './ui';
import { decideEventApplication, listEventApplications } from '../lib/events';
import { getProfiles } from '../lib/api';
import { fmtDate } from '../lib/format';
import type { EventApplication, EventApplicationStatus, Profile } from '../lib/types';

const STATUS_TONE: Record<EventApplicationStatus, 'info' | 'success' | 'danger'> = {
  pending: 'info',
  approved: 'success',
  declined: 'danger',
};

function byStatus(rows: EventApplication[]): EventApplication[] {
  const rank: Record<EventApplicationStatus, number> = { pending: 0, approved: 1, declined: 2 };
  return rows.slice().sort((a, b) => rank[a.status] - rank[b.status] || a.created_at.localeCompare(b.created_at));
}

export function EventApplications({ eventId }: { eventId: string }) {
  const [rows, setRows] = useState<EventApplication[] | null>(null);
  const [profiles, setProfiles] = useState<Record<string, Profile>>({});
  const [err, setErr] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);

  const load = useCallback(async () => {
    const next = await listEventApplications(eventId);
    setRows(byStatus(next));
    setProfiles(await getProfiles(next.map((row) => row.user_id)));
  }, [eventId]);

  useFocusEffect(useCallback(() => {
    let live = true;
    load().then(() => { if (live) setErr(null); }).catch((e: { message?: string }) => {
      if (live) setErr(e.message ?? 'Couldn’t load applications.');
    });
    return () => { live = false; };
  }, [load]));

  const decide = (userId: string, approve: boolean) => {
    setBusy(`${userId}:${approve ? 'yes' : 'no'}`);
    setErr(null);
    decideEventApplication(eventId, userId, approve)
      .then(load)
      .catch((e: { message?: string }) => setErr(e.message ?? 'Couldn’t update the application.'))
      .finally(() => setBusy(null));
  };

  return (
    <SectionCard title="Applications">
      <Text style={styles.body}>People who asked to attend. The owner and moderators see this queue. It isn’t on the public page. Approving adds a normal RSVP.</Text>
      <ErrorText>{err}</ErrorText>
      {!rows && !err ? <Text style={[styles.muted, { marginTop: 8 }]}>Loading…</Text> : null}
      {rows && rows.length === 0 ? <EmptyState icon="people-outline" title="No applications" body="They’ll show up here when someone applies." /> : null}
      <View style={{ marginTop: 8, gap: 12 }}>
        {rows?.map((row) => {
          const profile = profiles[row.user_id];
          const label = row.status === 'pending' ? 'Pending' : row.status === 'approved' ? 'Approved' : 'Declined';
          return (
            <View key={row.user_id} style={{ gap: 8 }}>
              <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
                {profile ? <OwnerFace profile={profile} /> : <Text style={styles.body}>Member</Text>}
                <StatusPill label={label} tone={STATUS_TONE[row.status]} />
              </View>
              <Text style={styles.muted}>{fmtDate(row.created_at)}</Text>
              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8 }}>
                {row.status !== 'approved' ? <Button small title="Approve" loading={busy === `${row.user_id}:yes`} onPress={() => decide(row.user_id, true)} /> : null}
                {row.status !== 'declined' ? <Button small variant="neutral" title="Decline" loading={busy === `${row.user_id}:no`} onPress={() => decide(row.user_id, false)} /> : null}
              </View>
            </View>
          );
        })}
      </View>
    </SectionCard>
  );
}
