import { Platform, Share } from 'react-native';
import { publicAppUrl } from './public-url';

function copyWithSelection(text: string): boolean {
  if (typeof document === 'undefined') return false;
  try {
    const el = document.createElement('textarea');
    el.value = text;
    el.setAttribute('readonly', 'true');
    el.style.position = 'fixed';
    el.style.top = '0';
    el.style.left = '-9999px';
    document.body.appendChild(el);
    el.focus();
    el.select();
    el.setSelectionRange(0, text.length);
    const ok = document.execCommand('copy');
    document.body.removeChild(el);
    return ok;
  } catch { return false; }
}

/** Copy or share the public URL for an app route (`/e/…`, `/g/…`). */
export function copyPublicPath(path: string): Promise<'copied' | 'shared' | 'dismissed'> {
  return copyOrShare(publicAppUrl(path));
}

/** Button title for that copy or share action. */
export function shareActionTitle(copied: boolean): string {
  return copied ? 'Copied' : Platform.OS === 'web' ? 'Copy link' : 'Share link';
}

/** Copy on web. Share sheet on native. */
export async function copyOrShare(url: string): Promise<'copied' | 'shared' | 'dismissed'> {
  if (Platform.OS === 'web') {
    // Selection copy stays inside the click gesture. The async clipboard API is the second try.
    if (copyWithSelection(url)) return 'copied';
    if (typeof navigator !== 'undefined' && navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(url);
      return 'copied';
    }
    throw new Error('Could not copy the link. Select it and copy it manually.');
  }
  const res = await Share.share({ message: url });
  return res.action === Share.dismissedAction ? 'dismissed' : 'shared';
}
