// Pure names for first-party app analytics. No React Native and no Supabase,
// so the screen-name rules can be checked without a device.

export const APP_EVENTS = ['screen_view', 'rsvp', 'open_chat', 'send_message', 'sync_meetup'] as const;
export type AppEventName = (typeof APP_EVENTS)[number];

export const APP_EVENT_LABELS: Record<AppEventName, string> = {
  screen_view: 'Screen views',
  rsvp: 'RSVPs',
  open_chat: 'Chats opened',
  send_message: 'Messages sent',
  sync_meetup: 'Meetup syncs',
};

const SCREEN_NAME = /^[a-z0-9_]{1,40}$/;

export type AppEventTotal = { name: string; count: number; people: number };

export type AppAnalyticsDay = {
  date: string;
  screen_view: number;
  rsvp: number;
  open_chat: number;
  send_message: number;
  sync_meetup: number;
};

export type AppAnalyticsSummary = {
  days: number;
  generatedAt: string;
  events: number;
  people: number;
  totals: AppEventTotal[];
  series: AppAnalyticsDay[];
  screens: { screen: string; views: number }[];
};

/** One event-page view, as app_analytics_event returns it to a moderator. */
export type EventAnalyticsView = {
  id: string;
  at: string;
  username: string | null;
  ip: string | null;
  city: string | null;
  region: string | null;
  country: string | null;
  deviceLatitude: number | null;
  deviceLongitude: number | null;
  device: string | null;
  browser: string | null;
  surface: string | null;
  platform: string | null;
  /** Set on a group analytics log row, so the view can name which event it was. */
  eventTitle?: string | null;
};

export type EventAnalyticsFunnel = {
  anonymousViews: number;
  authenticatedViews: number;
  rsvps: number;
};

export type EventAnalytics = {
  eventId: string;
  viewers: number;
  views: number;
  funnel: EventAnalyticsFunnel;
  /** Meetup YES count already shown on the event. Null when the event has no Meetup id. */
  meetupGoing: number | null;
  log: EventAnalyticsView[];
};

/** One club event inside a group analytics related list. Counts are app views and app RSVPs. */
export type GroupAnalyticsEvent = {
  id: string;
  title: string;
  startsAt: string | null;
  views: number;
  rsvps: number;
};

/**
 * Moderator funnel for one group. Views and RSVPs are that group's club events.
 * There is no Meetup member count on this object.
 */
export type GroupAnalytics = {
  groupId: string;
  events: number;
  viewers: number;
  views: number;
  funnel: EventAnalyticsFunnel;
  eventRows: GroupAnalyticsEvent[];
  log: EventAnalyticsView[];
};

const DEVICE_LABELS: Record<string, string> = {
  mobile: 'Mobile',
  tablet: 'Tablet',
  desktop: 'Desktop',
  bot: 'Bot',
};

/** @username when the view was signed in. Otherwise Anonymous. */
export function eventViewerLabel(username: string | null | undefined): string {
  const name = (username ?? '').trim().replace(/^@+/, '');
  return name ? `@${name}` : 'Anonymous';
}

function placePart(value: string | null | undefined): string {
  return (value ?? '').trim();
}

/** IP place, and device coordinates when the app already had them. */
export function eventViewPlace(row: {
  city?: string | null;
  region?: string | null;
  country?: string | null;
  deviceLatitude?: number | null;
  deviceLongitude?: number | null;
}): { ip: string | null; device: string | null } {
  const parts: string[] = [];
  for (const part of [placePart(row.city), placePart(row.region), placePart(row.country)]) {
    if (part && !parts.includes(part)) parts.push(part);
  }
  const lat = typeof row.deviceLatitude === 'number' ? row.deviceLatitude : Number(row.deviceLatitude);
  const lng = typeof row.deviceLongitude === 'number' ? row.deviceLongitude : Number(row.deviceLongitude);
  const hasDevice = row.deviceLatitude != null && row.deviceLongitude != null && Number.isFinite(lat) && Number.isFinite(lng);
  return {
    ip: parts.length ? parts.join(', ') : null,
    device: hasDevice ? `${lat.toFixed(2)}, ${lng.toFixed(2)}` : null,
  };
}

export function eventViewDetail(row: { device?: string | null; browser?: string | null; surface?: string | null; platform?: string | null }): string {
  const device = DEVICE_LABELS[(row.device ?? '').trim()] ?? null;
  const browser = (row.browser ?? '').trim() || null;
  const native = row.platform === 'ios' ? 'iOS' : row.platform === 'android' ? 'Android' : null;
  const surface = row.surface === 'public' ? 'Public page' : row.surface === 'app' ? 'Member page' : null;
  return [device, browser, native, surface].filter((part): part is string => !!part).join(' · ');
}

function num(v: unknown): number {
  const n = typeof v === 'number' ? v : Number(v);
  return Number.isFinite(n) ? n : 0;
}

function textOrNull(value: unknown): string | null {
  return typeof value === 'string' && value.trim() ? value : null;
}

/** One view-log row from app_analytics_event or app_analytics_group. */
export function eventAnalyticsView(raw: unknown): EventAnalyticsView | null {
  if (!raw || typeof raw !== 'object') return null;
  const row = raw as Record<string, unknown>;
  if (typeof row.id !== 'string' || typeof row.at !== 'string') return null;
  return {
    id: row.id,
    at: row.at,
    username: textOrNull(row.username),
    ip: textOrNull(row.ip),
    city: textOrNull(row.city),
    region: textOrNull(row.region),
    country: textOrNull(row.country),
    deviceLatitude: typeof row.deviceLatitude === 'number' ? row.deviceLatitude : null,
    deviceLongitude: typeof row.deviceLongitude === 'number' ? row.deviceLongitude : null,
    device: textOrNull(row.device),
    browser: textOrNull(row.browser),
    surface: textOrNull(row.surface),
    platform: textOrNull(row.platform),
    eventTitle: textOrNull(row.eventTitle),
  };
}

function readFunnel(funnel: EventAnalyticsFunnel): EventAnalyticsFunnel {
  return {
    anonymousViews: num(funnel.anonymousViews),
    authenticatedViews: num(funnel.authenticatedViews),
    rsvps: num(funnel.rsvps),
  };
}

function groupEventRow(raw: unknown): GroupAnalyticsEvent | null {
  if (!raw || typeof raw !== 'object') return null;
  const row = raw as Record<string, unknown>;
  if (typeof row.id !== 'string') return null;
  return {
    id: row.id,
    title: typeof row.title === 'string' && row.title.trim() ? row.title : 'Event',
    startsAt: textOrNull(row.startsAt),
    views: num(row.views),
    rsvps: num(row.rsvps),
  };
}

/** Moderator event funnel. Drops any extra keys, including a Meetup headcount if one were ever sent. meetupGoing stays: it is the listing's YES count, not a membership total. */
export function parseEventAnalytics(data: unknown, fallbackId: string): EventAnalytics {
  const body = (typeof data === 'string' ? JSON.parse(data) : data) as EventAnalytics | null;
  const funnel = body?.funnel;
  if (!body || !funnel || !Array.isArray(body.log)) {
    throw new Error('Event analytics returned an unexpected result.');
  }
  const meetup = body.meetupGoing;
  return {
    eventId: typeof body.eventId === 'string' ? body.eventId : fallbackId,
    viewers: num(body.viewers),
    views: num(body.views),
    funnel: readFunnel(funnel),
    meetupGoing: meetup == null ? null : num(meetup),
    log: body.log.map(eventAnalyticsView).filter((row): row is EventAnalyticsView => !!row),
  };
}

/** Moderator group funnel. Drops any extra keys, including a Meetup headcount if one were ever sent. */
export function parseGroupAnalytics(data: unknown, fallbackId: string): GroupAnalytics {
  const body = (typeof data === 'string' ? JSON.parse(data) : data) as GroupAnalytics | null;
  const funnel = body?.funnel;
  if (!body || !funnel || !Array.isArray(body.log) || !Array.isArray(body.eventRows)) {
    throw new Error('Group analytics returned an unexpected result.');
  }
  return {
    groupId: typeof body.groupId === 'string' ? body.groupId : fallbackId,
    events: num(body.events),
    viewers: num(body.viewers),
    views: num(body.views),
    funnel: readFunnel(funnel),
    eventRows: body.eventRows.map(groupEventRow).filter((row): row is GroupAnalyticsEvent => !!row),
    log: body.log.map(eventAnalyticsView).filter((row): row is EventAnalyticsView => !!row),
  };
}

const countFormat = new Intl.NumberFormat();

/** "N signed-in people. N views …" shared by event and group analytics. */
export function viewerCountSentence(viewers: number, views: number, where: string): string {
  const people = viewers === 1 ? 'person' : 'people';
  const viewWord = views === 1 ? 'view' : 'views';
  return `${countFormat.format(viewers)} signed-in ${people}. ${countFormat.format(views)} ${viewWord} ${where}`;
}

/** Drop route groups and ids so a screen view is "event", not a member's event uuid. */
export function screenNameFromPath(path: string): string {
  const parts = (path || '/')
    .split('?')[0]
    .split('#')[0]
    .split('/')
    .filter((part) => part && !part.startsWith('('));
  const [a, b, c] = parts;
  let name = 'screen';
  if (!a) name = 'home';
  else if (a === 'events' && !b) name = 'events';
  else if (a === 'events' && b === 'manage') name = 'event_edit';
  else if (a === 'events' && c === 'attend') name = 'event_attend';
  else if (a === 'events' && c === 'publish') name = 'event_publish';
  else if (a === 'events' && c === 'analytics') name = 'event_analytics';
  else if (a === 'events' && b) name = 'event';
  else if (a === 'e' && b) name = 'public_event';
  else if (a === 'groups' && !b) name = 'groups';
  else if (a === 'groups' && b === 'manage') name = 'group_edit';
  else if (a === 'groups' && c === 'publish') name = 'group_publish';
  else if (a === 'groups' && c === 'analytics') name = 'group_analytics';
  else if (a === 'groups' && b) name = 'group';
  else if (a === 'g' && b) name = 'public_group';
  else if (a === 'chat' && b === 'members') name = 'meetup_members';
  else if (a === 'chat') name = 'chat';
  else if (a === 'rooms' && b === 'manage') name = 'room_edit';
  else if (a === 'rooms' && b) name = 'chat_thread';
  else if (a === 'rooms') name = 'rooms';
  else if (a === 'me' && b === 'analytics') name = 'app_analytics';
  else if (a === 'me' || a === 'profile') name = 'profile';
  else if (a === 'sign-in') name = 'sign_in';
  else if (a === 'socrates') name = 'socrates';
  else if (a === 'guidelines') name = 'guidelines';
  else if (a === 'meetup' && b === 'member') name = 'meetup_member';
  else if (a === 'meetup' && b) name = 'meetup_event';
  else if (a === 'reports' && b) name = 'report';
  else if (a === 'reports') name = 'reports';
  else if (a === 'mod') name = 'moderation';
  else if (a === 'preview') name = 'preview';
  else if (a === 'members') name = 'members';
  else if (a === 'manage-rooms') name = 'manage_rooms';
  else if (a === 'auth-callback') name = 'auth_callback';
  else {
    const joined = parts
      .filter((part) => !/^[0-9a-f-]{8,}$/i.test(part) && !/^\d{4,}$/.test(part))
      .join('_')
      .toLowerCase()
      .replace(/[^a-z0-9_]+/g, '_')
      .replace(/^_+|_+$/g, '')
      .slice(0, 40);
    name = joined || 'screen';
  }
  return SCREEN_NAME.test(name) ? name : 'screen';
}

export function screenLabel(screen: string): string {
  return screen.replace(/_/g, ' ');
}

/** Always the five named events, in display order, even when a count is zero. */
export function namedEventTotals(rows: AppEventTotal[]): { name: AppEventName; label: string; count: number; people: number }[] {
  const byName = new Map(rows.map((row) => [row.name, row]));
  return APP_EVENTS.map((name) => {
    const row = byName.get(name);
    return { name, label: APP_EVENT_LABELS[name], count: num(row?.count), people: num(row?.people) };
  });
}

export function dailyEventTotals(series: AppAnalyticsDay[]): { date: string; total: number }[] {
  return series.map((day) => ({
    date: day.date,
    total: num(day.screen_view) + num(day.rsvp) + num(day.open_chat) + num(day.send_message) + num(day.sync_meetup),
  }));
}
