/** Digits printed in the magic-link email ("Or enter this code"). Supabase allows 6–10. */
export const EMAIL_CODE_MIN = 6;
export const EMAIL_CODE_MAX = 10;

/** Keep only the digits, so a paste of the whole email line still yields the code. */
export function emailCodeDigits(raw: string): string {
  return raw.replace(/\D/g, '').slice(0, EMAIL_CODE_MAX);
}

export function emailCodeReady(raw: string): boolean {
  const n = emailCodeDigits(raw).length;
  return n >= EMAIL_CODE_MIN && n <= EMAIL_CODE_MAX;
}
