// Meetup group urlname from a meetup.com URL. The edge functions use the same rules.

const URLNAME = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const RESERVED_URLNAME = new Set(['members', 'find', 'login', 'register', 'account', 'create', 'topics', 'cities', 'events', 'pro', 'apps', 'meta']);

export function normalizeGroupUrlname(raw: string | null | undefined): string | null {
  if (raw == null) return null;
  const s = raw.trim().toLowerCase();
  if (!s || s.length > 80 || !URLNAME.test(s)) return null;
  return s;
}

/** First path segment of an https meetup.com group URL. Null for member profiles and other hosts. */
export function meetupUrlname(url: string | null | undefined): string | null {
  if (!url) return null;
  let u: URL;
  try { u = new URL(url.trim()); } catch { return null; }
  if (u.protocol !== 'https:') return null;
  const host = u.hostname.toLowerCase();
  if (host !== 'www.meetup.com' && host !== 'meetup.com') return null;
  const seg = u.pathname.split('/').map((p) => p.trim().toLowerCase()).find(Boolean);
  if (!seg || seg.length > 80 || RESERVED_URLNAME.has(seg)) return null;
  return normalizeGroupUrlname(seg);
}

export type MeetupProGroup = { id: string; name: string; urlname: string };

/** Groups this person may connect Meetup Pro for. Moderators: every group with a Meetup URL. Owners: groups they own. */
export function meetupGroupsForPro(
  groups: { id: string; name: string; meetup_url: string | null; owner_id?: string | null }[],
  userId: string | null,
  isModerator: boolean,
): MeetupProGroup[] {
  const map = new Map<string, MeetupProGroup>();
  for (const g of groups) {
    if (!isModerator && (!userId || g.owner_id !== userId)) continue;
    const urlname = meetupUrlname(g.meetup_url);
    if (!urlname) continue;
    const prev = map.get(urlname);
    if (prev) prev.name = `${prev.name}, ${g.name}`;
    else map.set(urlname, { id: g.id, name: g.name, urlname });
  }
  return [...map.values()];
}
