export async function getRoom(id: string): Promise<Room | null> {
  if (isDemo()) {
    if (id.startsWith('dm-')) return { id, kind: 'dm', title: 'Direct message', description: '', meetup_url: null, starts_at: null, ends_at: null };
    return demoRooms.find((r) => r.id === id) ?? null;
  }
  const { data } = await supabase.from('rooms').select('*').eq('id', id).maybeSingle();
  return (data as Room) ?? null;
}

