/** Get-or-create the private thread with another member. */
export async function openDm(otherId: string): Promise<string> {
  if (!otherId) throw new Error('You can’t message this member.');
  if (isDemo()) {
    if (otherId === DEMO_ME) throw new Error('You can’t message yourself.');
    demoNoteDm(otherId);
    return `dm-${otherId}`;
  }
  const { data, error } = await supabase.rpc('open_dm', { other: otherId });
  if (error) throw new Error(explainChatError(`${error.message ?? ''} ${error.details ?? ''}`, 'Couldn’t open the conversation.'));
  return data as string;
}

