export async function getProfile(id: string, fresh = false): Promise<Profile | null> {
  if (isDemo()) return demoProfiles[id] ?? null;
  if (!fresh && profileCache.has(id)) return profileCache.get(id)!;
  const { data, error } = await supabase.from('profiles').select(PROFILE_COLS).eq('id', id).maybeSingle();
  if (error) throw error;
  if (!data) return null;
  const row = data as Profile;
  row.bio = row.bio ?? '';
  profileCache.set(id, row);
  return row;
}

/** Insert the signed-in member's profiles row when signup didn't. No-op if it already exists. */
export async function ensureMyProfile(): Promise<void> {
  if (isDemo()) return;
  const { error } = await supabase.rpc('ensure_my_profile');
  if (error) throw error;
  profileCache.clear();
}

export async function getProfiles(ids: string[]): Promise<Record<string, Profile>> {
  const out: Record<string, Profile> = {};
  if (isDemo()) { ids.forEach((i) => demoProfiles[i] && (out[i] = demoProfiles[i])); return out; }
  const missing = ids.filter((i) => !profileCache.has(i));
  if (missing.length) {
    const { data } = await supabase.from('profiles').select(PROFILE_COLS).in('id', missing);
    (data as Profile[] | null)?.forEach((p) => profileCache.set(p.id, p));
  }
  ids.forEach((i) => profileCache.has(i) && (out[i] = profileCache.get(i)!));
  return out;
}

export async function updateProfile(id: string, patch: Partial<Pick<Profile, 'username' | 'display_name' | 'bio' | 'avatar_path'>>) {
  if (isDemo()) { Object.assign(demoProfiles[DEMO_ME], patch); return; }
  const { error } = await supabase.from('profiles').update({ ...patch, updated_at: new Date().toISOString() }).eq('id', id);
  if (error) {
    if (error.code === '23505') throw new Error('That username is taken.');
    if (error.code === '23514') throw new Error('That username isn’t allowed (3–24 lowercase letters, numbers, underscores; some words are reserved).');
    throw error;
  }
  profileCache.delete(id);
}

