// Meetup photo fallback (signed-in only, via SECURITY DEFINER RPC). Batched + cached per profile id.
const meetupPhotoCache = new Map<string, string | null>();
const meetupPhotoWaiters = new Map<string, ((u: string | null) => void)[]>();
let meetupPhotoTimer: ReturnType<typeof setTimeout> | null = null;
export function cachedMeetupPhoto(id: string): string | null | undefined { return meetupPhotoCache.get(id); }
export function getMeetupPhoto(id: string): Promise<string | null> {
  if (isDemo()) return Promise.resolve(null);
  if (meetupPhotoCache.has(id)) return Promise.resolve(meetupPhotoCache.get(id)!);
  return new Promise((resolve) => {
    const w = meetupPhotoWaiters.get(id) ?? []; w.push(resolve); meetupPhotoWaiters.set(id, w);
    if (!meetupPhotoTimer) meetupPhotoTimer = setTimeout(flushMeetupPhotos, 30);
  });
}
async function flushMeetupPhotos() {
  meetupPhotoTimer = null;
  const batch = new Map(meetupPhotoWaiters); meetupPhotoWaiters.clear();
  const ids = [...batch.keys()];
  let found: Record<string, string> = {};
  let ok = true;
  try {
    const { data, error } = await supabase.rpc('meetup_avatar_urls', { ids });
    if (error) ok = false;
    for (const r of (data ?? []) as { profile_id: string; photo_url: string }[]) found[r.profile_id] = r.photo_url;
  } catch { ok = false; }
  for (const [id, ws] of batch) {
    const u = found[id] ?? null;
    if (ok) meetupPhotoCache.set(id, u);
    ws.forEach((f) => f(u));
  }
}

export function avatarUrl(path: string | null): string | null {
  if (!path) return null;
  return supabase.storage.from('avatars').getPublicUrl(path).data.publicUrl;
}

export async function uploadAvatar(userId: string, uri: string, mime = 'image/jpeg'): Promise<string> {
  const ext = mime.split('/')[1] ?? 'jpg';
  const path = `${userId}/avatar-${Date.now()}.${ext}`;
  const buf = await (await fetch(uri)).arrayBuffer();
  const { error } = await supabase.storage.from('avatars').upload(path, buf, { contentType: mime, upsert: true });
  if (error) throw error;
  return path;
}

