// ---- Meetup account linking (edge functions meetup-oauth-start / -disconnect)
// Returns the Meetup authorize URL, or null in demo mode (where it fakes a successful link).
export async function startMeetupLink(returnTo: string, groupUrlname?: string): Promise<string | null> {
  if (isDemo()) {
    if (!groupUrlname) Object.assign(demoProfiles[DEMO_ME], { meetup_name: 'Demo Member', meetup_profile_url: 'https://www.meetup.com/reading-philosophy/', meetup_is_member: true });
    return null;
  }
  const body: { return_to: string; group_urlname?: string } = { return_to: returnTo };
  if (groupUrlname) body.group_urlname = groupUrlname;
  const { data, error } = await supabase.functions.invoke('meetup-oauth-start', { body });
  if (error) {
    let msg = 'Couldn’t start Meetup sign-in.';
    if (error instanceof FunctionsHttpError) { try { const j = await error.context.json(); msg = j.message ?? msg; } catch {} }
    throw new Error(msg);
  }
  return data.url as string;
}
export async function disconnectMeetup(groupUrlname?: string) {
  if (isDemo()) {
    if (!groupUrlname) Object.assign(demoProfiles[DEMO_ME], { meetup_name: null, meetup_profile_url: null, meetup_is_member: false });
    return;
  }
  const { error } = await supabase.functions.invoke('meetup-oauth-disconnect', { body: groupUrlname ? { group_urlname: groupUrlname } : {} });
  if (error) {
    let msg = groupUrlname ? 'Couldn’t disconnect Meetup Pro.' : 'Couldn’t disconnect Meetup.';
    if (error instanceof FunctionsHttpError) { try { const j = await error.context.json(); msg = j.message ?? msg; } catch {} }
    throw new Error(msg);
  }
}

