/** Members whose name or username matches. Empty until there are two characters. */
export async function searchProfiles(query: string): Promise<Profile[]> {
  const q = query.trim().replace(/[^a-zA-Z0-9 _.'@-]/g, '').slice(0, 40);
  if (q.length < 2) return [];
  if (isDemo()) {
    const needle = q.toLowerCase();
    return Object.values(demoProfiles).filter((profile) => {
      if (profile.id === DEMO_ME) return false;
      return `${profile.display_name ?? ''} ${profile.username}`.toLowerCase().includes(needle);
    }).slice(0, 20);
  }
  const { data, error } = await supabase.from('profiles').select(PROFILE_COLS)
    .eq('is_banned', false)
    .or(`username.ilike.%${q}%,display_name.ilike.%${q}%`)
    .limit(20);
  if (error) throw error;
  return ((data ?? []) as Profile[]).map((profile) => ({ ...profile, bio: profile.bio ?? '' }));
}

