// Public group page helpers. No React Native and no Supabase.
// A sponsor link is an https URL with no embedded login.

export const PUBLIC_GROUP_PAGE_WIDTH = 1080;
/** Group cover and public event card images. 1200 by 675. */
export const PUBLIC_COVER_ASPECT = 1200 / 675;
/** Group page hero. Shorter than 1200 by 675, center-cropped, so the title sits higher. */
export const PUBLIC_GROUP_HERO_ASPECT = 2.4;

/** Name shown for a published group's owner. Null when the profile has no name. */
export function organizerLabel(row: { display_name?: string | null; username?: string | null }): string | null {
  const display = row.display_name?.trim();
  if (display) return display;
  const username = row.username?.trim().replace(/^@+/, '');
  if (username) return `@${username}`;
  return null;
}

/** https URL with no username or password. Anything else is not a sponsor link or image. */
export function safeSponsorUrl(url: string | null | undefined): string | null {
  if (!url) return null;
  const raw = url.trim();
  if (!raw || /\s/.test(raw)) return null;
  try {
    const u = new URL(raw);
    if (u.protocol !== 'https:') return null;
    if (u.username || u.password) return null;
    return u.toString();
  } catch {
    return null;
  }
}

export type GroupSponsorDraft = {
  title: string;
  body: string;
  image_url: string;
  link_url: string;
};

export type GroupSponsorFields = {
  title: string;
  body: string;
  image_url: string | null;
  link_url: string | null;
};

/** Fields stored on a sponsor row. Empty image and link stay null. */
export function sponsorInput(draft: GroupSponsorDraft): GroupSponsorFields {
  const title = draft.title.trim();
  if (!title) throw new Error('Title is required.');
  if (title.length > 160) throw new Error('Title is too long.');
  const body = draft.body.trim();
  if (body.length > 2000) throw new Error('Body is too long.');
  const image = draft.image_url.trim();
  const link = draft.link_url.trim();
  if (image && !safeSponsorUrl(image)) throw new Error('Image URL must be an https URL.');
  if (link && !safeSponsorUrl(link)) throw new Error('Link must be an https URL.');
  return {
    title,
    body,
    image_url: image ? safeSponsorUrl(image) : null,
    link_url: link ? safeSponsorUrl(link) : null,
  };
}
