// Moderator report list. Client gating only; RLS enforces access.
import { fullName } from '../lib/names';
import React, { useEffect, useState } from 'react';
import { Text } from 'react-native';
import { router } from 'expo-router';
import { Button, EmptyState, ErrorText, ListRow, ListView, StatusPill, Toolbar, styles, type Column } from './ui';
import { useSession } from '../lib/session';
import {
  getMessage, getProfiles, listOpenReports,
  type Report,
} from '../lib/api';
import type { Message, Profile } from '../lib/types';

export function useCanModerate() {
  const { userId, isModerator, loading, moderatorChecked, demo } = useSession();
  // Stay blank until the moderator check settles. Redirecting on the first
  // false would send a moderator away before the check returns.
  return { ready: !loading && moderatorChecked, ok: !!userId && isModerator && !demo, userId };
}

export function NotFound() {
  return <EmptyState icon="lock-closed-outline" title="Nothing here" action={<Button variant="neutral" small title="Back to chat" onPress={() => router.replace('/chat')} />} />;
}

// ---- Reports
export type ReportCtx = { report: Report; message: Message | null; people: Record<string, Profile>; target: string | null };
export async function loadReports(): Promise<ReportCtx[]> {
  const r = await listOpenReports();
  const m: Record<number, Message | null> = {};
  await Promise.all(r.filter((x) => x.message_id).map(async (x) => { m[x.message_id!] = await getMessage(x.message_id!); }));
  const ids = new Set<string>();
  r.forEach((x) => { ids.add(x.reporter_id); if (x.reported_user_id) ids.add(x.reported_user_id); });
  Object.values(m).forEach((x) => x && ids.add(x.user_id));
  const people = await getProfiles([...ids]);
  return r.map((report) => {
    const message = report.message_id ? m[report.message_id] ?? null : null;
    return { report, message, people, target: report.reported_user_id ?? message?.user_id ?? null };
  });
}

const REPORT_COLS: Column[] = [{ label: 'Reason', flex: 2 }, { label: 'About', flex: 1 }, { label: 'Type', width: 80 }, { label: 'Reported', width: 120 }];
export function ReportsList() {
  const [items, setItems] = useState<ReportCtx[] | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [q, setQ] = useState('');
  useEffect(() => { loadReports().then(setItems).catch((e) => setErr(e.message)); }, []);
  const shown = (items ?? []).filter((x) => !q.trim() || x.report.reason.toLowerCase().includes(q.trim().toLowerCase()));
  return (
    <>
      <ErrorText>{err}</ErrorText>
      <Toolbar search={q} onSearch={setQ} placeholder="Search reasons…" />
      <ListView title="Open reports" count={items?.length} columns={REPORT_COLS} loading={!items && !err}
        empty={<EmptyState icon="shield-checkmark-outline" title="No open reports" body="Reports from members show up here." />}>
        {shown.map((x) => (
          <ListRow key={x.report.id} columns={REPORT_COLS} onPress={() => router.push(`/reports/${x.report.id}`)}
            cells={[x.report.reason || '(no reason)', x.target ? fullName(x.people[x.target]) : '—',
              <StatusPill label={x.report.message_id ? 'Message' : 'Member'} tone="warning" />,
              <Text style={styles.rowCell}>{new Date(x.report.created_at).toLocaleDateString()}</Text>]} />
        ))}
      </ListView>
    </>
  );
}
