// Pure chat error and room-id helpers. No Supabase import, so tests can run in Node.

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const BLOCKED_LINE = 'You can’t message this member.';
const GENERIC_SEND = 'Message could not be sent.';

function oneParam(value: unknown): string {
  const raw = Array.isArray(value) ? (value.length === 1 ? value[0] : '') : value;
  return typeof raw === 'string' ? raw.trim() : '';
}

/**
 * Room id safe to load and to send.
 * Expo Router types a route param as `string | string[]`. A one-element array
 * still loads the thread (PostgREST stringifies it in `.eq`) but JSON-encodes
 * as an array. `RegExp.test` then coerces that array back to the uuid, and
 * `post_message` rejects it. The function answers `{ error: "server_error" }`
 * with no message, which the composer shows as the generic send failure.
 * Demo threads keep local ids (`dm-…`, `group-…`, `r-…`). Live rooms are uuids.
 */
export function threadRoomId(value: unknown): string {
  const id = oneParam(value);
  if (!id) return '';
  if (/^(dm|group|r)-[A-Za-z0-9_-]{1,80}$/.test(id)) return id;
  return UUID.test(id) ? id : '';
}

/** Live `post_message` only accepts a uuid. Demo ids are not sent to the function. */
export function chatRoomId(value: unknown): string {
  const id = threadRoomId(value);
  return UUID.test(id) ? id : '';
}

/** Map open_dm / post_message failures to a short line. Does not say which person blocked the other. */
export function explainChatError(message: string, fallback = 'Something went wrong.'): string {
  const m = message.toLowerCase();
  if (/open_dm|list_my_dms|schema cache/.test(m)) return 'Direct messages aren’t available yet.';
  if (m.includes('not_a_participant')) return 'You can’t message in this conversation.';
  if (m.includes('blocked') || m.includes('unavailable')) return BLOCKED_LINE;
  if (m.includes('bad_recipient')) return 'You can’t message yourself.';
  if (m.includes('user_not_found')) return 'That member isn’t on the app.';
  if (m.includes('banned')) return 'Your account can’t message right now. Contact the organizers.';
  if (m.includes('bad_length')) return 'Messages must be 1–2000 characters.';
  if (m.includes('rate_limited') || m.includes('slow down')) return 'Slow down a little — max 30 messages per minute.';
  if (m.includes('room_closed') || m.includes('isn\'t open') || m.includes('isn’t open')) return 'This chat hour isn’t open right now.';
  if (m.includes('room_not_found') || m.includes('room not found') || m.includes('bad_room')) return 'That conversation isn’t available.';
  return fallback;
}

function safeUserMessage(message: string): boolean {
  if (!message || message.length > 300) return false;
  if (/permission denied|stack trace|sqlstate|pgrst|jwt|service_role|syntax for type|password|secret/i.test(message)) return false;
  return true;
}

/**
 * Line for a failed moderate-message response.
 * Known codes win over a server `message` so a block stays anonymous.
 * A human `message` is kept when the code has no better line.
 */
export function explainSendFailure(
  payload: { error?: unknown; message?: unknown } | null | undefined,
  fallback = GENERIC_SEND,
): string {
  const code = typeof payload?.error === 'string' ? payload.error.trim().toLowerCase() : '';
  const serverMessage = typeof payload?.message === 'string' ? payload.message.trim() : '';
  if (code === 'blocked' || code === 'unavailable') return BLOCKED_LINE;
  if (code === 'rejected') return safeUserMessage(serverMessage) ? serverMessage : 'That message isn’t allowed.';
  if (code === 'unauthorized') return 'Sign in again to send a message.';
  const mapped = code ? explainChatError(code, '') : '';
  if (mapped) return mapped;
  if (safeUserMessage(serverMessage)) {
    const fromMessage = explainChatError(serverMessage, '');
    return fromMessage || serverMessage;
  }
  if (code === 'server_error') return 'Message could not be sent. Try again in a moment.';
  return fallback;
}
