// Shared Publish-to status. Events and groups use the same channel shape:
// unpublished / published / cancelled, and in sync when the sent version matches.

export const PUBLISH_CHANNELS: { channel: 'meetup' | 'web'; label: string }[] = [
  { channel: 'meetup', label: 'Meetup' },
  { channel: 'web', label: 'Web' },
];

export type PublicationLike = {
  status?: string | null;
  published_version?: number | null;
} | null | undefined;

export function channelLabel(channel: string) {
  return PUBLISH_CHANNELS.find((c) => c.channel === channel)?.label ?? channel;
}

export function publicationStatus(pub?: PublicationLike): { label: string; tone: 'default' | 'success' | 'danger' } {
  if (pub?.status === 'published') return { label: 'Published', tone: 'success' };
  if (pub?.status === 'cancelled') return { label: 'Cancelled', tone: 'danger' };
  return { label: 'Unpublished', tone: 'default' };
}

/** In sync / out of date apply only while the channel is published. */
export function publicationSync(currentVersion: number, pub?: PublicationLike): { label: string; tone: 'success' | 'warning' } | null {
  if (!pub || pub.status !== 'published') return null;
  if (pub.published_version != null && pub.published_version === currentVersion) return { label: 'In sync', tone: 'success' };
  return { label: 'Out of date', tone: 'warning' };
}

const PUBLICATION_TAIL = 'channel,status,published_version,published_at,snapshot,external_id,external_url,last_error,updated_at';

/** Select list for event_publications or group_publications. The owner column differs. */
export function publicationSelect(ownerColumn: 'event_id'): 'id,event_id,channel,status,published_version,published_at,snapshot,external_id,external_url,last_error,updated_at';
export function publicationSelect(ownerColumn: 'group_id'): 'id,group_id,channel,status,published_version,published_at,snapshot,external_id,external_url,last_error,updated_at';
export function publicationSelect(ownerColumn: 'event_id' | 'group_id'): string {
  return `id,${ownerColumn},${PUBLICATION_TAIL}`;
}

/** True only while a published channel is behind the record's current version. */
export function publicationOutOfDate(currentVersion: number, pub?: PublicationLike): boolean {
  return publicationSync(currentVersion, pub)?.label === 'Out of date';
}

/** Version sentence on a publish channel. Events and groups use the same wording. */
export function publishedVersionLine(record: 'club event' | 'club group', currentVersion: number, publishedVersion: number | null | undefined): string {
  if (publishedVersion != null) return `Sent version ${publishedVersion}. This ${record} is version ${currentVersion}.`;
  return `This ${record} is version ${currentVersion}. Nothing has been sent.`;
}

/** https Meetup URL on meetup.com. Other hosts are dropped. */
export function safeMeetupUrl(url: string | null | undefined): string | null {
  if (!url) return null;
  try {
    const u = new URL(url);
    if (u.protocol !== 'https:') return null;
    if (u.hostname !== 'www.meetup.com' && u.hostname !== 'meetup.com') return null;
    return u.toString();
  } catch { return null; }
}
